#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-only
"""ddk2kbuild.py -- convert Kleaf DDK BUILD.bazel back to Kbuild/Makefile.

The repository was migrated FROM classic Kbuild TO Kleaf DDK (``ddk_module``
in ``BUILD.bazel``).  The original ``Makefile``/``Kbuild`` files were deleted.
This tool reconstructs a *reviewable* Kbuild/Makefile skeleton from the DDK
declaration.

    Usage:
      python3 ddk2kbuild.py <BUILD.bazel path | directory> [options]
      python3 ddk2kbuild.py --all <root> [options]

    Options:
      --out DIR        write generated files under DIR (mirrors the package tree)
      --stdout         print generated files instead of writing them
      --dry-run        do everything except write files
      --write          (default) write files next to each BUILD.bazel
      --makefile       also emit a Makefile shim
      --legacy-kbuild  also emit a legacy Kbuild.<label> for multi-module dirs
      --walk-globs     expand **/*.c globs against the filesystem (opt-in, medium)
      --allow-lossy    allow writing low-confidence modules (default: refuse)
      --report FMT     text (default) or json
      --write-min-confidence LVL   high|medium|low (default: medium)
      --self-test      run build-in unit tests
      --verbose        extra diagnostics on stderr

Design
------
Three stages with a typed value model between parse and emit:

    Stage A  Lexer + recursive-descent parser  -> syntax tree (spans preserved)
    Stage B  Resolver                           -> typed value tree
                                                    (ValueKind + Confidence;
                                                     Error nodes carry reasons)
    Stage C  Rule registry emitter              -> list[Line] with provenance

Confidence is a lattice join (HIGH < MEDIUM < LOW < UNKNOWN) computed per node,
and the module's confidence is the *min* over every emitted line.  Every line
records ``origin`` (BUILD.bazel:LINE) so the report can name exactly which
emitted line dragged a module down.

Pure Python 3.8+ standard library.  No Bazel, no third-party packages.
Single file on purpose: it is copied into a kernel checkout and run there.

Layout (search for the `# Stage` banners)
------------------------------------------
    Constants / Small helpers      shared enums, confidence lattice, tiny utils
    Stage A1  Lexer                Starlark-subset tokenizer
    Stage A2  Syntax tree          recursive-descent parser
    Stage A3  File-level parse     assigns / calls / loads / defs
    Stage B1  Typed value model    VStr / VList / VSelect / VGlob / VError
    Stage B2  .bzl loader          three-tier symbol resolver + evaluator
    Stage B3  Resolver             BUILD syntax tree -> typed values
    Read/parse memoization         process-lifetime file & scan caches
    Stage C1  Line / provenance    dependency classification
    Stage C2  Module model         rule registry, emitters
    Stage C3  Post-emit validator  rejects invalid Kbuild before writing
    Rendering                      whole-file emitters, 80-column wrapping
    CLI                            Opts, argparse, reports, main
"""

from __future__ import annotations

import argparse
import fnmatch
import json
import os
import re
import sys
import textwrap

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

TOOL = "ddk2kbuild.py"
BANNER = "# AUTO-GENERATED by ddk2kbuild.py from BUILD.bazel -- REVIEW REQUIRED"
# One-shot notice for an in-place tree-wide write (avoids N duplicate lines).
_INPLACE_NOTED = False

# Confidence lattice.  Higher value == less trustworthy.
C_HIGH, C_MEDIUM, C_LOW, C_UNKNOWN = 0, 1, 2, 3
CONF_NAME = {C_HIGH: "high", C_MEDIUM: "medium", C_LOW: "low", C_UNKNOWN: "unknown"}
CONF_ORDER = {"high": C_HIGH, "medium": C_MEDIUM, "low": C_LOW, "unknown": C_UNKNOWN}

# Value provenance triad.
VK_LITERAL = "LITERAL"            # fully known at load time
VK_COMPUTED = "COMPUTED"          # computed from known inputs
VK_ENV_DEPENDENT = "ENV_DEPENDENT"  # select()/glob()/native.* -- build-graph driven

MAX_NEST = 256          # bracket nesting cap
BZ_WALK_STEPS = 200000  # tree-walking evaluator step budget
BZ_WALK_DEPTH = 64      # evaluator recursion cap

DDK_RULES = (
    "ddk_module",
    "ddk_submodule",
    "ddk_library",
    "ddk_headers",
    "ddk_uapi_headers",
    "ddk_config",
    "ddk_prebuilt_module",
    "ddk_prebuilt_object",
    "kernel_module_group",
    "kernel_module",
)

# Attributes whose value is a *list of self-contained source files*.
SRC_ATTRS = ("srcs", "conditional_srcs")
# Attributes that are pure include-path providers in Kbuild.
INCLUDE_ATTRS = ("includes", "linux_includes")

# ASCII control characters that would break the lexical scan.
for _c in range(0x20):
    if _c not in (0x09, 0x0A, 0x0D):
        pass  # handled defensively in the lexer, not at import time


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def warn_msg(msg):
    sys.stderr.write("%s: warning: %s\n" % (TOOL, msg))


def info_msg(msg):
    sys.stderr.write("%s: %s\n" % (TOOL, msg))


# ---------------------------------------------------------------------------
# Stage A1 -- Lexer
# ---------------------------------------------------------------------------

class ParseError(Exception):
    def __init__(self, msg, line=0, col=0):
        Exception.__init__(self, msg)
        self.msg = msg
        self.line = line
        self.col = col


# Token kinds
T_STRING = "STRING"
T_NUMBER = "NUMBER"
T_NAME = "NAME"
T_PUNCT = "PUNCT"
T_NEWLINE = "NEWLINE"
T_INDENT = "INDENT"
T_DEDENT = "DEDENT"
T_EOF = "EOF"

_STRING_PREFIXES = ("r", "b", "u", "rb", "br", "Rb", "bR", "rB", "Br", "f", "rf", "fr")
_PUNCT3 = ("**=", "//=", "<<=", ">>=")
_PUNCT2 = (
    "==", "!=", "<=", ">=", "//", "**", "<<", ">>", "+=", "-=", "*=", "/=",
    "%=", "|=", "&=", "^=", "->",
)
_PUNCT1 = "()[]{},:.=+-*/%|&^~<>@;"


class Token(object):
    __slots__ = ("kind", "value", "line", "col", "end_line", "end_col", "raw")

    def __init__(self, kind, value, line, col, end_line, end_col, raw):
        self.kind = kind
        self.value = value
        self.line = line
        self.col = col
        self.end_line = end_line
        self.end_col = end_col
        self.raw = raw

    def is_punct(self, v):
        return self.kind == T_PUNCT and self.value == v

    def is_name(self, v=None):
        return self.kind == T_NAME and (v is None or self.value == v)

    def __repr__(self):
        return "Token(%s,%r@%d:%d)" % (self.kind, self.value, self.line, self.col)


def _read_string(text, i, n):
    """Read one string literal starting at text[i] (the quote char).

    Returns (value, j, unterminated).  Handles ''', \"\"\", escapes and string
    prefixes.  Never raises: an unterminated literal yields what was read.
    """
    quote = text[i]
    if text.startswith(quote * 3, i):
        delim = quote * 3
        j = i + 3
        buf = []
        while j < n:
            if text.startswith(delim, j):
                return "".join(buf), j + 3, False
            ch = text[j]
            if ch == "\\" and j + 1 < n:
                esc = text[j + 1]
                buf.append(_unescape(esc))
                j += 2
                continue
            buf.append(ch)
            j += 1
        return "".join(buf), n, True
    j = i + 1
    buf = []
    while j < n:
        ch = text[j]
        if ch == "\\" and j + 1 < n:
            buf.append(_unescape(text[j + 1]))
            j += 2
            continue
        if ch == quote:
            return "".join(buf), j + 1, False
        if ch == "\n":
            # Unterminated single-line string: stop at the newline.
            return "".join(buf), j, True
        buf.append(ch)
        j += 1
    return "".join(buf), n, True


def _unescape(ch):
    return {"n": "\n", "t": "\t", "r": "\r", "0": "\0",
            "\\": "\\", "'": "'", '"': '"'}.get(ch, "\\" + ch)


def tokenize(text):
    """Tokenize Starlark-ish source into a flat token list.

    Totality contract: for *any* byte string this returns a token list.  It
    never raises.  Unknown bytes become PUNCT tokens (self-synchronizing).
    Emits INDENT/DEDENT/NEWLINE so that multi-line call arguments are handled
    naturally by the parser (newlines inside brackets are suppressed here).
    """
    tokens = []
    i = 0
    n = len(text)
    depth = 0
    indent_stack = [0]
    at_line_start = True
    line = 1
    col = 0
    warnings = []

    def push(kind, value, ln, cl, eln, ecl, raw):
        tokens.append(Token(kind, value, ln, cl, eln, ecl, raw))

    while i < n:
        ch = text[i]

        if at_line_start and depth == 0:
            # Measure indentation.  Tabs count as 8 columns (CPython rule).
            start = i
            width = 0
            while i < n and text[i] in (" ", "\t"):
                width = width + 8 - (width % 8) if text[i] == "\t" else width + 1
                i += 1
            if i < n and text[i] == "#":
                while i < n and text[i] != "\n":
                    i += 1
                continue
            if i < n and text[i] == "\n":
                i += 1
                line += 1
                col = 0
                continue
            if i >= n:
                break
            prev = indent_stack[-1]
            if width > prev:
                indent_stack.append(width)
                push(T_INDENT, width, line, 0, line, width, text[start:i])
            else:
                while len(indent_stack) > 1 and width < indent_stack[-1]:
                    indent_stack.pop()
                    push(T_DEDENT, width, line, 0, line, width, "")
            at_line_start = False
            col = width
            continue

        at_line_start = False

        # Whitespace / line continuation
        if ch in (" ", "\t", "\r"):
            i += 1
            col += 1
            continue
        if ch == "\\" and i + 1 < n and text[i + 1] == "\n":
            i += 2
            line += 1
            col = 0
            at_line_start = True
            continue

        if ch == "\n":
            if depth == 0:
                push(T_NEWLINE, "\n", line, col, line, col + 1, "\n")
            i += 1
            line += 1
            col = 0
            at_line_start = True
            continue

        if ch == "#":
            start = i
            while i < n and text[i] != "\n":
                i += 1
            continue

        # Strings (with optional prefix)
        qpos = None
        if ch in ("'", '"'):
            qpos = i
        elif ch.isalpha():
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            word = text[i:j]
            if word.lower() in ("r", "b", "u", "rb", "br", "f", "rf", "fr") and j < n \
                    and text[j] in ("'", '"'):
                qpos = j
                i = j
        if qpos is not None:
            value, end, unterminated = _read_string(text, qpos, n)
            raw = text[i:end] if qpos == i else text[i:end]
            if unterminated:
                warnings.append("line %d: unterminated string literal" % line)
            push(T_STRING, value, line, col, line, col + (end - i), raw)
            # Recovery: a single-quote literal that hit a newline must not
            # swallow the rest of the file.
            for c in text[i:end]:
                if c == "\n":
                    line += 1
                    col = 0
                else:
                    col += 1
            i = end
            continue

        # Numbers
        if ch.isdigit():
            j = i
            while j < n and (text[j].isalnum() or text[j] in ("_", ".")):
                j += 1
            push(T_NUMBER, text[i:j], line, col, line, col + (j - i), text[i:j])
            col += j - i
            i = j
            continue

        # Names / keywords
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            push(T_NAME, text[i:j], line, col, line, col + (j - i), text[i:j])
            col += j - i
            i = j
            continue

        # Punctuation
        three = text[i:i + 3]
        if three in _PUNCT3:
            push(T_PUNCT, three, line, col, line, col + 3, three)
            i += 3
            col += 3
            continue
        two = text[i:i + 2]
        if two in _PUNCT2:
            push(T_PUNCT, two, line, col, line, col + 2, two)
            i += 2
            col += 2
            continue
        if ch in _PUNCT1:
            push(T_PUNCT, ch, line, col, line, col + 1, ch)
            if ch in "([{":
                depth += 1
            elif ch in ")]}":
                depth = max(0, depth - 1)
            i += 1
            col += 1
            continue

        # Unknown byte: skip it but keep scanning.
        push(T_PUNCT, ch, line, col, line, col + 1, ch)
        i += 1
        col += 1

    while len(indent_stack) > 1:
        indent_stack.pop()
        push(T_DEDENT, 0, line, col, line, col, "")
    push(T_EOF, None, line, col, line, col, "")
    return tokens, warnings


# ---------------------------------------------------------------------------
# Stage A2 -- Syntax tree
# ---------------------------------------------------------------------------

class SNode(object):
    """A syntax node.  ``kind`` is one of the closed set below.

    str      -> value is a str
    num      -> value is the literal text
    bool     -> value is True/False
    none     -> value is None
    name     -> value is the identifier
    list     -> args: [SNode]
    tuple    -> args: [SNode]
    dict     -> args: [ (key SNode, value SNode) ]
    call     -> value: callee name (str) or None, args: [SNode],
                kwargs: OrderedDict[str, SNode]
    attr     -> value: base SNode, args: [attr-name str]
    index    -> value: base SNode, args: [index SNode]
    binop    -> value: op string, args: [left, right]
    unop     -> value: op string, args: [operand]
    lambda   -> args: [(params, body SNode)]
    comp     -> args: [(elt SNode, [{target, iter}...])]  list/dict comprehension
    unknown  -> raw text we could not parse
    """

    __slots__ = ("kind", "value", "args", "kwargs", "line", "col", "raw")

    def __init__(self, kind, value=None, args=None, kwargs=None,
                 line=0, col=0, raw=""):
        self.kind = kind
        self.value = value
        self.args = args if args is not None else []
        self.kwargs = kwargs if kwargs is not None else {}
        self.line = line
        self.col = col
        self.raw = raw

    def __repr__(self):
        return "SNode(%s,%r,line=%d)" % (self.kind, self.value, self.line)


class Statement(object):
    """One top-level statement.

    kind: 'assign' | 'expr' | 'load' | 'def' | 'if' | 'for' | 'return' |
          'error' | 'pass'
    """

    __slots__ = ("kind", "name", "node", "targets", "line", "raw",
                 "params", "body", "loads")

    def __init__(self, kind, name=None, node=None, line=0, raw="",
                 params=None, body=None, loads=None, targets=None):
        self.kind = kind
        self.name = name
        self.node = node
        self.line = line
        self.raw = raw
        self.params = params or []
        self.body = body or []
        self.loads = loads or []
        self.targets = targets or []


class ParsedFile(object):
    __slots__ = ("path", "statements", "assigns", "calls", "loads",
                 "fn_defs", "warnings", "error_stmts", "source")

    def __init__(self, path):
        self.path = path
        self.statements = []
        self.assigns = {}
        self.calls = []
        self.loads = []          # list of (bzl_label, [(local, orig), ...], line)
        self.fn_defs = {}
        self.warnings = []
        self.error_stmts = []
        self.source = ""


class Parser(object):
    def __init__(self, tokens, path="<string>"):
        self.toks = tokens
        self.pos = 0
        self.path = path
        self.warnings = []
        self.depth = 0

    # -- token plumbing ----------------------------------------------------
    def peek(self, k=0):
        i = self.pos + k
        if i >= len(self.toks):
            return self.toks[-1]
        return self.toks[i]

    def at(self, kind, value=None):
        t = self.peek()
        return t.kind == kind and (value is None or t.value == value)

    def advance(self):
        t = self.peek()
        if t.kind != T_EOF:
            self.pos += 1
        return t

    def expect(self, value):
        t = self.peek()
        if t.kind == T_PUNCT and t.value == value:
            return self.advance()
        if t.kind == T_NAME and t.value == value:
            return self.advance()
        raise ParseError("expected %r, got %r" % (value, t.value or t.kind),
                         t.line, t.col)

    def skip_newlines(self):
        while self.peek().kind in (T_NEWLINE, T_INDENT, T_DEDENT):
            self.advance()

    # -- statements --------------------------------------------------------
    def parse_file(self):
        stmts = []
        while not self.at(T_EOF):
            t = self.peek()
            if t.kind in (T_NEWLINE, T_INDENT, T_DEDENT):
                self.advance()
                continue
            start_pos = self.pos
            stmt = None
            try:
                stmt = self.parse_statement()
            except ParseError as exc:
                stmt = None
                self.warnings.append("line %d: %s" % (exc.line or t.line, exc.msg))
            if stmt is None:
                raw = self._recover_statement(start_pos)
                stmts.append(Statement("error", line=t.line, raw=raw))
                continue
            stmts.append(stmt)
        return stmts

    def _recover_statement(self, start_pos):
        """Panic mode: consume to the next bracket-depth-0 statement boundary.

        Forward progress is guaranteed: at least one token is consumed, so a
        file whose tail is unparseable can never trap the parser in a loop or
        lose the well-formed statements that came before it.
        """
        depth = 0
        out = []
        while not self.at(T_EOF):
            t = self.peek()
            if depth == 0 and t.kind == T_NEWLINE and self.pos > start_pos:
                self.advance()
                break
            if t.kind == T_PUNCT and t.value in "([{":
                depth += 1
            elif t.kind == T_PUNCT and t.value in ")]}":
                depth = max(0, depth - 1)
            out.append(t.raw if t.raw else (
                t.value if isinstance(t.value, str) else ""))
            self.advance()
        return "".join(out).strip()

    def parse_statement(self):
        t = self.peek()
        if t.kind == T_NAME and t.value == "load" and self.peek(1).is_punct("("):
            return self.parse_load()
        if t.kind == T_NAME and t.value == "def":
            return self.parse_def()
        if t.kind == T_NAME and t.value == "return":
            self.advance()
            node = None
            if self.peek().kind not in (T_NEWLINE, T_DEDENT, T_EOF):
                node = self.parse_expr()
            self._end_stmt()
            return Statement("return", node=node, line=t.line)
        if t.kind == T_NAME and t.value == "pass":
            self.advance()
            self._end_stmt()
            return Statement("pass", line=t.line)
        if t.kind == T_NAME and t.value in ("if", "elif", "else", "for", "while"):
            return self.parse_compound()
        if t.kind == T_NAME and t.value in ("break", "continue"):
            self.advance()
            self._end_stmt()
            return Statement("pass", line=t.line)

        # NAME '=' expr  -> assignment (only plain '=' occurs in the corpus)
        if t.kind == T_NAME and self.peek(1).is_punct("=") \
                and not self.peek(1).is_punct("=="):
            name = self.advance().value
            self.expect("=")
            node = self.parse_expr()
            self._end_stmt()
            return Statement("assign", name=name, node=node, line=t.line)

        # Comprehension-form assignment: names = [x for x in xs]
        node = self.parse_expr()
        self._end_stmt()
        if t.kind == T_NAME:
            # a bare name expression statement (e.g. inside a def body)
            return Statement("expr", node=node, line=t.line)
        return Statement("expr", node=node, line=t.line)

    def _end_stmt(self):
        # Only NEWLINEs are consumed here.  INDENT/DEDENT are structural and
        # must reach the enclosing parse_block, otherwise block boundaries are
        # destroyed and a whole file collapses into one statement.
        while self.peek().kind == T_NEWLINE:
            self.advance()

    def parse_load(self):
        t = self.advance()  # 'load'
        self.expect("(")
        args = self.parse_args(terminator=")")
        bzl_node = None
        pairs = []
        for a in args:
            # parse_args yields ('pos', node) | ('kw', name, node)
            node = a[2] if a[0] == "kw" else a[1]
            if a[0] == "kw":
                # load(":f.bzl", local = "orig")
                if node.kind == "str":
                    pairs.append((a[1], node.value))
                else:
                    pairs.append((a[1], a[1]))
            elif node.kind == "str":
                # positional: the first positional is the .bzl label; the
                # rest are `load(":f.bzl", "sym")` re-exports
                if bzl_node is None:
                    bzl_node = node
                else:
                    pairs.append((node.value, node.value))
        bzl_label = bzl_node.value if bzl_node is not None else ""
        self._end_stmt()
        return Statement("load", loads=[(bzl_label, pairs)], line=t.line)

    def parse_compound(self):
        """Parse if/elif/else/for/while with an indented (or 1-line) body.

        Represented as a statement whose `body` is a list of clause dicts so
        the evaluator can walk it.  All clauses live on the same Statement so
        `if/elif/else` stays one unit.
        """
        t = self.peek()
        clauses = []
        while True:
            head = self.peek()
            if head.kind != T_NAME or head.value not in ("if", "elif", "else",
                                                         "for", "while"):
                break
            kw = self.advance().value
            cond = None
            target = None
            if kw in ("if", "elif"):
                cond = self.parse_expr()
            elif kw == "while":
                cond = self.parse_expr()
            elif kw == "for":
                target = self.parse_expr()
                if not self.at(T_NAME, "in"):
                    raise ParseError("expected 'in' in for", self.peek().line,
                                     self.peek().col)
                self.advance()
                iterable = self.parse_expr()
                target = (target, iterable)
            self.expect(":")
            body = self.parse_block()
            clauses.append({"kw": kw, "cond": cond, "target": target,
                            "body": body})
            # Look ahead for elif/else continuing *this* chain.  The peek is
            # strictly non-destructive: it inspects tokens without moving the
            # cursor, so a DEDENT (end of chain, or end of an enclosing block)
            # is never swallowed.
            j = self.pos
            while j < len(self.toks) and self.toks[j].kind == T_NEWLINE:
                j += 1
            nxt = self.toks[j] if j < len(self.toks) else self.toks[-1]
            if not (nxt.kind == T_NAME and nxt.value in ("elif", "else")):
                break
            while self.peek().kind == T_NEWLINE:
                self.advance()
        return Statement("compound", line=t.line, body=clauses)

    def parse_def(self):
        t = self.advance()  # 'def'
        name_tok = self.peek()
        if name_tok.kind != T_NAME:
            raise ParseError("expected function name", name_tok.line, name_tok.col)
        name = self.advance().value
        self.expect("(")
        params = []
        if not self.at(T_PUNCT, ")"):
            while True:
                pt = self.peek()
                if pt.kind == T_NAME:
                    pname = self.advance().value
                    default = None
                    if self.at(T_PUNCT, "="):
                        self.advance()
                        default = self.parse_expr()
                    params.append((pname, default))
                elif pt.is_punct("*") or pt.is_punct("**"):
                    self.advance()
                    continue
                else:
                    break
                if self.at(T_PUNCT, ","):
                    self.advance()
                    continue
                break
        self.expect(")")
        self.expect(":")
        body = self.parse_block()
        return Statement("def", name=name, params=params, body=body, line=t.line)

    def parse_block(self):
        """Parse an indented block after a ':'."""
        stmts = []
        saw_indent = False
        while self.peek().kind == T_NEWLINE:
            self.advance()
        if self.peek().kind == T_INDENT:
            self.advance()
            saw_indent = True
        else:
            # one-liner body: `if x: return y`
            try:
                stmts.append(self.parse_statement())
            except ParseError as exc:
                self.warnings.append("line %d: %s" % (exc.line, exc.msg))
            return stmts
        while True:
            # A block ends at the matching DEDENT (or EOF).  Blank lines and
            # newlines inside the block are skipped, but an INDENT token means
            # a *nested* block that the recursive call already consumed, so it
            # must never be skipped here -- doing so would swallow the rest of
            # the file into this block.
            while self.peek().kind == T_NEWLINE:
                self.advance()
            if self.at(T_EOF):
                break
            if self.peek().kind == T_DEDENT:
                self.advance()
                break
            try:
                stmts.append(self.parse_statement())
            except ParseError as exc:
                self.warnings.append("line %d: %s" % (exc.line, exc.msg))
                self._recover_statement(self.pos)
        return stmts

    # -- expressions -------------------------------------------------------
    def parse_expr(self):
        self.depth += 1
        if self.depth > MAX_NEST:
            self.depth -= 1
            raise ParseError("expression nesting too deep", self.peek().line,
                             self.peek().col)
        try:
            return self._parse_expr_inner()
        finally:
            self.depth -= 1

    def _parse_expr_inner(self):
        left = self.parse_binary(0)
        # ternary:  a if cond else b
        if self.peek().is_name("if"):
            self.advance()
            cond = self.parse_binary(0)
            if self.peek().is_name("else"):
                self.advance()
                other = self.parse_expr()
                return SNode("ternary", args=[cond, left, other],
                             line=left.line, col=left.col,
                             raw=left.raw)
            raise ParseError("ternary without else", self.peek().line, self.peek().col)
        return left

    # Precedence, loosest first (matches Python/Starlark).
    _BINOPS = [
        ("or",), ("and",), ("in", "not in"),
        ("==", "!=", "<", ">", "<=", ">="),
        ("|",), ("^",), ("&",), ("<<", ">>"),
        ("+", "-"), ("*", "/", "//", "%"), ("**",),
    ]

    def parse_binary(self, level):
        if level >= len(self._BINOPS):
            return self.parse_unary()
        left = self.parse_binary(level + 1)
        ops = self._BINOPS[level]
        while True:
            t = self.peek()
            if t.kind == T_PUNCT and t.value in ops:
                self.advance()
                right = self.parse_binary(level + 1)
                left = SNode("binop", value=t.value, args=[left, right],
                             line=left.line, col=left.col,
                             raw=(left.raw or "") + t.value + (right.raw or ""))
                continue
            if t.kind == T_NAME and t.value in ops:
                self.advance()
                right = self.parse_binary(level + 1)
                left = SNode("binop", value=t.value, args=[left, right],
                             line=left.line, col=left.col, raw=left.raw)
                continue
            if t.kind == T_NAME and t.value == "in":
                self.advance()
                right = self.parse_binary(level + 1)
                left = SNode("binop", value="in", args=[left, right],
                             line=left.line, col=left.col, raw=left.raw)
                continue
            if t.kind == T_NAME and t.value == "not" and self.peek(1).is_name("in"):
                self.advance()
                self.advance()
                right = self.parse_binary(level + 1)
                left = SNode("binop", value="not in", args=[left, right],
                             line=left.line, col=left.col, raw=left.raw)
                continue
            break
        return left

    def parse_unary(self):
        t = self.peek()
        if t.kind == T_PUNCT and t.value in ("-", "+", "~"):
            self.advance()
            operand = self.parse_unary()
            return SNode("unop", value=t.value, args=[operand], line=t.line,
                         col=t.col, raw=t.value + (operand.raw or ""))
        if t.kind == T_NAME and t.value == "not":
            self.advance()
            operand = self.parse_unary()
            return SNode("unop", value="not", args=[operand], line=t.line, col=t.col)
        if t.kind == T_NAME and t.value == "lambda":
            self.advance()
            params = []
            while self.peek().kind == T_NAME and not self.peek().is_punct(":"):
                params.append(self.advance().value)
                if self.at(T_PUNCT, ","):
                    self.advance()
                else:
                    break
            self.expect(":")
            body = self.parse_expr()
            return SNode("lambda", args=[(params, body)], line=t.line, col=t.col)
        return self.parse_postfix()

    def parse_postfix(self):
        node = self.parse_primary()
        while True:
            t = self.peek()
            if t.is_punct("("):
                # call on an arbitrary callee (attribute / index / name)
                self.advance()
                kwargs, args = self.parse_call_parts()
                node = SNode("call", value=node, args=args, kwargs=kwargs,
                             line=node.line, col=node.col,
                             raw=self._raw_span(node.line))
                continue
            if t.is_punct("."):
                self.advance()
                at = self.peek()
                if at.kind != T_NAME:
                    raise ParseError("expected attribute name", at.line, at.col)
                self.advance()
                node = SNode("attr", value=node, args=[at.value],
                             line=node.line, col=node.col,
                             raw=self._raw_span(node.line))
                continue
            if t.is_punct("["):
                self.advance()
                idx = self.parse_expr()
                self.expect("]")
                node = SNode("index", value=node, args=[idx],
                             line=node.line, col=node.col,
                             raw=self._raw_span(node.line))
                continue
            break
        return node

    def _raw_span(self, line):
        return ""

    def parse_primary(self):
        t = self.peek()
        if t.kind == T_STRING:
            self.advance()
            return SNode("str", value=t.value, line=t.line, col=t.col, raw=t.raw)
        if t.kind == T_NUMBER:
            self.advance()
            return SNode("num", value=t.value, line=t.line, col=t.col, raw=t.raw)
        if t.kind == T_NAME:
            if t.value == "True":
                self.advance()
                return SNode("bool", value=True, line=t.line, col=t.col, raw=t.raw)
            if t.value == "False":
                self.advance()
                return SNode("bool", value=False, line=t.line, col=t.col, raw=t.raw)
            if t.value == "None":
                self.advance()
                return SNode("none", value=None, line=t.line, col=t.col, raw=t.raw)
            if t.value == "not":
                return self.parse_unary()
            self.advance()
            return SNode("name", value=t.value, line=t.line, col=t.col, raw=t.raw)
        if t.is_punct("["):
            return self.parse_list_literal()
        if t.is_punct("{"):
            return self.parse_dict_literal()
        if t.is_punct("("):
            return self.parse_paren()
        if t.is_punct("*") or t.is_punct("**"):
            # *args / **kwargs in a call; represent as a positional marker
            self.advance()
            inner = self.parse_expr()
            return SNode("star", value=t.value, args=[inner], line=t.line, col=t.col)
        raise ParseError("unexpected token %r" % (t.value or t.kind,), t.line, t.col)

    def parse_paren(self):
        t = self.expect("(")
        if self.at(T_PUNCT, ")"):
            self.advance()
            return SNode("tuple", args=[], line=t.line, col=t.col, raw="()")
        first = self.parse_expr()
        if self.at(T_PUNCT, ","):
            items = [first]
            while self.at(T_PUNCT, ","):
                self.advance()
                if self.at(T_PUNCT, ")"):
                    break
                items.append(self.parse_expr())
            self.expect(")")
            return SNode("tuple", args=items, line=t.line, col=t.col, raw="")
        self.expect(")")
        return first

    def parse_list_literal(self):
        t = self.expect("[")
        items = self._parse_seq(terminator="]")
        # list comprehension:  [elt for x in xs if cond]
        if self.at(T_NAME, "for"):
            comp = self._parse_comprehension()
            self.expect("]")
            return SNode("comp", value="list", args=[items[0] if items else None,
                                                     comp], line=t.line, col=t.col)
        return SNode("list", args=items, line=t.line, col=t.col, raw="")

    def parse_dict_literal(self):
        t = self.expect("{")
        pairs = []
        while not self.at(T_PUNCT, "}"):
            if self.at(T_EOF):
                raise ParseError("unterminated dict", t.line, t.col)
            k = self.parse_expr()
            self.expect(":")
            v = self.parse_expr()
            pairs.append((k, v))
            if self.at(T_PUNCT, ","):
                self.advance()
                continue
            break
        if self.at(T_NAME, "for"):
            comp = self._parse_comprehension()
            self.expect("}")
            return SNode("comp", value="dict", args=[(pairs[0] if pairs else None,
                                                      comp)], line=t.line, col=t.col)
        self.expect("}")
        return SNode("dict", args=pairs, line=t.line, col=t.col, raw="")

    def _parse_comprehension(self):
        targets = []
        while self.at(T_NAME, "for"):
            self.advance()
            tnode = self.parse_expr()
            if not self.at(T_NAME, "in"):
                raise ParseError("expected 'in' in comprehension",
                                 self.peek().line, self.peek().col)
            self.advance()
            it = self.parse_expr()
            while self.at(T_NAME, "if"):
                self.advance()
                self.parse_expr()
            targets.append((tnode, it))
        return targets

    def _parse_seq(self, terminator):
        items = []
        while not self.at(T_PUNCT, terminator):
            if self.at(T_EOF):
                raise ParseError("unterminated sequence", self.peek().line,
                                 self.peek().col)
            items.append(self.parse_expr())
            if self.at(T_PUNCT, ","):
                self.advance()
                continue
            break
        self.expect(terminator)
        return items

    # -- call arguments ----------------------------------------------------
    def parse_args(self, terminator=None):
        """Return a raw list of arg items: ('pos', SNode) or ('kw', name, SNode)."""
        out = []
        while not self.at(T_EOF) and not self.at(T_NEWLINE):
            if terminator and self.at(T_PUNCT, terminator):
                break
            if self.at(T_PUNCT, ")"):
                break
            if self.peek().kind == T_NAME and self.peek(1).is_punct("=") \
                    and not self.peek(1).is_punct("=="):
                nm = self.advance().value
                self.expect("=")
                val = self.parse_expr()
                out.append(("kw", nm, val))
            elif self.at(T_PUNCT, "*"):
                self.advance()
                out.append(("pos", SNode("star", value="*",
                                         args=[self.parse_expr()])))
            elif self.at(T_PUNCT, "**"):
                self.advance()
                out.append(("pos", SNode("star", value="**",
                                         args=[self.parse_expr()])))
            else:
                out.append(("pos", self.parse_expr()))
            if self.at(T_PUNCT, ","):
                self.advance()
                continue
            break
        if terminator and self.at(T_PUNCT, terminator):
            self.advance()
        elif terminator:
            raise ParseError("expected %r" % terminator, self.peek().line,
                             self.peek().col)
        return out

    def parse_call_parts(self):
        """Parse a call's argument list; returns (kwargs dict, args list)."""
        kwargs = {}
        args = []
        for item in self.parse_args(terminator=")"):
            if item[0] == "kw":
                kwargs[item[1]] = item[2]
            else:
                args.append(item[1])
        return kwargs, args


# ---------------------------------------------------------------------------
# Stage A3 -- File-level parse: collect assigns, calls, loads, defs
# ---------------------------------------------------------------------------

def _collect(stmts, pf, scope_bound=None):
    for st in stmts:
        if st.kind == "load":
            for bzl, pairs in st.loads:
                pf.loads.append((bzl, pairs, st.line))
        elif st.kind == "assign":
            if scope_bound is None:
                pf.assigns[st.name] = st.node
        elif st.kind == "def":
            pf.fn_defs[st.name] = st
        elif st.kind == "expr" and st.node is not None:
            if st.node.kind == "call":
                if scope_bound is None:
                    pf.calls.append(st)
        elif st.kind == "if":
            pass


def parse_text(text, path="<string>"):
    """Parse a BUILD/.bzl source into a ParsedFile.  Never raises."""
    pf = ParsedFile(path)
    pf.source = text
    try:
        toks, lex_warns = tokenize(text)
    except Exception as exc:  # pragma: no cover - defensive
        pf.warnings.append("lexer failure: %r" % (exc,))
        return pf
    pf.warnings.extend(lex_warns)
    p = Parser(toks, path)
    try:
        stmts = p.parse_file()
    except Exception as exc:  # pragma: no cover - defensive
        pf.warnings.append("parser failure: %r" % (exc,))
        return pf
    pf.warnings.extend(p.warnings)
    _collect(stmts, pf)
    pf.statements = stmts
    pf.error_stmts = [s for s in stmts if s.kind == "error"]
    return pf


# ---------------------------------------------------------------------------
# Stage B1 -- Typed value model
# ---------------------------------------------------------------------------

class Val(object):
    """Base of the typed Starlark value model."""

    __slots__ = ("kind", "conf", "origin", "reason")

    def __init__(self, kind, conf=C_HIGH, origin=0, reason=""):
        self.kind = kind          # ValueKind: LITERAL | COMPUTED | ENV_DEPENDENT
        self.conf = conf          # Confidence lattice
        self.origin = origin      # BUILD.bazel line
        self.reason = reason

    # -- protocol ----------------------------------------------------------
    def is_literal(self):
        return self.kind == VK_LITERAL

    def to_py(self):
        raise NotImplementedError

    def items(self):
        """Iterate (Val, ...) children; overridden by containers."""
        return []

    def join(self, other):
        """Lattice join of conf (worst wins) and kind (worst wins)."""
        order = {VK_LITERAL: 0, VK_COMPUTED: 1, VK_ENV_DEPENDENT: 2}
        k = self.kind if order.get(self.kind, 2) >= order.get(other.kind, 2) \
            else other.kind
        return max(self.conf, other.conf), k

    def __repr__(self):
        return "%s(%s,%s)" % (type(self).__name__, self.kind,
                              CONF_NAME[self.conf])


class VStr(Val):
    __slots__ = ("s",)

    def __init__(self, s, conf=C_HIGH, origin=0, kind=VK_LITERAL, reason=""):
        Val.__init__(self, kind, conf, origin, reason)
        self.s = s

    def to_py(self):
        return self.s


class VInt(Val):
    __slots__ = ("i",)

    def __init__(self, i, conf=C_HIGH, origin=0):
        Val.__init__(self, VK_LITERAL, conf, origin)
        self.i = i

    def to_py(self):
        return self.i


class VBool(Val):
    __slots__ = ("b",)

    def __init__(self, b, conf=C_HIGH, origin=0):
        Val.__init__(self, VK_LITERAL, conf, origin)
        self.b = b

    def to_py(self):
        return self.b


class VNone(Val):
    def __init__(self, origin=0):
        Val.__init__(self, VK_LITERAL, C_HIGH, origin)

    def to_py(self):
        return None


class VList(Val):
    __slots__ = ("elems",)

    def __init__(self, elems, conf=C_HIGH, origin=0, kind=None):
        if kind is None:
            kind = VK_LITERAL
        Val.__init__(self, kind, conf, origin)
        self.elems = list(elems)

    def to_py(self):
        return [e.to_py() for e in self.elems]

    def items(self):
        return list(self.elems)


class VTuple(Val):
    __slots__ = ("elems",)

    def __init__(self, elems, conf=C_HIGH, origin=0):
        Val.__init__(self, VK_LITERAL, conf, origin)
        self.elems = list(elems)

    def to_py(self):
        return tuple(e.to_py() for e in self.elems)

    def items(self):
        return list(self.elems)


class VDict(Val):
    __slots__ = ("pairs",)

    def __init__(self, pairs, conf=C_HIGH, origin=0, kind=VK_LITERAL):
        Val.__init__(self, kind, conf, origin)
        self.pairs = list(pairs)  # [(VVal, VVal)]

    def to_py(self):
        return dict((k.to_py() if hasattr(k, "to_py") else k,
                     v.to_py() if hasattr(v, "to_py") else v)
                    for k, v in self.pairs)

    def items(self):
        out = []
        for k, v in self.pairs:
            out.append(k)
            out.append(v)
        return out


class VSelect(Val):
    """select({...}) -- fundamentally ENV_DEPENDENT."""

    __slots__ = ("branches", "default_key", "base")

    def __init__(self, branches, default_key=None, base=None, conf=C_LOW,
                 origin=0, reason=""):
        Val.__init__(self, VK_ENV_DEPENDENT, conf, origin, reason)
        self.branches = list(branches)  # [(cond_str, Val)]
        self.default_key = default_key
        self.base = base                # Val that was concatenated before select

    def branch_names(self):
        return [str(b[0]) for b in self.branches]

    def default_value(self):
        for cond, val in self.branches:
            if cond == self.default_key:
                return val
        return None

    def items(self):
        return [v for _, v in self.branches]


class VGlob(Val):
    """glob([...], exclude=[...]) -- ENV_DEPENDENT, pattern preserved."""

    __slots__ = ("patterns", "exclude", "allow_empty", "is_header_only")

    def __init__(self, patterns, exclude, allow_empty=False, conf=C_LOW,
                 origin=0, reason=""):
        Val.__init__(self, VK_ENV_DEPENDENT, conf, origin, reason)
        self.patterns = list(patterns)
        self.exclude = list(exclude)
        self.allow_empty = allow_empty
        self.is_header_only = bool(patterns) and all(
            p.endswith(".h") or p.endswith(".hpp") or p.endswith(".hxx")
            for p in patterns)

    def items(self):
        return []


class VError(Val):
    """An unresolved value.  Never lowered into a -y/obj-m line."""

    __slots__ = ("symbol", "where")

    def __init__(self, reason, conf=C_UNKNOWN, origin=0, symbol=None, where=""):
        Val.__init__(self, VK_ENV_DEPENDENT, conf, origin, reason)
        self.symbol = symbol
        self.where = where

    def to_py(self):
        return None


class VFileLabel(Val):
    """`:name` / `//pkg:target` -- a build label, never a source file."""

    __slots__ = ("label",)

    def __init__(self, label, conf=C_HIGH, origin=0, reason=""):
        Val.__init__(self, VK_LITERAL, conf, origin, reason)
        self.label = label

    def to_py(self):
        return self.label


# ---------------------------------------------------------------------------
# Stage B2 -- .bzl loading and the three-tier symbol resolver
# ---------------------------------------------------------------------------

class BzlLoadError(Exception):
    pass


class _Budget(object):
    __slots__ = ("steps",)

    def __init__(self, steps):
        self.steps = steps

    def tick(self):
        self.steps -= 1
        if self.steps <= 0:
            raise BzlLoadError("evaluation step budget exhausted")


class NativeCallUnsupported(Exception):
    pass


class BzlLoader(object):
    """Resolve ``load()`` labels to parsed .bzl modules, with cycle detection."""

    def __init__(self, repo_root, verbose=False):
        self.repo_root = repo_root
        self.verbose = verbose
        self.cache = {}
        self._parsing = set()
        self.notes = []

    # -- label resolution --------------------------------------------------
    def resolve(self, label, from_dir):
        """Return an absolute path for a load label, or None."""
        if not label:
            return None
        if label.startswith("@"):
            return None  # external repository: not on disk here
        if label.startswith("//"):
            rest = label[2:]
            if ":" in rest:
                pkg, fn = rest.split(":", 1)
            else:
                pkg, fn = rest, rest.split("/")[-1]
            return os.path.normpath(os.path.join(self.repo_root, pkg, fn))
        if label.startswith(":"):
            return os.path.normpath(os.path.join(from_dir, label[1:]))
        # relative path like "foo/bar.bzl"
        if label.endswith(".bzl"):
            return os.path.normpath(os.path.join(from_dir, label))
        return None

    def load(self, label, from_dir):
        path = self.resolve(label, from_dir)
        if path is None or not os.path.isfile(path):
            return None, "cannot locate %r (external or missing)" % label
        if path in self._parsing:
            return None, "circular load of %r" % label
        if path in self.cache:
            return self.cache[path], ""
        self._parsing.add(path)
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as fh:
                text = fh.read()
        except OSError as exc:
            self._parsing.discard(path)
            return None, "cannot read %r: %s" % (label, exc)
        pf = parse_text(text, path)
        self.cache[path] = pf
        self._parsing.discard(path)
        return pf, ""


class BzlEvaluator(object):
    """Tree-walking evaluator for the .bzl subset that matters.

    Three-tier ladder:
      1. top-level literal assignment                -> LITERAL
      2. top-level assignment calling a same-.bzl def -> evaluate body, COMPUTED
      3. anything reaching native.*/glob()/unknown    -> ENV_DEPENDENT (VError)
    """

    def __init__(self, loader, origin_root, verbose=False):
        self.loader = loader
        self.repo_root = origin_root
        self.verbose = verbose

    # -- symbol export resolution -----------------------------------------
    def exported(self, label, symbol, from_dir, _seen=None):
        pf, err = self.loader.load(label, from_dir)
        if pf is None:
            return None, err
        return self.symbol_value(pf, symbol, os.path.dirname(pf.path), _seen)

    def symbol_value(self, pf, symbol, bzl_dir, _seen=None):
        seen = _seen if _seen is not None else set()
        key = (pf.path, symbol)
        if key in seen:
            return None, "circular symbol reference %s:%s" % (pf.path, symbol)
        seen.add(key)

        node = pf.assigns.get(symbol)
        if node is not None:
            conf, kind, val = self.eval_node(node, pf, bzl_dir, seen, VK_LITERAL)
            return val, ""

        for bzl, pairs, line in pf.loads:
            for local, orig in pairs:
                if local == symbol:
                    sub, err = self.exported(bzl, orig, bzl_dir, seen)
                    if sub is None:
                        return None, err or "unresolvable re-export %r" % symbol
                    return sub, ""
        return None, "symbol %r is not a static assignment in %s (macro-driven)" \
            % (symbol, os.path.basename(pf.path))

    # -- expression evaluation --------------------------------------------
    def eval_node(self, node, pf, bzl_dir, seen, kind_hint, env=None):
        """Return (conf, kind, Val).

        Every path is total: unsupported constructs yield a VError rather than
        an exception.
        """
        env = env if env is not None else {}
        try:
            return self._eval(node, pf, bzl_dir, seen, env)
        except (BzlLoadError, NativeCallUnsupported) as exc:
            return (C_LOW, VK_ENV_DEPENDENT,
                    VError(str(exc), C_LOW, node.line if node else 0))
        except RecursionError:
            return (C_LOW, VK_ENV_DEPENDENT,
                    VError("evaluation recursion limit", C_LOW))
        except Exception as exc:  # pragma: no cover - defensive
            return (C_LOW, VK_ENV_DEPENDENT,
                    VError("evaluation error: %r" % (exc,), C_LOW))

    def _eval(self, node, pf, bzl_dir, seen, env):
        if node is None:
            return (C_HIGH, VK_LITERAL, VNone())

        k = node.kind
        if k == "str":
            return (C_HIGH, VK_LITERAL, VStr(node.value, origin=node.line))
        if k == "num":
            try:
                return (C_HIGH, VK_LITERAL, VInt(int(node.value, 0), origin=node.line))
            except ValueError:
                return (C_HIGH, VK_LITERAL, VStr(node.value, origin=node.line))
        if k == "bool":
            return (C_HIGH, VK_LITERAL, VBool(node.value, origin=node.line))
        if k == "none":
            return (C_HIGH, VK_LITERAL, VNone(node.line))

        if k == "name":
            name = node.value
            if name in env:
                v = env[name]
                return (v.conf, v.kind, v)
            if name == "native":
                return (C_HIGH, VK_LITERAL, VStr("native", origin=node.line))
            # BUILD-local assignment
            n2 = pf.assigns.get(name)
            if n2 is not None and n2 is not node:
                c2, k2, v2 = self._eval(n2, pf, bzl_dir, seen, env)
                v2 = _with_origin(v2, node.line)
                return (c2, k2, v2)
            # loaded symbol
            for bzl, pairs, line in pf.loads:
                for local, orig in pairs:
                    if local == name:
                        sub, err = self.exported(bzl, orig, bzl_dir, seen)
                        if sub is not None:
                            return (sub.conf, sub.kind, sub)
                        return (C_LOW, VK_ENV_DEPENDENT,
                                VError(err, C_LOW, node.line, symbol=name))
            return (C_LOW, VK_ENV_DEPENDENT,
                    VError("unresolved symbol %r" % name, C_LOW, node.line,
                           symbol=name))

        if k == "list":
            return self._eval_list(node, pf, bzl_dir, seen, env)
        if k == "tuple":
            conf, kind, elems = self._eval_seq(node.args, pf, bzl_dir, seen, env)
            return (conf, kind, VTuple(elems, conf=conf, origin=node.line))
        if k == "dict":
            return self._eval_dict(node, pf, bzl_dir, seen, env)

        if k == "binop":
            return self._eval_binop(node, pf, bzl_dir, seen, env)
        if k == "unop":
            return self._eval_unop(node, pf, bzl_dir, seen, env)
        if k == "attr":
            return self._eval_attr(node, pf, bzl_dir, seen, env)
        if k == "index":
            return self._eval_index(node, pf, bzl_dir, seen, env)
        if k == "call":
            return self._eval_call(node, pf, bzl_dir, seen, env)
        if k == "comp":
            return self._eval_comp(node, pf, bzl_dir, seen, env)
        if k == "ternary":
            cond = self._eval(node.args[0], pf, bzl_dir, seen, env)[2]
            branch = node.args[1] if _truthy(cond) else node.args[2]
            conf, kind, val = self._eval(branch, pf, bzl_dir, seen, env)
            return (max(conf, C_MEDIUM), kind, val)
        if k == "lambda":
            return (C_HIGH, VK_LITERAL, VStr("<lambda>", kind=VK_COMPUTED))

        return (C_LOW, VK_ENV_DEPENDENT,
                VError("unsupported expression %r" % k, C_LOW,
                       node.line, where=k))

    # -- containers --------------------------------------------------------
    def _eval_list(self, node, pf, bzl_dir, seen, env):
        confs = [C_HIGH]
        kind = VK_LITERAL
        elems = []
        for sub in node.args:
            c, kk, v = self._eval(sub, pf, bzl_dir, seen, env)
            confs.append(c)
            if _kind_rank(kk) > _kind_rank(kind):
                kind = kk
            elems.append(v)
        conf = max(confs)
        if any(isinstance(e, VError) for e in elems):
            conf = max(conf, C_LOW)
            kind = VK_ENV_DEPENDENT
        return (conf, kind, VList(elems, conf=conf, origin=node.line, kind=kind))

    def _eval_seq(self, nodes, pf, bzl_dir, seen, env):
        conf = C_HIGH
        kind = VK_LITERAL
        elems = []
        for sub in nodes:
            c, kk, v = self._eval(sub, pf, bzl_dir, seen, env)
            conf = max(conf, c)
            if _kind_rank(kk) > _kind_rank(kind):
                kind = kk
            elems.append(v)
        return conf, kind, elems

    def _eval_dict(self, node, pf, bzl_dir, seen, env):
        conf = C_HIGH
        kind = VK_LITERAL
        pairs = []
        for kn, vn in node.args:
            ck, kk, kv = self._eval(kn, pf, bzl_dir, seen, env)
            cv, kvk, vv = self._eval(vn, pf, bzl_dir, seen, env)
            conf = max(conf, ck, cv)
            kind = _worse_kind(kind, _worse_kind(kk, kvk))
            pairs.append((kv, vv))
        return (conf, kind, VDict(pairs, conf=conf, origin=node.line, kind=kind))

    # -- operators ---------------------------------------------------------
    def _eval_binop(self, node, pf, bzl_dir, seen, env):
        op = node.value
        c1, k1, v1 = self._eval(node.args[0], pf, bzl_dir, seen, env)
        c2, k2, v2 = self._eval(node.args[1], pf, bzl_dir, seen, env)
        conf = max(c1, c2)
        kind = _worse_kind(k1, k2)

        if op == "+":
            if isinstance(v1, VStr) and isinstance(v2, VStr):
                return (conf, kind, VStr(v1.s + v2.s, conf=conf,
                                         origin=node.line, kind=kind))
            if isinstance(v1, VList) and isinstance(v2, VList):
                elems = list(v1.elems) + list(v2.elems)
                return (conf, kind, VList(elems, conf=conf,
                                          origin=node.line, kind=kind))
            if isinstance(v1, VList) and isinstance(v2, VSelect):
                merged = VSelect(v2.branches, v2.default_key, base=v1,
                                 conf=max(conf, C_LOW), origin=node.line,
                                 reason=v2.reason)
                return (merged.conf, VK_ENV_DEPENDENT, merged)
            if isinstance(v1, VSelect) and isinstance(v2, VList):
                merged = VSelect(v1.branches, v1.default_key, base=v2,
                                 conf=max(conf, C_LOW), origin=node.line,
                                 reason=v1.reason)
                return (merged.conf, VK_ENV_DEPENDENT, merged)
            if isinstance(v1, VError) or isinstance(v2, VError):
                return (C_LOW, VK_ENV_DEPENDENT,
                        VError("cannot concatenate unresolved value",
                               C_LOW, node.line))
            return (C_MEDIUM, VK_COMPUTED, VStr("", conf=C_MEDIUM))
        if op == "%":
            if isinstance(v1, VStr) and isinstance(v2, VStr):
                return (conf, VK_COMPUTED, VStr(_try_percent(v1.s, v2.s),
                                                conf=conf, kind=VK_COMPUTED))
            return (C_MEDIUM, VK_COMPUTED, VError("unsupported %% operation",
                                                  C_MEDIUM, node.line))
        if op in ("==", "!="):
            eq = v1.to_py() == v2.to_py()
            return (conf, kind, VBool(eq if op == "==" else not eq))
        if op == "in" or op == "not in":
            try:
                hay = v2.to_py()
                needle = v1.to_py()
                res = needle in (hay or [])
            except Exception:
                res = False
            return (max(conf, C_MEDIUM), VK_COMPUTED,
                    VBool(res if op == "in" else not res, conf=max(conf, C_MEDIUM)))
        if op == "|":
            if isinstance(v1, VDict) and isinstance(v2, VDict):
                return (conf, kind, VDict(list(v1.pairs) + list(v2.pairs),
                                          conf=conf, origin=node.line, kind=kind))
        return (C_MEDIUM, VK_COMPUTED,
                VError("unsupported operator %r" % op, C_MEDIUM, node.line))

    def _eval_unop(self, node, pf, bzl_dir, seen, env):
        c, k, v = self._eval(node.args[0], pf, bzl_dir, seen, env)
        if node.value == "not":
            return (c, k, VBool(not _truthy(v), conf=c))
        return (c, k, v)

    def _eval_attr(self, node, pf, bzl_dir, seen, env):
        c, k, base = self._eval(node.value, pf, bzl_dir, seen, env)
        attr = node.args[0]
        if isinstance(base, VStr):
            return (c, k, VStr("%s.%s" % (base.s, attr), conf=c,
                               kind=VK_COMPUTED))
        return (C_MEDIUM, VK_COMPUTED,
                VError("attribute access .%s on non-literal" % attr, C_MEDIUM,
                       node.line))

    def _eval_index(self, node, pf, bzl_dir, seen, env):
        c1, k1, base = self._eval(node.value, pf, bzl_dir, seen, env)
        c2, k2, idx = self._eval(node.args[0], pf, bzl_dir, seen, env)
        if isinstance(base, VDict):
            key = idx.to_py()
            for kk, vv in base.pairs:
                if hasattr(kk, "to_py") and kk.to_py() == key:
                    return (max(c1, c2), _worse_kind(k1, k2), vv)
            return (max(c1, c2, C_MEDIUM), VK_COMPUTED, VNone())
        if isinstance(base, VList) and isinstance(idx, VInt):
            try:
                return (max(c1, c2), _worse_kind(k1, k2), base.elems[idx.i])
            except IndexError:
                return (C_MEDIUM, VK_COMPUTED, VError("index out of range",
                                                      C_MEDIUM, node.line))
        if isinstance(base, VStr):
            # string indexing/slicing: keep it opaque but harmless
            return (C_MEDIUM, VK_COMPUTED, VError("string index", C_MEDIUM,
                                                  node.line))
        return (C_MEDIUM, VK_COMPUTED, VError("unsupported index", C_MEDIUM,
                                              node.line))

    # -- comprehensions ----------------------------------------------------
    def _eval_comp(self, node, pf, bzl_dir, seen, env):
        comp = node.args[1]
        is_dict = node.value == "dict"
        out_elems = []
        pairs = []
        budget = _Budget(20000)
        envs = [dict(env)]
        for target, it in comp:
            nxt = []
            for e in envs:
                budget.tick()
                _, _, iterable = self._eval(it, pf, bzl_dir, seen, e)
                try:
                    values = iterable.to_py()
                except Exception:
                    values = []
                if not isinstance(values, (list, tuple)):
                    values = []
                for item in values:
                    e2 = dict(e)
                    if target.kind == "name":
                        e2[target.value] = _py_to_val(item, it.line)
                    nxt.append(e2)
            envs = nxt
            if not envs:
                break
        for e in envs:
            budget.tick()
            if is_dict:
                kn, vn = node.args[0]
                _, _, kv = self._eval(kn, pf, bzl_dir, seen, e)
                _, _, vv = self._eval(vn, pf, bzl_dir, seen, e)
                pairs.append((kv, vv))
            else:
                _, _, elt = self._eval(node.args[0], pf, bzl_dir, seen, e)
                out_elems.append(elt)
        if is_dict:
            return (C_MEDIUM, VK_COMPUTED,
                    VDict(pairs, conf=C_MEDIUM, origin=node.line,
                          kind=VK_COMPUTED))
        return (C_MEDIUM, VK_COMPUTED,
                VList(out_elems, conf=C_MEDIUM, origin=node.line,
                      kind=VK_COMPUTED))

    # -- calls -------------------------------------------------------------
    def _eval_call(self, node, pf, bzl_dir, seen, env):
        callee = node.value
        name = None
        if callee is not None and callee.kind == "name":
            name = callee.value
        elif callee is not None and callee.kind == "attr":
            base = callee.value
            base_name = base.value if base is not None and base.kind == "name" else ""
            name = "%s.%s" % (base_name, callee.args[0])
        kwargs = {}
        pos = []
        budget = _Budget(BZ_WALK_STEPS)
        for key, sub in node.kwargs.items():
            budget.tick()
            _, _, v = self._eval(sub, pf, bzl_dir, seen, env)
            kwargs[key] = v
        for sub in node.args:
            budget.tick()
            _, _, v = self._eval(sub, pf, bzl_dir, seen, env)
            pos.append(v)

        if name in ("glob", "native.glob"):
            pats = kwargs.get("include")
            if pats is None and pos:
                pats = pos[0]
            pat_list = _val_str_list(pats)
            excl = _val_str_list(kwargs.get("exclude"))
            return (C_LOW, VK_ENV_DEPENDENT,
                    VGlob(pat_list, excl, conf=C_LOW, origin=node.line))
        if name in ("select", "native.select"):
            branches = []
            default_key = None
            src = kwargs.get("_") if "_" in kwargs else (pos[0] if pos else None)
            if src is None and pos:
                src = pos[0]
            if isinstance(src, VDict):
                for kk, vv in src.pairs:
                    ks = kk.to_py() if hasattr(kk, "to_py") else str(kk)
                    branches.append((ks, vv))
                    if ks == "//conditions:default":
                        default_key = ks
            if default_key is None and branches:
                default_key = branches[0][0]
            return (C_LOW, VK_ENV_DEPENDENT,
                    VSelect(branches, default_key, conf=C_LOW, origin=node.line,
                            reason="select() over Bazel config_settings"))

        if name in ("native.glob", "native.genrule", "native.filegroup",
                    "native.package", "native.exports_files", "filegroup",
                    "genrule", "copy_files", "hermetic_genrule",
                    "genrule_files", "select_files", "cc_binary"):
            raise NativeCallUnsupported(
                "%s() is build-graph driven, not statically evaluable" % name)

        if name in ("struct", "struct2"):
            return (C_MEDIUM, VK_COMPUTED, VDict([], conf=C_MEDIUM,
                                                 origin=node.line))

        # user-defined function in the same .bzl
        fn = pf.fn_defs.get(name)
        if fn is not None:
            return self._call_user_fn(fn, pos, kwargs, pf, bzl_dir, seen, env)

        # method call on a value: .append/.extend/.get/.format
        if callee is not None and callee.kind == "attr":
            return self._eval_method(callee, pos, kwargs, pf, bzl_dir, seen, env)

        if name in ("False", "True") or name is None:
            return (C_MEDIUM, VK_COMPUTED,
                    VError("indirect call", C_MEDIUM, node.line))
        return (C_LOW, VK_ENV_DEPENDENT,
                VError("unresolved function %r" % name, C_LOW, node.line,
                       symbol=name))

    def _eval_method(self, callee, pos, kwargs, pf, bzl_dir, seen, env):
        base_node = callee.value
        attr = callee.args[0]
        # _eval returns (conf, kind, Val) -- unpack all three.
        c, k, base = self._eval(base_node, pf, bzl_dir, seen, env)
        base_conf, base_kind = c, k
        # In-place mutation (.append/.extend) must write back into the caller's
        # environment, otherwise a def body's `srcs.append(...)` is lost.
        if base_node is not None and base_node.kind == "name":
            target_key = base_node.value
        else:
            target_key = None
        if attr == "get":
            key = pos[0].to_py() if pos else None
            default = pos[1] if len(pos) > 1 else VNone()
            if isinstance(base, VDict):
                for kk, vv in base.pairs:
                    if hasattr(kk, "to_py") and kk.to_py() == key:
                        return (base_conf, base_kind, vv)
                return (base_conf, base_kind, default)
            return (max(base_conf, C_MEDIUM), VK_COMPUTED,
                    VError("get() on non-dict", C_MEDIUM))
        if attr == "keys" and isinstance(base, VDict):
            keys = [k for k, _ in base.pairs]
            return (base_conf, base_kind, VList(keys, conf=base_conf,
                                                origin=base.origin,
                                                kind=base_kind))
        if attr in ("append", "extend"):
            # in-place mutation inside a def body
            extra = pos[0] if pos else VList([])
            new = base
            if isinstance(base, VList):
                if attr == "append":
                    new = VList(list(base.elems) + [extra], conf=base_conf,
                                origin=base.origin, kind=base_kind)
                else:
                    more = extra.elems if isinstance(extra, VList) else [extra]
                    new = VList(list(base.elems) + list(more), conf=base_conf,
                                origin=base.origin, kind=base_kind)
            elif isinstance(base, VDict) and attr == "extend":
                new = base
            if target_key is not None:
                env[target_key] = new
            return (new.conf, new.kind, new)
        if attr == "format":
            return (C_MEDIUM, VK_COMPUTED,
                    VStr("<formatted>", conf=C_MEDIUM, kind=VK_COMPUTED))
        if attr == "startswith" or attr == "endswith":
            if isinstance(base, VStr) and pos and isinstance(pos[0], VStr):
                ok = base.s.endswith(pos[0].s) if attr == "endswith" \
                    else base.s.startswith(pos[0].s)
                return (base_conf, base_kind, VBool(ok))
        if attr == "join" and isinstance(base, VStr):
            if pos and isinstance(pos[0], VList):
                return (C_MEDIUM, VK_COMPUTED,
                        VStr(base.s.join(_val_str_list(pos[0])), kind=VK_COMPUTED))
        return (C_MEDIUM, VK_COMPUTED,
                VError("unsupported method .%s()" % attr, C_MEDIUM))

    def _call_user_fn(self, fn, pos, kwargs, pf, bzl_dir, seen, env):
        """Evaluate a def body with args bound -- no exec, bounded steps."""
        local = dict(env)
        params = fn.params
        for idx, (pname, default) in enumerate(params):
            if idx < len(pos):
                local[pname] = pos[idx]
            elif pname in kwargs:
                local[pname] = kwargs[pname]
            elif default is not None:
                _, _, dv = self._eval(default, pf, bzl_dir, seen, env)
                local[pname] = dv
            else:
                local[pname] = VNone()
        budget = _Budget(BZ_WALK_STEPS)
        try:
            _, _, kind, val = self._exec_block(fn.body, pf, bzl_dir, seen,
                                               local, budget)
        except BzlLoadError as exc:
            return (C_LOW, VK_ENV_DEPENDENT, VError(str(exc), C_LOW, fn.line))
        if val is None:
            return (C_LOW, VK_ENV_DEPENDENT,
                    VError("def %s() did not return a value" % fn.name, C_LOW,
                           fn.line))
        return (val.conf if isinstance(val, Val) else C_MEDIUM, kind, val)

    def _exec_block(self, stmts, pf, bzl_dir, seen, env, budget):
        kind = VK_COMPUTED
        for st in stmts:
            budget.tick()
            if st.kind == "assign":
                c, kk, v = self._eval(st.node, pf, bzl_dir, seen, env)
                c, kk, v = _mutate_kind(c, kk, v)
                existing = env.get(st.name)
                if isinstance(existing, VList) and v is existing:
                    pass
                env[st.name] = v
                kind = _worse_kind(kind, kk)
            elif st.kind == "expr" and st.node is not None:
                if st.node.kind == "call":
                    c, kk, v = self._eval_call(st.node, pf, bzl_dir, seen, env)
                    kind = _worse_kind(kind, kk)
                    self._maybe_rebind(st.node, v, env)
                else:
                    c, kk, v = self._eval(st.node, pf, bzl_dir, seen, env)
                    kind = _worse_kind(kind, kk)
            elif st.kind == "return":
                if st.node is None:
                    return True, C_HIGH, kind, VNone()
                c, kk, v = self._eval(st.node, pf, bzl_dir, seen, env)
                return True, c, _worse_kind(kind, kk), v
            elif st.kind == "compound":
                done, conf, kk, val = self._exec_compound(
                    st, pf, bzl_dir, seen, env, budget)
                kind = _worse_kind(kind, kk)
                if done:
                    return True, conf, kind, val
            elif st.kind in ("if", "for"):
                pass
            elif st.kind == "error":
                return (True, C_LOW, VK_ENV_DEPENDENT,
                        VError("unsupported statement in macro body",
                               C_LOW, st.line))
        return False, C_HIGH, kind, None

    def _exec_compound(self, st, pf, bzl_dir, seen, env, budget):
        """Execute if/elif/else/for/while; returns (returned, conf, kind, val).

        Statements mutate `env` in place so a def body's `srcs.append(...)`
        and `x = ...` assignments survive.
        """
        conf = C_HIGH
        kind = VK_COMPUTED
        for clause in st.body:
            budget.tick()
            kw = clause["kw"]
            if kw in ("if", "elif"):
                _, _, cv = self._eval(clause["cond"], pf, bzl_dir, seen, env)
                if not _truthy(cv):
                    continue
            if kw == "for":
                tnode, it = clause["target"]
                _, _, iterable = self._eval(it, pf, bzl_dir, seen, env)
                values = []
                try:
                    values = iterable.to_py()
                except Exception:
                    values = []
                if not isinstance(values, (list, tuple)):
                    values = []
                for item in values:
                    budget.tick()
                    if tnode is not None and tnode.kind == "name":
                        env[tnode.value] = _py_to_val(item, st.line)
                    done, c2, k2, v2 = self._exec_block(
                        clause["body"], pf, bzl_dir, seen, env, budget)
                    conf = max(conf, c2)
                    kind = _worse_kind(kind, k2)
                    if done:
                        return True, conf, kind, v2
                continue        # `for` has no fall-through body of its own
            if kw == "while":
                # Bounded: never allow an unbounded loop from repo code.
                for _ in range(1000):
                    budget.tick()
                    _, _, cv = self._eval(clause["cond"], pf, bzl_dir, seen, env)
                    if not _truthy(cv):
                        break
                    done, c2, k2, v2 = self._exec_block(
                        clause["body"], pf, bzl_dir, seen, env, budget)
                    conf = max(conf, c2)
                    kind = _worse_kind(kind, k2)
                    if done:
                        return True, conf, kind, v2
                else:
                    return (True, C_LOW, VK_ENV_DEPENDENT,
                            VError("while loop exceeded its iteration bound",
                                   C_LOW, st.line))
                continue
            # if / elif / else: a taken clause executes and ends the chain.
            done, c2, k2, v2 = self._exec_block(clause["body"], pf, bzl_dir,
                                                seen, env, budget)
            conf = max(conf, c2)
            kind = _worse_kind(kind, k2)
            if done:
                return True, conf, kind, v2
            return False, conf, kind, None
        return False, conf, kind, None

    def _maybe_rebind(self, call_node, val, env):
        """Handle `srcs = fn(...)` style in-place reassignment (rare)."""
        return


def _mutate_kind(conf, kind, val):
    if isinstance(val, VError):
        return C_LOW, VK_ENV_DEPENDENT, val
    return conf, kind, val


def _py_to_val(item, line):
    if isinstance(item, str):
        return VStr(item, origin=line)
    if isinstance(item, bool):
        return VBool(item, origin=line)
    if isinstance(item, int):
        return VInt(item, origin=line)
    if isinstance(item, (list, tuple)):
        return VList([_py_to_val(x, line) for x in item], origin=line)
    if isinstance(item, dict):
        return VDict([(_py_to_val(k, line), _py_to_val(v, line))
                      for k, v in item.items()], origin=line)
    if item is None:
        return VNone(line)
    return VStr(str(item), conf=C_MEDIUM, origin=line, kind=VK_COMPUTED)


def _kind_rank(kind):
    return {VK_LITERAL: 0, VK_COMPUTED: 1, VK_ENV_DEPENDENT: 2}.get(kind, 2)


def _worse_kind(a, b):
    return a if _kind_rank(a) >= _kind_rank(b) else b


def _with_origin(val, line):
    try:
        if isinstance(val, (VStr, VInt, VBool)):
            val.origin = line
    except Exception:
        pass
    return val


def _truthy(val):
    try:
        return bool(val.to_py())
    except Exception:
        return False


def _val_str_list(val):
    if val is None:
        return []
    if isinstance(val, VList):
        out = []
        for e in val.elems:
            if isinstance(e, VStr):
                out.append(e.s)
        return out
    if isinstance(val, VStr):
        return [val.s]
    return []


def _try_percent(fmt, arg):
    try:
        return fmt % arg
    except Exception:
        return fmt


# ---------------------------------------------------------------------------
# Stage B3 -- Resolver: BUILD syntax tree -> typed values
# ---------------------------------------------------------------------------

class Finding(object):
    """An unrecoverable / lossy item, attached to a node path."""

    __slots__ = ("path", "kind", "detail", "line", "conf")

    def __init__(self, path, kind, detail, line=0, conf=C_LOW):
        self.path = path
        self.kind = kind          # 'lossy' | 'unrecoverable' | 'note' | 'warn'
        self.detail = detail
        self.line = line
        self.conf = conf

    def as_dict(self):
        return {"path": self.path, "kind": self.kind, "detail": self.detail,
                "line": self.line, "confidence": CONF_NAME[self.conf]}


class Exit(Exception):
    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


class Resolver(object):
    """Turn a parsed BUILD.bazel into typed module value sets."""

    def __init__(self, build_path, pf, loader, opts):
        self.build_path = build_path
        self.dir = os.path.dirname(os.path.abspath(build_path))
        self.pf = pf
        self.loader = loader
        self.opts = opts
        self.ev = BzlEvaluator(loader, opts.repo_root, opts.verbose)
        self.findings = []
        self._depth = 0

    # -- public ------------------------------------------------------------
    def resolve_file_scoped(self, target_name):
        """Look up a local `:target` rule in the same file."""
        for st in self.pf.calls:
            node = st.node
            if node.value is not None and node.value.kind == "name":
                fn = node.value.value
            else:
                fn = ""
            nm = node.kwargs.get("name")
            if nm is not None and nm.kind == "str" and nm.value == target_name:
                return fn, node
        return None, None

    def value_of(self, node, path, seen=None):
        """Resolve a syntax node to a typed Val.  Never raises."""
        seen = seen if seen is not None else set()
        self._depth += 1
        if self._depth > MAX_NEST:
            self._depth -= 1
            return VError("resolution nesting too deep", C_LOW, node.line if node else 0)
        try:
            return self._value_of(node, path, seen)
        except Exception as exc:  # pragma: no cover - defensive
            return VError("resolution error: %r" % (exc,), C_LOW,
                          node.line if node else 0)
        finally:
            self._depth -= 1

    def _value_of(self, node, path, seen):
        if node is None:
            return VNone()
        line = node.line
        k = node.kind

        if k == "str":
            return VStr(node.value, origin=line)
        if k == "num":
            try:
                return VInt(int(node.value, 0), origin=line)
            except ValueError:
                return VStr(node.value, origin=line)
        if k == "bool":
            return VBool(node.value, origin=line)
        if k == "none":
            return VNone(line)

        if k == "list":
            elems = [self._value_of(e, "%s[%d]" % (path, i), seen)
                     for i, e in enumerate(node.args)]
            conf = max([e.conf for e in elems] or [C_HIGH])
            kind = VK_LITERAL
            for e in elems:
                kind = _worse_kind(kind, e.kind)
            return VList(elems, conf=conf, origin=line, kind=kind)

        if k == "tuple":
            elems = [self._value_of(e, path, seen) for e in node.args]
            conf = max([e.conf for e in elems] or [C_HIGH])
            return VTuple(elems, conf=conf, origin=line)

        if k == "dict":
            conf = C_HIGH
            kind = VK_LITERAL
            pairs = []
            for i, (kn, vn) in enumerate(node.args):
                kv = self._value_of(kn, "%s.key[%d]" % (path, i), seen)
                vv = self._value_of(vn, "%s[%s]" % (path, _key_str(kv, i)), seen)
                conf = max(conf, kv.conf, vv.conf)
                kind = _worse_kind(kind, _worse_kind(kv.kind, vv.kind))
                pairs.append((kv, vv))
            return VDict(pairs, conf=conf, origin=line, kind=kind)

        if k == "binop" and node.value == "+":
            left = self._value_of(node.args[0], path, seen)
            right = self._value_of(node.args[1], path, seen)
            return self._concat(left, right, path, line)

        if k == "binop":
            # other operators inside a ddk attribute: opaque
            self.findings.append(Finding(
                path, "unrecoverable",
                "operator %r inside an attribute value is not expressible" % node.value,
                line))
            return VError("operator %r" % node.value, C_LOW, line)

        if k == "name":
            return self._resolve_name(node, path, seen)

        if k == "call":
            return self._resolve_call(node, path, seen)

        if k == "comp":
            val = self._eval_comprehension(node, path, seen)
            self.findings.append(Finding(
                path, "lossy",
                "comprehension in an attribute value: resolved best-effort",
                line, C_MEDIUM))
            return val

        if k == "ternary":
            self.findings.append(Finding(
                path, "unrecoverable",
                "conditional expression (a if c else b) cannot be projected",
                line))
            return VError("ternary", C_LOW, line)

        if k == "lambda":
            self.findings.append(Finding(path, "unrecoverable",
                                         "lambda value", line))
            return VError("lambda", C_LOW, line)

        if k == "attr":
            self.findings.append(Finding(path, "unrecoverable",
                                         "attribute value expression", line))
            return VError("attribute %s" % ".".join(node.args), C_LOW, line)

        if k == "star":
            return self._value_of(node.args[0], path, seen)

        self.findings.append(Finding(path, "unrecoverable",
                                     "unsupported syntax %r" % k, line))
        return VError("unsupported %s" % k, C_LOW, line)

    # -- helpers -----------------------------------------------------------
    def _concat(self, left, right, path, line):
        conf = max(left.conf, right.conf)
        kind = _worse_kind(left.kind, right.kind)
        if isinstance(left, VList) and isinstance(right, VList):
            return VList(list(left.elems) + list(right.elems), conf=conf,
                         origin=line, kind=kind)
        if isinstance(left, VList) and isinstance(right, VSelect):
            merged = VSelect(right.branches, right.default_key, base=left,
                             conf=max(conf, C_LOW), origin=line,
                             reason=right.reason)
            return merged
        if isinstance(left, VSelect) and isinstance(right, VList):
            # `(... + select(...)) + LIST`: both the select's existing base and
            # LIST are unconditional, so accumulate them.  Overwriting base
            # with `right` alone silently drops the earlier literal part.
            if left.base is None:
                new_base = right
            elif isinstance(left.base, VList):
                new_base = VList(list(left.base.elems) + list(right.elems),
                                 conf=max(left.base.conf, right.conf),
                                 origin=line, kind=kind)
            else:
                new_base = VList([left.base] + list(right.elems),
                                 conf=max(conf, C_LOW), origin=line, kind=kind)
            merged = VSelect(left.branches, left.default_key, base=new_base,
                             conf=max(conf, C_LOW), origin=line,
                             reason=left.reason)
            return merged
        if isinstance(left, VSelect) and isinstance(right, VSelect):
            merged = VSelect(left.branches + right.branches,
                             left.default_key, base=None,
                             conf=max(conf, C_LOW), origin=line,
                             reason=left.reason or right.reason)
            return merged
        if isinstance(left, VStr) and isinstance(right, VStr):
            return VStr(left.s + right.s, conf=conf, origin=line, kind=kind)
        if isinstance(left, VError) or isinstance(right, VError):
            bad = left if isinstance(left, VError) else right
            return bad
        if isinstance(left, VGlob) or isinstance(right, VGlob):
            # `["a.c"] + glob([...])`: the literal part is always recoverable.
            # A header-only glob adds nothing at all; a source glob is a real
            # loss and is recorded as such.
            g = left if isinstance(left, VGlob) else right
            other = right if isinstance(left, VGlob) else left
            pats = ", ".join(g.patterns)
            if g.is_header_only:
                self.findings.append(Finding(
                    path, "note",
                    "header-only glob([%s]) is covered by -I; no object line "
                    "needed" % pats, line, C_MEDIUM))
                return other
            self.findings.append(Finding(
                path, "unrecoverable",
                "glob([%s]) concatenated with a literal list: the glob part is "
                "not recoverable" % pats, line))
            if isinstance(other, VList):
                el = list(other.elems)
                el.append(VError("glob([%s])" % pats, C_LOW, line))
                return VList(el, conf=C_LOW, origin=line,
                             kind=VK_ENV_DEPENDENT)
            return VError("glob concatenation", C_LOW, line)
        return VError("unsupported concatenation", C_LOW, line)

    def _resolve_name(self, node, path, seen):
        name = node.value
        key = (id(self.pf), name)
        if key in seen:
            self.findings.append(Finding(path, "unrecoverable",
                                         "circular symbol %r" % name, node.line))
            return VError("circular symbol %r" % name, C_LOW, node.line,
                          symbol=name)
        seen = seen | {key}
        target = self.pf.assigns.get(name)
        if target is not None and target is not node:
            val = self._value_of(target, path, seen)
            return _with_origin(val, node.line)
        # loaded from a .bzl
        for bzl, pairs, line in self.pf.loads:
            for local, orig in pairs:
                if local == name:
                    val, err = self.ev.exported(bzl, orig, self.dir, set())
                    if val is not None:
                        self.findings.append(Finding(
                            path, "note",
                            "resolved %r from %s (=%s)" % (name, bzl, orig),
                            line, val.conf))
                        return _with_origin(val, node.line)
                    self.findings.append(Finding(
                        path, "unrecoverable",
                        "cannot resolve %r from %s: %s" % (name, bzl, err),
                        line))
                    return VError("unresolved %r" % name, C_LOW, node.line,
                                  symbol=name)
        self.findings.append(Finding(path, "unrecoverable",
                                     "unresolved symbol %r" % name, node.line))
        return VError("unresolved %r" % name, C_LOW, node.line, symbol=name)

    def _resolve_call(self, node, path, seen):
        callee = node.value
        name = ""
        if callee is not None and callee.kind == "name":
            name = callee.value
        elif callee is not None and callee.kind == "attr":
            base = callee.value
            bname = base.value if base is not None and base.kind == "name" else ""
            name = "%s.%s" % (bname, callee.args[0])

        if name in ("glob", "native.glob"):
            return self._resolve_glob(node, path)
        if name in ("select", "native.select") or name == "select":
            return self._resolve_select(node, path, seen)
        if name in ("Label", "label"):
            args = node.args
            if args and args[0].kind == "str":
                return VFileLabel(args[0].value, origin=node.line)
            return VError("Label()", C_LOW, node.line)
        if name in ("[]", ) or name == "":
            pass

        # A call to a local/loaded macro inside an attribute, e.g.
        # get_versioned_sources(...) or __srcs_from_config(...).
        fn = self.pf.fn_defs.get(name)
        if fn is not None:
            val = self._eval_local_fn(fn, node, path, seen)
            return val
        for bzl, pairs, line in self.pf.loads:
            for local, orig in pairs:
                if local != name:
                    continue
                bpf, err = self.loader.load(bzl, self.dir)
                if bpf is None:
                    break
                if orig in bpf.fn_defs:
                    val = self._eval_macro(bpf, bpf.fn_defs[orig], node,
                                           os.path.dirname(bpf.path), path, line)
                    return val
                if orig in bpf.assigns:
                    sub = self.ev.symbol_value(bpf, orig,
                                               os.path.dirname(bpf.path), set())[0]
                    if sub is not None:
                        return sub
                self.findings.append(Finding(
                    path, "unrecoverable",
                    "cannot evaluate macro %r from %s" % (name, bzl), line))
                return VError("unresolved macro %r" % name, C_LOW, node.line,
                              symbol=name)

        self.findings.append(Finding(
            path, "unrecoverable",
            "call to %r cannot be resolved to a static value" % (name or "<expr>"),
            node.line))
        return VError("unresolved call %r" % name, C_LOW, node.line, symbol=name)

    def _resolve_glob(self, node, path):
        pats = []
        exclude = []
        allow_empty = False
        for key, sub in node.kwargs.items():
            if key in ("include",):
                pats = _str_list(sub)
            elif key == "exclude":
                exclude = _str_list(sub)
            elif key == "allow_empty":
                allow_empty = bool(sub.value) if sub.kind == "bool" else False
        if not pats and node.args:
            pats = _str_list(node.args[0])
        header_only = bool(pats) and all(
            p.endswith((".h", ".hpp", ".hxx")) for p in pats)
        suppress = set(self.opts.suppress_globs)
        real_pats = [p for p in pats if p not in suppress]
        if header_only or not real_pats:
            g = VGlob(pats, exclude, allow_empty, conf=C_MEDIUM,
                      origin=node.line)
            self.findings.append(Finding(
                path, "note",
                "header-only glob(%s): no object line needed, -I covers it"
                % ", ".join(pats), node.line, C_MEDIUM))
            return g
        if self.opts.walk_globs:
            expanded = self._walk_glob(real_pats, exclude)
            if expanded is not None:
                self.findings.append(Finding(
                    path, "warn",
                    "glob(%s) expanded from the filesystem: %d files; "
                    "verify against the checked-in tree"
                    % (", ".join(real_pats), len(expanded)), node.line, C_MEDIUM))
                elems = [VStr(f, conf=C_MEDIUM, origin=node.line,
                              kind=VK_COMPUTED) for f in expanded]
                return VList(elems, conf=C_MEDIUM, origin=node.line,
                             kind=VK_COMPUTED)
            self.findings.append(Finding(
                path, "unrecoverable",
                "glob(%s) could not be expanded on disk" % ", ".join(real_pats),
                node.line))
            return VGlob(pats, exclude, allow_empty, conf=C_LOW,
                         origin=node.line)
        self.findings.append(Finding(
            path, "unrecoverable",
            "glob(%s): literal .c list lives in Bazel analysis, not in the "
            "file; use --walk-globs to expand it against the source tree"
            % ", ".join(real_pats), node.line))
        return VGlob(pats, exclude, allow_empty, conf=C_LOW, origin=node.line)

    def _walk_glob(self, patterns, exclude):
        if not patterns:
            return None
        found = set()
        root = self.dir
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames
                           if d not in (".git", "bazel-bin", "bazel-out",
                                        "bazel-testlogs", "node_modules")]
            for fname in filenames:
                full = os.path.join(dirpath, fname)
                rel = os.path.relpath(full, root).replace(os.sep, "/")
                for pat in patterns:
                    if _bazel_glob_match(pat, rel):
                        found.add(rel)
                        break
        for pat in exclude:
            for rel in list(found):
                if _bazel_glob_match(pat, rel):
                    found.discard(rel)
        return sorted(found)

    def _resolve_select(self, node, path, seen):
        branches = []
        default_key = None
        src = None
        if node.args:
            src = node.args[0]
        if src is None and "//conditions:default" in node.kwargs:
            src = node.kwargs["//conditions:default"]
        pairs = []
        if src is not None and src.kind == "dict":
            pairs = src.args
        elif src is not None and src.kind == "name":
            resolved = self._value_of(src, path + ".<select>", seen)
            if isinstance(resolved, VDict):
                pairs = [(knode, vnode) for knode, vnode in
                         [(k, v) for k, v in resolved.pairs]]
                branches = list(resolved.pairs)
        if pairs and not branches:
            for kn, vn in pairs:
                if isinstance(kn, SNode):
                    ks = kn.value if kn.kind == "str" else _key_str(
                        self._value_of(kn, path, seen), 0)
                    vv = self._value_of(vn, "%s{%s}" % (path, ks), seen)
                else:
                    ks = _key_str(kn, 0)
                    vv = vn
                branches.append((ks, vv))
                if ks == "//conditions:default":
                    default_key = ks
        if default_key is None and branches:
            default_key = branches[0][0]
        names = [b[0] for b in branches]
        self.findings.append(Finding(
            path, "unrecoverable",
            "select() over Bazel config_settings is not expressible in Kbuild; "
            "emitted the %r branch only.  All branches: %s"
            % (default_key or "<none>", ", ".join(names) or "<empty>"),
            node.line))
        return VSelect(branches, default_key, conf=C_LOW, origin=node.line,
                       reason="select() over Bazel config_settings")

    def _eval_comprehension(self, node, path, seen):
        try:
            pf, bzl_dir = self.pf, self.dir
            conf, kind, val = self.ev._eval(node, pf, bzl_dir, set(), {})
            return val if isinstance(val, Val) else VError("comprehension", C_LOW)
        except Exception as exc:
            return VError("comprehension failed: %r" % (exc,), C_LOW, node.line)

    def _eval_local_fn(self, fn, call_node, path, seen):
        bpf = ParsedFile(self.build_path)
        bpf.assigns = self.pf.assigns
        bpf.fn_defs = self.pf.fn_defs
        bpf.loads = self.pf.loads
        return self._eval_macro(bpf, fn, call_node, self.dir, path, call_node.line)

    def _eval_macro(self, pf, fn, call_node, bzl_dir, path, line):
        pos = []
        kwargs = {}
        for sub in call_node.args:
            pos.append(self._value_of(sub, path, set()))
        for key, sub in call_node.kwargs.items():
            kwargs[key] = self._value_of(sub, path, set())
        try:
            _, _, val = self.ev._call_user_fn(fn, pos, kwargs, pf, bzl_dir, set(),
                                              {})
        except Exception as exc:
            self.findings.append(Finding(
                path, "unrecoverable",
                "macro %r raised during evaluation: %r" % (fn.name, exc), line))
            return VError("macro %r" % fn.name, C_LOW, line)
        if not isinstance(val, Val):
            self.findings.append(Finding(
                path, "unrecoverable",
                "macro %r produced no static value" % fn.name, line))
            return VError("macro %r" % fn.name, C_LOW, line)
        if isinstance(val, VError):
            self.findings.append(Finding(
                path, "unrecoverable",
                "macro %r is build-graph driven: %s" % (fn.name, val.reason),
                line))
            return val
        note_conf = val.conf
        self.findings.append(Finding(
            path, "warn",
            "macro %r evaluated statically (%d items); diff against the .bzl"
            % (fn.name, len(val.elems) if isinstance(val, VList) else 0),
            line, note_conf))
        return val


def _key_str(val, idx):
    if isinstance(val, VStr):
        return val.s
    if isinstance(val, VBool):
        return str(val.b)
    try:
        return str(val.to_py())
    except Exception:
        return "key%d" % idx


def _str_list(node):
    """Literal strings from a list-shaped node.

    A non-literal entry is rendered as a placeholder (`<name>` / `<fn(...)>`)
    so the caller can report it rather than silently dropping it.
    """
    if node is None:
        return []
    if node.kind == "str":
        return [node.value]
    if node.kind in ("list", "tuple"):
        out = []
        for sub in node.args:
            if sub.kind == "str":
                out.append(sub.value)
        return out
    if node.kind == "name":
        return ["<%s>" % node.value]
    if node.kind == "call":
        callee = node.value
        nm = callee.value if callee is not None and callee.kind == "name" else "?"
        return ["<%s(...)>" % nm]
    return []


def _bazel_glob_match(pattern, relpath):
    if pattern.endswith("/**") or pattern == "**":
        prefix = pattern[:-3]
        return relpath.startswith(prefix) if prefix else True
    if "/**/" in pattern:
        head, _, tail = pattern.partition("/**/")
        if not (relpath == head or relpath.startswith(head.rstrip("/") + "/")):
            if head:
                return False
        return fnmatch.fnmatch(relpath.split("/")[-1], tail)
    if pattern.startswith("**/"):
        return fnmatch.fnmatch(relpath, pattern) or \
            fnmatch.fnmatch(relpath.split("/")[-1], pattern[3:])
    return fnmatch.fnmatch(relpath, pattern)


# ---------------------------------------------------------------------------
# Stage C1 -- Line, provenance, dependency classification
# ---------------------------------------------------------------------------

class Line(object):
    __slots__ = ("text", "kind", "conf", "origin", "note")

    def __init__(self, text, kind, conf=C_HIGH, origin=0, note=""):
        self.text = text
        self.kind = kind
        self.conf = conf
        self.origin = origin
        self.note = note

    def as_dict(self):
        return {"text": self.text, "kind": self.kind,
                "confidence": CONF_NAME[self.conf], "origin": self.origin}


def is_h(path):
    return path.endswith((".h", ".hpp", ".hxx", ".inc"))


def is_src(path):
    """A C/asm source that Kbuild compiles into an object.
    Rust (.rs) is deliberately excluded: Kbuild has no rule for it."""
    return path.endswith((".c", ".S", ".s"))


def is_rust(path):
    """A Rust source (.rs). Rust modules are built by DDK from a crate root so
    the source is Rust; it must NOT be lowered into a dummy `<mod>-y` object."""
    return path.endswith(".rs")


def is_label(path):
    return path.startswith("://") or path.startswith("//") or \
        path.startswith(":") or path.startswith("@")


def looks_like_headers_label(label):
    """Heuristic: a label naming a *_headers / headers-only target."""
    tail = label.split(":")[-1].split("/")[-1].lower()
    return ("header" in tail or tail in ("headers", "hdrs") or
            tail.endswith("_hdrs") or "hdr" in tail)


def looks_like_object_label(label):
    return label.endswith(".o") or label.endswith(".ko")


def ko_to_obj(out):
    """Bazel `out` (a .ko) -> the Kbuild object base name, plus a note."""
    name = out
    if name.endswith(".ko"):
        name = name[:-3]
    note = ""
    if "/" in name:
        note = "out %r contains '/': Kbuild object names cannot; flattened" % out
        name = name.replace("/", "_")
    if "." in name:
        if not note:
            note = "out %r contains '.': Kbuild object names cannot; " \
                   "dots replaced with '_'" % out
        name = name.replace(".", "_")
    return name, note


def _src_elems(val):
    """Return (literals, labels, unresolvable-notes) for a srcs value."""
    literals = []
    labels = []
    notes = []
    if val is None or isinstance(val, VNone):
        return literals, labels, notes
    if isinstance(val, (VGlob, VError, VSelect)):
        return literals, labels, notes
    if isinstance(val, VStr):
        (literals if not is_label(val.s) else labels).append(val.s)
        return literals, labels, notes
    if isinstance(val, (VList, VTuple)):
        for e in val.elems:
            l2, b2, n2 = _src_elems(e)
            literals.extend(l2)
            labels.extend(b2)
            notes.extend(n2)
        return literals, labels, notes
    if isinstance(val, VFileLabel):
        labels.append(val.label)
        return literals, labels, notes
    if isinstance(val, VDict):
        return literals, labels, notes
    return literals, labels, notes


def _to_obj_path(src):
    """A Bazel source path -> the object name Kbuild expects (foo.c -> foo.o)."""
    for ext in (".c", ".S", ".s", ".rs"):
        if src.endswith(ext):
            return src[:-len(ext)] + ".o"
    return src


def _config_from_label(label):
    """Best-effort Bazel config_setting label -> a CONFIG_ macro spelling.

    A `:rdo_bringup` / `//pkg:rdo_bringup` label becomes
    `CONFIG_RDO_BRINGUP` -- an *obvious placeholder*, never a claim that such a
    Kconfig symbol exists.  The emitted `ifdef` is intentionally a TODO the
    reviewer must map to the real config.
    """
    tail = label.split(":")[-1].split("/")[-1]
    cleaned = re.sub(r"[^0-9A-Za-z]+", "_", tail).strip("_").upper()
    return "CONFIG_" + cleaned if cleaned else "CONFIG_UNKNOWN"


# A config symbol whose name looks like an *optional* feature (debug/trace/test).
# Used ONLY to group the emitted switches with a `# debug features:` comment --
# every conditional_srcs entry becomes a switch regardless, because a gate like
# CONFIG_GOOG_TOUCH_INTERFACE is a real feature toggle, not debug.
_OPTIONAL_FEATURE_RE = re.compile(
    r"DEBUG|TRACE|KUNIT|_TEST|TEST_|SELFTEST|LOG|VERBOSE|DUMP|PROFIL|GCOV")


def is_optional_feature(cfg):
    """True if a CONFIG_* symbol names a debug/trace/test-style extra."""
    sym = cfg[len("CONFIG_"):] if cfg.startswith("CONFIG_") else cfg
    return bool(_OPTIONAL_FEATURE_RE.search(sym.upper()))


def _switch_name(cfg):
    """`CONFIG_DEBUG_FS` -> `DEBUGFS_SRCS`; a stable, human-flippable name."""
    sym = cfg[len("CONFIG_"):] if cfg.startswith("CONFIG_") else cfg
    cleaned = re.sub(r"[^0-9A-Za-z]+", "_", sym).strip("_").upper()
    return (cleaned or "FEATURE") + "_SRCS"


def _switch_block(mod, entries):
    """Render the inline on/off switch block for conditional sources.

    `entries` is a list of (config_symbol, true_objs, false_objs).  Mirrors the
    original Kbuild idiom seen throughout the akita reference tree
    (`ifneq ($(CONFIG_X),)` + `name-objs += obj.o`), but routes the guard
    through a named switch so a reviewer can clear ONE line and drop just that
    feature's sources instead of having to disable the whole module:

        GOOG_TOUCH_INTERFACE_SRCS ?= $(CONFIG_GOOG_TOUCH_INTERFACE)
        ifneq ($(CONFIG_GOOG_TOUCH_INTERFACE),)
        focal_touch-objs += focaltech_goog.o
        endif

    The default tracks the real CONFIG_* so behaviour is unchanged unless a
    switch is deliberately overridden.  When a False branch exists it is
    emitted under the switch's else path.
    """
    out = [
        "# --- optional features (clear a *_SRCS switch to drop its sources) ---",
        "# Each switch defaults to the matching kernel CONFIG_*; Kbuild"
        " semantics",
        "# are unchanged until you override one below.",
    ]
    names = []
    debug_names = []
    for cfg, _tobjs, _fobjs in entries:
        name = _switch_name(cfg)
        names.append((cfg, name))
        if is_optional_feature(cfg):
            debug_names.append(name)
        out.append("%s ?= $(%s)" % (name, cfg))
    if debug_names:
        out.append("# debug features above: %s" % ", ".join(debug_names))
    out.append("")

    for cfg, true_objs, false_objs in entries:
        name = _switch_name(cfg)
        if false_objs:
            # Both branches selectable under the one switch: empty -> False,
            # non-empty -> True, which is exactly $(CONFIG_X) empty vs set.
            out.append("ifeq ($(%s),)" % name)
            out.extend(_wrap_assign("%s-y += " % mod.obj, false_objs))
            out.append("else")
            out.extend(_wrap_assign("%s-y += " % mod.obj, true_objs))
            out.append("endif")
        else:
            out.append("ifneq ($(%s),)" % name)
            out.extend(_wrap_assign("%s-y += " % mod.obj, true_objs))
            out.append("endif")
        out.extend(_wrap_comment(
            "# plain Kbuild: %s-$(%s) += %s"
            % (mod.obj, cfg, " ".join(true_objs)), indent="#     "))
    return "\n".join(out)


# A `local_defines` entry that injects debug instrumentation (dynamic debug,
# debug logging) rather than a functional compile option.  These are the ones
# a reviewer most often wants to turn OFF for a production/debug-off build, so
# they get their own switch.  Matched against the bare name (no -D).
_DEBUG_DEFINE_RE = re.compile(r"^(DYNAMIC_DEBUG|DEBUG_|_DEBUG|.*_DEBUG_MODULE)")


def _is_debug_define(name):
    """True for a debug/logging-style -D that should be individually togglable."""
    bare = name.split("=", 1)[0]
    return bool(_DEBUG_DEFINE_RE.match(bare))


def _debug_define_block(mod, defs):
    """Named switch for debug-only -D defines (e.g. DYNAMIC_DEBUG_MODULE).

    Unlike conditional_srcs these do NOT gate objects: they change how the
    objects compile.  So the switch feeds `ccflags-y` and defaults to the
    original define list, meaning behaviour is unchanged until a reviewer
    clears `DEBUG_DEFINES` to build without the instrumentation.
    """
    origin = " ".join("-D" + d for d in defs)
    out = [
        "# --- debug compile flags (clear DEBUG_DEFINES to disable) ---",
        "# Defines, not source gates: clearing this builds the same objects "
        "with",
        "# the debug instrumentation off.  Default = the DDK local_defines.",
        "DEBUG_DEFINES ?= %s" % origin,
        "ccflags-y += $(DEBUG_DEFINES)",
        "# to disable:  DEBUG_DEFINES :=    (or drop it entirely)",
    ]
    return "\n".join(out)


def _module_enable_symbol(mod, ctx):
    """Best-effort recovery of the CONFIG_ symbol that enables this module.

    DDK's `ddk_module` does not record it, but the surrounding tree usually
    does (verified against the kernel-akita reference corpus):

      1. the local `Kconfig` next to the BUILD file: `config FOOBAR` entries,
         preferring one whose name matches the module/out name;
      2. an enclosing `Makefile`'s `KBUILD_OPTIONS += CONFIG_FOOBAR=m`.

    Returns (symbol_or_None, human_readable_origin).  The symbol is only ever
    returned when it was actually read from a file -- never guessed from the
    module name -- so we do not fabricate a CONFIG_ that may not exist.
    """
    base = os.path.dirname(ctx.build_path)

    # 1. Kconfig in this directory
    kcandidates = [os.path.join(base, "Kconfig"),
                   os.path.join(base, "Kconfig.ext")]
    syms = []
    for kpath in kcandidates:
        try:
            with open(kpath, encoding="utf-8", errors="replace") as fh:
                text = fh.read()
        except OSError:
            continue
        for m in re.finditer(r"^\s*(?:menu)?config\s+([A-Z0-9_]+)", text,
                             re.M):
            syms.append(("CONFIG_" + m.group(1), os.path.basename(kpath)))
    if syms:
        # Prefer a symbol whose stem matches the module name or object name
        # (e.g. module `focal_touch` / out `focal_touch.ko`).  Otherwise, if
        # there is exactly one symbol declared, accept it ONLY when it shares a
        # stem with the module -- a lone feature symbol (aoc_usb_driver's
        # Kconfig declares just AOC_USB_AUDIO_OFFLOAD) is not an enable gate.
        want = {mod.name.upper(), mod.obj.upper()}
        norm = lambda s: re.sub(r"[^A-Z0-9]", "", s.upper())
        wset = {norm(w) for w in want}
        for sym, src in syms:
            if norm(sym[len("CONFIG_"):]) in wset:
                return sym, "Kconfig `config` entry (%s)" % src
            if sym[len("CONFIG_"):].replace("_", "") in \
                    {w.replace("_", "") for w in want}:
                return sym, "Kconfig `config` entry (%s)" % src
        uniq = sorted(set(s for s, _ in syms))
        if len(uniq) == 1:
            stem = norm(uniq[0][len("CONFIG_"):])
            base_stem = stem
            for suf in ("DRIVER", "MODULE"):
                if base_stem.endswith(suf):
                    base_stem = base_stem[:-len(suf)]
                    break
            # `h2omg` module <- GOOGLE_H2OMG symbol: the module stem may appear
            # anywhere in the symbol (prefix or suffix), so match either way as
            # long as the overlap is the whole module name.
            if any(ms in base_stem or base_stem in ms for ms in wset):
                return uniq[0], "the only Kconfig `config` entry (%s)" \
                    % syms[0][1]

    # 2. enclosing Makefile KBUILD_OPTIONS
    for root in (base, os.path.dirname(base)):
        mpath = os.path.join(root, "Makefile")
        try:
            with open(mpath, encoding="utf-8", errors="replace") as fh:
                text = fh.read()
        except OSError:
            continue
        opts = re.findall(r"KBUILD_OPTIONS\s*\+?=\s*((?:[^\n\\]|\\\n)+)", text)
        found = []
        for chunk in opts:
            found.extend(re.findall(r"\b(CONFIG_[A-Z0-9_]+)\b", chunk))
        found = sorted(set(found))
        where = os.path.relpath(mpath, os.path.dirname(ctx.build_path))
        if len(found) == 1:
            return found[0], "Makefile KBUILD_OPTIONS (%s)" % where
        # Multiple candidates: pick the one whose stem best matches the module.
        want = {mod.name.upper(), mod.obj.upper()}
        norm = lambda s: re.sub(r"[^A-Z0-9]", "", s.upper())
        wset = {norm(w) for w in want}
        for sym in found:
            stem = sym[len("CONFIG_"):]
            if norm(stem) in wset or norm(stem.replace("_FTS", "")) in wset:
                return sym, "Makefile KBUILD_OPTIONS (%s)" % where

    # 3. A device defconfig.  The kernel's device trees carry the authoritative
    #    enable values, and they are sectioned per module by a
    #    `# private/google-modules/<pkg>/Kconfig` marker followed by that
    #    module's `CONFIG_*=...` lines.  This is the only source for the ~100
    #    modules whose package has no local Kconfig and no Makefile.
    hit = _symbol_from_device_defconfigs(mod, ctx)
    if hit is not None:
        return hit
    return None, ""


def _symbol_from_device_defconfigs(mod, ctx):
    """Find this module's enable symbol in a device defconfig.

    Scans `<root>/**/*defconfig` for sections marked by the module's package
    Kconfig path and returns the CONFIG_ symbol in that section that matches
    the module.  Returns (symbol, origin) or None.
    """
    root = getattr(ctx.opts, "repo_root", "") or ""
    if not root:
        return None
    # Which package path would its device defconfig section name?  Prefer the
    # module's own dir relative to the workspace root.
    rel = os.path.relpath(os.path.dirname(ctx.build_path), root)
    rel = rel.replace(os.sep, "/")
    # In a kernel checkout `private/google-modules` is usually a symlink to
    # `google-modules`, while defconfig section markers spell it either way.
    # Compare several spellings; the order is FIXED so the emitted finding (and
    # therefore the report) is byte-identical across runs.
    rel_variants = []
    if rel.startswith("private/"):
        rel_variants = [rel, rel[len("private/"):]]
    else:
        rel_variants = [rel, "private/" + rel]
    cand = _device_defconfigs(root,
                              extra_dirs=getattr(ctx.opts, "defconfig_dirs",
                                                 None))
    for path in cand:
        text = _read_text(path)
        if text is None:
            continue
        for rv in rel_variants:
            found = _section_symbols(text, rv, mod)
            if found is not None:
                return found[0], "device defconfig %s (section %s)" % (
                    os.path.relpath(path, root), rv)
    # Package-level fallback: the defconfig may set a single module gate for
    # the whole package (aoc: only `CONFIG_AOC_DRIVER=m`; the per-module
    # `AOC_CHAR_DRIVER` etc. are `default y` in Kbuild).  The original Kbuild
    # used that one gate for every module in the directory, so attribute it
    # when the section has exactly one `=m` symbol and no per-module match.
    for path in cand:
        text = _read_text(path)
        if text is None:
            continue
        for rv in rel_variants:
            pairs = _section_all_symbols(text, rv)
            if not pairs:
                continue
            as_m = [s for s, v in pairs if v == "m"]
            if len(as_m) == 1:
                return as_m[0], ("device defconfig %s (package gate, "
                                 "section %s)"
                                 % (os.path.relpath(path, root), rv))
    return None


def _device_defconfigs(root, limit=256, extra_dirs=None):
    """Every *defconfig file under the workspace's device trees.

    `extra_dirs` (from --defconfig) are searched FIRST and take precedence, so
    a caller can point at an out-of-tree device directory without relying on
    the auto-discovery guess.
    """
    out = []
    roots = list(extra_dirs or [])
    for top in ("google-devices", "private/devices", "devices"):
        d = os.path.join(root, *top.split("/"))
        if os.path.isdir(d):
            roots.append(d)
    for d in roots:
        if not os.path.isdir(d):
            continue
        for dirpath, dirnames, files in os.walk(d):
            dirnames[:] = [x for x in dirnames if x not in (".git",)]
            dirnames.sort()
            for fn in sorted(files):
                if "defconfig" in fn:
                    p = os.path.join(dirpath, fn)
                    if p not in out:
                        out.append(p)
            if len(out) >= limit:
                return out
    return out


_SECTION_RE = re.compile(r"^#\s*(.*?)/?Kconfig\s*$")
_CONFIG_RE = re.compile(r"^CONFIG_([A-Z0-9_]+)\s*=\s*(\S+)")


def _sections(text):
    """Parse a defconfig into {marker_path: [(symbol, value), ...]}.

    A device defconfig is sectioned by `# <pkg>/Kconfig` comments, each
    followed by that package's `CONFIG_*=...` lines.  Computed once per file
    and cached -- the same defconfig is consulted for every module in the tree.
    """
    key = ("sections", id(text))
    hit = _SCAN_CACHE.get(key)
    if hit is not None:
        return hit
    out = {}
    cur = None
    for line in text.splitlines():
        s = line.strip()
        if s.startswith("#"):
            m = _SECTION_RE.match(s)
            if m:
                cur = m.group(1).rstrip("/")
                out.setdefault(cur, [])
            continue
        if cur is None:
            continue
        m = _CONFIG_RE.match(s)
        if m:
            out[cur].append(("CONFIG_" + m.group(1), m.group(2)))
    _SCAN_CACHE[key] = out
    return out


def _section_pairs(text, rel_pkg):
    """(symbol, value) pairs for the `rel_pkg` section, or None if absent."""
    for marker, pairs in _sections(text).items():
        if marker.endswith(rel_pkg) or rel_pkg.endswith(marker):
            return pairs
    return None


def _section_symbols(text, rel_pkg, mod):
    """CONFIG_ symbols in `text` belonging to the `rel_pkg` section.

    Picks the symbol matching the module, else the section's only symbol.
    """
    pairs = _section_pairs(text, rel_pkg)
    if not pairs:
        return None
    symbols = [s for s, _v in pairs]
    if len(symbols) == 1:
        return symbols
    want = {mod.name.upper(), mod.obj.upper()}
    norm = lambda s: re.sub(r"[^A-Z0-9]", "", s.upper())
    wset = {norm(w) for w in want}
    # Drop common module-name decoration so `panel-samsung-s6e3hc4` can match
    # `CONFIG_DRM_PANEL_SAMSUNG_S6E3HC4` (strip a leading family word and the
    # `PANEL`/`DRM` prefixes the Kconfig symbol carries).
    tok = norm(mod.obj)
    for pre in ("PANEL", "DRM", "SND", "SOC", "GOOGLE", "GOOG", "MAX"):
        if tok.startswith(pre) and len(tok) > len(pre):
            wset.add(tok[len(pre):])
    for sym in symbols:
        stem = norm(sym[len("CONFIG_"):])
        if stem in wset:
            return [sym]
        base_stem = stem
        for suf in ("DRIVER", "MODULE"):
            if base_stem.endswith(suf):
                base_stem = base_stem[:-len(suf)]
                break
        if base_stem in wset:
            return [sym]
        # suffix match: the symbol ends with the module's distinctive stem
        # (DRM_PANEL_SAMSUNG_S6E3HC4 ends with S6E3HC4).
        for w in sorted(wset, key=len, reverse=True):
            if len(w) >= 6 and (stem.endswith(w) or w.endswith(stem)):
                return [sym]
    return None


def _section_all_symbols(text, rel_pkg):
    """(symbol, value) pairs in the `rel_pkg` section, or None if absent."""
    return _section_pairs(text, rel_pkg)


def _label_to_pkg_path(label):
    """`//private/google-modules/aoc:aoc.kconfig` -> `private/google-modules/aoc`.

    Returns None for a malformed/relative label.
    """
    if not label.startswith("//"):
        return None
    body = label[2:]
    if ":" in body:
        pkg = body.split(":", 1)[0]
    else:
        pkg = body
    return pkg or None


# ---------------------------------------------------------------------------
# Read/parse memoization
#
# A whole-tree conversion re-reads and re-parses the same few files hundreds of
# times: the device defconfigs once per module (~600 reads across three files),
# and a cross-package BUILD.bazel once per referring module.  A run never
# mutates its inputs, so a process-lifetime cache keyed on the absolute path is
# both correct and a large saving.  Callers see identical results.
# ---------------------------------------------------------------------------

_FILE_CACHE = {}     # abspath -> file text (or None if unreadable)
_PARSE_CACHE = {}    # abspath -> ParsedFile
_SCAN_CACHE = {}     # (abspath, kind) -> derived scan result


def _cache_clear():
    """Drop all memoized reads/parses (used by tests)."""
    _FILE_CACHE.clear()
    _PARSE_CACHE.clear()
    _SCAN_CACHE.clear()


def _read_text(path):
    """Read a file's text, memoized per process.  None if unreadable."""
    try:
        key = os.path.abspath(path)
    except (TypeError, ValueError):
        key = path
    if key in _FILE_CACHE:
        return _FILE_CACHE[key]
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError:
        text = None
    _FILE_CACHE[key] = text
    return text


def _parse_text_cached(path):
    """parse_text(path contents), memoized per process.  None if unreadable."""
    try:
        key = os.path.abspath(path)
    except (TypeError, ValueError):
        key = path
    if key in _PARSE_CACHE:
        return _PARSE_CACHE[key]
    text = _read_text(path)
    if text is None:
        _PARSE_CACHE[key] = None
        return None
    try:
        pf = parse_text(text, path)
    except Exception:
        pf = None
    _PARSE_CACHE[key] = pf
    return pf


def _kconfig_symbols(text):
    """`config FOO` / `menuconfig FOO` names declared in a Kconfig file."""
    return re.findall(r"^\s*(?:menu)?config\s+([A-Z0-9_]+)", text or "", re.M)


def _filegroup_kconfig_paths(parsed, rule_node):
    """For `filegroup(name="x.kconfig", srcs=["Kconfig", ...])` -> the src paths.

    Only literal string entries are returned; a glob or label is reported by the
    caller as unresolved rather than guessed at.
    """
    out = []
    for s in _str_list_unsafe(rule_node.kwargs.get("srcs")):
        if not s.startswith("//") and not s.startswith(":"):
            out.append(s)
    return out


def _str_list_unsafe(node):
    """Like _str_list but tolerant of call/name nodes; returns [] on oddities."""
    try:
        return _str_list(node)
    except Exception:
        return []


def build_config_scaffold(build_path, pf, opts):
    """Reconstruct the config chain a BUILD.bazel participates in.

    Returns a dict with:
      module : list of per-module config facts (kconfig/defconfig, ddk_config
               target it links to, and the symbols its conditional_srcs reads)
      package_kconfigs : [(label_name, [src paths])] from filegroup(*.kconfig)
      ddk_configs : [(name, {kconfigs, defconfig, deps})]
      findings : [Finding]
    """
    base = os.path.dirname(build_path)
    facts = {
        "module": [],
        "package_kconfigs": [],
        "ddk_configs": [],
        "findings": [],
    }

    # index top-level rules by name for `config = ":target"` resolution
    index = {}
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        if nm is not None and nm.kind == "str":
            index[nm.value] = (fn, node)

    # 1. filegroup(name="*.kconfig") -> the Kconfig files this package exports
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        name = nm.value if nm is not None and nm.kind == "str" else ""
        if fn in ("filegroup", "exports_files") and name.endswith(".kconfig"):
            srcs = _filegroup_kconfig_paths(pf, node)
            present = []
            for s in srcs:
                if os.path.exists(os.path.join(base, s)):
                    present.append(s)
                else:
                    facts["findings"].append(Finding(
                        "config", "note",
                        "filegroup %r lists %r which is not present next to the "
                        "BUILD file" % (name, s), node.line, C_MEDIUM))
            facts["package_kconfigs"].append((name, present))

    # 2. ddk_config(...) targets
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        if fn != "ddk_config":
            continue
        nm = node.kwargs.get("name")
        name = nm.value if nm is not None and nm.kind == "str" else "<anon>"
        kcs = _str_list_unsafe(node.kwargs.get("kconfigs"))
        dfc = node.kwargs.get("defconfig")
        dfc_s = dfc.value if dfc is not None and dfc.kind == "str" else None
        deps = _str_list_unsafe(node.kwargs.get("deps"))
        facts["ddk_configs"].append((name, {
            "kconfigs": kcs, "defconfig": dfc_s, "deps": deps,
            "line": node.line,
        }))

    # 3. each ddk_module: legacy kconfig/defconfig, config=":ddk_config", and
    #    the symbols its conditional_srcs reads
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        if fn not in ("ddk_module", "ddk_submodule"):
            continue
        nm = node.kwargs.get("name")
        name = nm.value if nm is not None and nm.kind == "str" else "<anon>"
        kc = node.kwargs.get("kconfig")
        dfc = node.kwargs.get("defconfig")
        cfg = node.kwargs.get("config")
        linked = None
        if cfg is not None and cfg.kind == "str" and cfg.value.startswith(":"):
            linked = cfg.value[1:]
        reads = []
        cs = node.kwargs.get("conditional_srcs")
        if cs is not None and cs.kind == "dict":
            for k, _v in cs.args:
                if k is not None and k.kind == "str":
                    reads.append(k.value)
        facts["module"].append({
            "name": name,
            "line": node.line,
            "kconfig": kc.value if kc is not None and kc.kind == "str" else None,
            "defconfig": dfc.value if dfc is not None and dfc.kind == "str"
            else None,
            "linked_config": linked,
            "reads": reads,
        })
    return facts


def render_module_config(base, facts, opts):
    """Module-level Kconfig/defconfig scaffold text, or '' when nothing to say."""
    lines = [
        "# AUTO-GENERATED by ddk2kbuild.py -- CONFIG RECONSTRUCTION",
        "#",
        "# This package's config selection is NOT in the BUILD file.  The chain is:",
        "#   device defconfig  ->  sets CONFIG_*",
        "#   Kconfig / *.kconfig  ->  declares CONFIG_*",
        "#   ddk_module.conditional_srcs  ->  reads CONFIG_*",
        "# Kbuild keeps the same shape (Kconfig + defconfig), so nothing needs to",
        "# move -- only the files below must exist and be sourced.",
    ]
    declared = []
    for name, paths in facts["package_kconfigs"]:
        for p in paths:
            text = _read_text(os.path.join(base, p))
            syms = _kconfig_symbols(text)
            if syms:
                declared.extend(syms)
                lines.append("#   Kconfig %s declares: %s"
                             % (p, " ".join("CONFIG_" + s for s in syms)))
            else:
                lines.append("#   Kconfig %s (empty or unreadable)" % p)

    if facts["ddk_configs"]:
        lines.append("#")
        lines.append("# ddk_config targets:")
        for cname, info in facts["ddk_configs"]:
            dfc = info["defconfig"] or "<none>"
            kcs = ", ".join(info["kconfigs"]) or "<none>"
            lines.append("#   %s: kconfigs=[%s] defconfig=%s" % (cname, kcs, dfc))
            if info["defconfig"]:
                dfc_text = _read_text(os.path.join(base, info["defconfig"]))
                if dfc_text is not None:
                    for ln in dfc_text.splitlines():
                        if ln.strip().startswith("CONFIG_"):
                            lines.append("#     %s" % ln.strip())

    reads = sorted(set(s for m in facts["module"] for s in m["reads"]))
    if reads:
        lines.append("#")
        lines.append("# CONFIG_* this package reads in conditional_srcs:")
        for r in reads:
            got = "declared here" if r[len("CONFIG_"):] in declared \
                else "NOT declared by this package -- set in the device defconfig"
            lines.append("#   %s (%s)" % (r, got))
    return "\n".join(lines) + "\n"


def render_device_config(base, facts, device_name, opts):
    """Device-level Kconfig.ext + merged defconfig scaffold text."""
    lines = [
        "# AUTO-GENERATED by ddk2kbuild.py -- DEVICE CONFIG RECONSTRUCTION",
        "# device: %s" % device_name,
        "#",
        "# Kconfig.ext: which module Kconfigs the kernel sees.  In Kbuild this is",
        "# the `source \"...\"` chain in the arch/defconfig flow; keep these lines",
        "# (adapting the $(KCONFIG_*) prefix variables from build.config).",
    ]
    for label in facts["kconfigs"]:
        pkg = _label_to_pkg_path(label)
        if pkg is None:
            lines.append("#   TODO(manual): unresolvable kconfig label %r" % label)
            continue
        lines.append('source "%s/Kconfig"' % pkg)
    for ext in facts["kconfig_exts"]:
        lines.append("#   kconfig_ext: %s (source chain lives there)" % ext)

    lines.append("")
    lines.append("# Merged defconfig fragment (from defconfig_fragments):")
    for frag in facts["defconfig_fragments"]:
        path = frag if os.path.isabs(frag) else os.path.join(base, frag)
        text = _read_text(path)
        if text is None:
            lines.append("#   TODO(manual): missing fragment %s" % frag)
            continue
        lines.append("# ---- %s ----" % frag)
        for ln in text.splitlines():
            s = ln.strip()
            if s and not s.startswith("#"):
                lines.append(s)

    if facts["build_configs"]:
        lines.append("")
        lines.append("# build.config files set PATH VARIABLES, not CONFIG_* "
                     "symbols:")
        for bc in facts["build_configs"]:
            lines.append("#   %s" % bc)
    return "\n".join(lines) + "\n"


def build_device_facts(build_path, pf):
    """Extract config facts from a `device_build(...)` target.

    Returns a list of (device_name, facts, line) -- one per device_build rule
    in the file -- or [] when the file declares none.
    """
    out = []
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        if fn not in ("device_build", "kernel_build", "ddk_config"):
            continue
        nm = node.kwargs.get("name")
        name = nm.value if nm is not None and nm.kind == "str" else "<anon>"
        facts = {
            "kconfigs": _str_list_unsafe(node.kwargs.get("kconfigs")),
            "kconfig_exts": _str_list_unsafe(node.kwargs.get("kconfig_exts")),
            "defconfig_fragments": _str_list_unsafe(
                node.kwargs.get("defconfig_fragments")),
            "build_configs": _str_list_unsafe(node.kwargs.get("build_configs")),
            "rule": fn,
        }
        if fn == "ddk_config":
            dfc = node.kwargs.get("defconfig")
            if dfc is not None and dfc.kind == "str":
                facts["defconfig_fragments"] = [dfc.value]
        if any(facts[k] for k in ("kconfigs", "kconfig_exts",
                                  "defconfig_fragments")):
            out.append((name, facts, node.line))
    return out


def _write_or_buffer(res, key, filename, text, out_dir, opts):
    """Record a generated config file: print under --stdout, else note path."""
    if opts.stdout:
        res["config_text"] = res.get("config_text", "")
        res["config_text"] += "\n# ---- %s (%s) ----\n%s" % (
            filename, res["build_path"], text)
        return
    if opts.dry_run or out_dir is None:
        res.setdefault("config_files", []).append((filename, None, text))
        return
    dest = os.path.join(out_dir, filename)
    if os.path.exists(dest):
        # never clobber a real hand-written file
        base, ext = os.path.splitext(dest)
        dest = base + ".generated" + (ext if ext else "")
        res["warnings"].append(
            "%s exists; wrote %s instead" % (filename, os.path.basename(dest)))
    try:
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w", encoding="utf-8") as fh:
            fh.write(text)
        res.setdefault("config_files", []).append((filename, dest, text))
    except OSError as exc:
        res["warnings"].append("cannot write %s: %s" % (dest, exc))


def _process_config(build_path, pf, res, opts):
    """Build module-level and/or device-level config scaffolds for one file."""
    base = os.path.dirname(build_path)
    # Mirror the package tree under --out, so a whole-tree run does not have
    # every package fighting over one Kconfig.reconstructed.
    if opts.out:
        out_dir = os.path.join(opts.out, os.path.relpath(base, opts.repo_root))
    else:
        out_dir = base
    scope = opts.config_scope

    if scope in ("module", "both"):
        facts = build_config_scaffold(build_path, pf, opts)
        res["config_facts"] = facts
        for f in facts["findings"]:
            res["file_findings"].append(f)
        if facts["package_kconfigs"] or facts["ddk_configs"] or \
                any(m["reads"] for m in facts["module"]):
            text = render_module_config(base, facts, opts)
            _write_or_buffer(res, "module_config", "Kconfig.reconstructed",
                             text, out_dir, opts)

    if scope in ("device", "both"):
        devices = build_device_facts(build_path, pf)
        if opts.device:
            devices = [d for d in devices if d[0] == opts.device]
        for dname, dfacts, line in devices:
            text = render_device_config(base, dfacts, dname, opts)
            _write_or_buffer(
                res, "device_config",
                "Kconfig.ext.%s.reconstructed" % dname, text, out_dir, opts)
            res.setdefault("devices", []).append(dname)


def _label_kind(label, resolver):
    """Classify a cross-package label.

    Returns (kind, resolved_rule, resolved_node) where kind is one of
    'headers' | 'module' | 'library' | 'object' | 'unknown'.
    """
    if label.startswith(":"):
        fn, node = resolver.resolve_file_scoped(label[1:])
        if fn is None:
            return "unknown", None, None
        return _rule_kind(fn), fn, node
    # `//pkg:target` / `//pkg`: read that package's BUILD.bazel and look the
    # target up, so a header provider is classified from its real rule rather
    # than guessed from the target's name (which fails for e.g. `//other:h`).
    fn, node = _lookup_cross_package_target(label, resolver)
    if fn is not None:
        return _rule_kind(fn), fn, node
    if looks_like_headers_label(label):
        return "headers", None, None
    if looks_like_object_label(label):
        return "object", None, None
    # A bare //pkg label points at the default target of that package: a
    # module, per the *-ipc / google-dpa convention.
    return "module", None, None


def _rule_kind(fn):
    """Map a Bazel rule/function name to a dependency kind."""
    if fn in ("ddk_headers", "ddk_uapi_headers"):
        return "headers"
    if fn == "ddk_library":
        return "library"
    if fn in ("ddk_module", "ddk_submodule"):
        return "module"
    if fn == "ddk_prebuilt_object":
        return "object"
    if fn in ("filegroup", "copy_files", "_ddk_conditional_filegroup",
              "select_files"):
        # A plain source container: `DefaultInfo.files = transitive(srcs)`.
        # Referenced from `srcs`, its files belong to the consuming module.
        return "filegroup"
    return "unknown"


def _label_to_pkg_dir(label, root):
    """`//pkg:target` -> the directory holding its BUILD.bazel.

    `//common:X` is special: the ACK kernel calls its workspace `common`, so
    `//common:all_headers_aarch64` lives in the workspace ROOT's BUILD.bazel
    (`<root>/BUILD.bazel`), not `<root>/common/BUILD.bazel`.
    """
    if not label.startswith("//"):
        return None, None
    body = label[2:]
    if ":" in body:
        pkg, target = body.split(":", 1)
    else:
        pkg, target = body, body.split("/")[-1]
    if pkg == "common":
        return root, target
    if not pkg:
        return root, target
    return os.path.join(root, pkg), target


def _lookup_cross_package_target(label, resolver):
    """(rule_fn, node) for `//pkg:target` read from that package's BUILD.bazel."""
    if not label.startswith("//"):
        return None, None
    opts = getattr(resolver, "opts", None)
    root = getattr(opts, "repo_root", "") or ""
    pkgdir, target = _label_to_pkg_dir(label, root)
    if pkgdir is None:
        return None, None
    build = os.path.join(pkgdir, "BUILD.bazel")
    if not os.path.isfile(build):
        return None, None
    pf = _parse_text_cached(build)
    if pf is None:
        return None, None
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        if nm is not None and nm.kind == "str" and nm.value == target:
            return fn, node
    return None, None


def label_to_module_syms(label, repo_pkg_root):
    """Map a cross-package module label to a third_party/... module_syms key."""
    if label.startswith("@"):
        return None
    body = label.lstrip("/")
    if ":" in body:
        pkg, target = body.split(":", 1)
    else:
        pkg, target = body, body.split("/")[-1]
    rel = pkg
    if not rel.strip("/"):
        # A label with no package component (e.g. `//:foo`) has no directory
        # to point module_syms at; emitting an empty key yields a broken
        # `$(call module_syms,)` -- signal "unresolvable" instead.
        return None
    # module_syms takes the *directory* holding the .ko / Module.symvers.
    return rel + "/" if rel else ""


def _dirs_from_val(val):
    """Collect literal include dirs from a resolved includes/linux_includes Val.

    Handles `["a", "b"] + select({...})` (a VSelect whose `base` holds the
    unconditional literal part and whose branches hold the conditional parts)
    as well as plain lists/tuples/strings.  Select branches are environment
    dependent, so every branch is collected as a best-effort union.
    """
    out = []
    if val is None or isinstance(val, VError):
        return out
    if isinstance(val, VSelect):
        if val.base is not None:
            out.extend(_dirs_from_val(val.base))
        for _cond, bv in val.branches:
            out.extend(_dirs_from_val(bv))
        return out
    if isinstance(val, (VList, VTuple)):
        for e in val.elems:
            out.extend(_dirs_from_val(e))
        return out
    if isinstance(val, VStr):
        out.append(val.s)
    return out


def _val_is_env_dependent(val):
    if isinstance(val, VSelect) or isinstance(val, VError):
        return True
    if isinstance(val, (VList, VTuple)):
        return any(_val_is_env_dependent(e) for e in val.elems)
    return False


def _includes_is_env_dependent(rule_node, resolver):
    """True if a ddk_headers target's includes are select()/unresolvable."""
    if rule_node is None:
        return False
    for attr in ("includes", "linux_includes"):
        node = rule_node.kwargs.get(attr)
        if node is None:
            continue
        val = resolver.value_of(node, attr) if resolver is not None else None
        if _val_is_env_dependent(val):
            return True
    return False


def resolve_cross_package_headers(label, ctx):
    """`//pkg:target` where target is a ddk_headers -> its include dirs.

    BzlLoader cannot do this: it only resolves labels within the current
    package.  The needed info IS in the tree, though -- the label names the
    package and the sibling BUILD.bazel declares the target's `includes`.  Both
    files are parsed with the same parser.

    Returns (dirs, pkg_rel) or ([], None) when the target cannot be read.
    """
    if not label.startswith("//"):
        return [], None
    repo_root = getattr(ctx.opts, "repo_root", "") or ""
    pkgdir, target = _label_to_pkg_dir(label, repo_root)
    if pkgdir is None:
        return [], None
    build = os.path.join(pkgdir, "BUILD.bazel")
    if not os.path.isfile(build):
        return [], None
    rel = os.path.relpath(pkgdir, repo_root) if repo_root else pkgdir
    if rel == ".":
        rel = ""
    pf = _parse_text_cached(build)
    if pf is None:
        return [], None
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        if nm is None or nm.kind != "str" or nm.value != target:
            continue
        if fn not in ("ddk_headers", "ddk_uapi_headers"):
            return [], rel
        # includes may be a list, a concatenation, or a select(); use a local
        # resolver so all forms resolve.  collect_include_dirs also follows
        # header-target aliases (`hdrs = [":other"]`).
        try:
            res = Resolver(build, pf, BzlLoader(repo_root, False), ctx.opts)
        except Exception:
            res = None
        dirs = collect_include_dirs(node, res)
        return dirs, rel
    return [], rel


def collect_include_dirs(rule_node, resolver, visited=None):
    """Return the include dirs provided by a local ddk_headers target.

    Follows header-target aliases: a ddk_headers may carry no `includes` of its
    own and instead re-export another target via `hdrs = [":other"]`, so the
    real include dirs live one (or more) hops away.
    """
    visited = visited if visited is not None else set()
    out = []
    if rule_node is None:
        return out
    nm = rule_node.kwargs.get("name")
    key = nm.value if nm is not None and nm.kind == "str" else id(rule_node)
    if key in visited:
        return out
    visited.add(key)
    for attr in ("includes", "linux_includes"):
        node = rule_node.kwargs.get(attr)
        if node is None:
            continue
        # Resolve through the value engine so concatenation (`["a"] + ...`)
        # and select() are understood, not just literal list nodes.
        val = resolver.value_of(node, attr) if resolver is not None else None
        for d in _dirs_from_val(val):
            if d not in out:
                out.append(d)
    # Follow aliases: hdrs/deps entries that point at another header target,
    # either locally (`:other`) or in another package (`//pkg:other`).  A
    # ddk_headers frequently carries no `includes` of its own and only
    # re-exports other providers (e.g. panels:common_headers ->
    # //.../display/common:ddk_headers), so the real dirs are one hop away.
    if resolver is not None:
        for attr in ("hdrs", "deps"):
            node = rule_node.kwargs.get(attr)
            if node is None:
                continue
            for sub in _label_strings(node):
                if sub.startswith(":"):
                    fn2, node2 = resolver.resolve_file_scoped(sub[1:])
                    if node2 is None:
                        continue
                    for d in collect_include_dirs(node2, resolver, visited):
                        if d not in out:
                            out.append(d)
                elif sub.startswith("//"):
                    fn2, node2 = _lookup_cross_package_target(sub, resolver)
                    if node2 is None:
                        continue
                    # Cross-package targets need a resolver bound to THAT
                    # file; build one so nested `includes`/`select` resolve.
                    xres = _resolver_for_label(sub, resolver)
                    if xres is None:
                        continue
                    for d in collect_include_dirs(node2, xres, visited):
                        if d not in out:
                            out.append(d)
    return out


def _resolver_for_label(label, resolver):
    """A Resolver bound to the BUILD.bazel that `//pkg:target` lives in."""
    opts = getattr(resolver, "opts", None)
    root = getattr(opts, "repo_root", "") or ""
    pkgdir, _target = _label_to_pkg_dir(label, root)
    if pkgdir is None:
        return None
    build = os.path.join(pkgdir, "BUILD.bazel")
    pf = _parse_text_cached(build)
    if pf is None:
        return None
    try:
        return Resolver(build, pf, BzlLoader(root, False), opts)
    except Exception:
        return None


def _label_strings(node):
    """Literal `:target` / `//pkg:target` strings in a list-shaped node."""
    out = []
    if node is None:
        return out
    if node.kind == "str":
        return [node.value]
    if node.kind in ("list", "tuple"):
        for e in node.args:
            if e.kind == "str":
                out.append(e.value)
    return out


# ---------------------------------------------------------------------------
# Stage C2 -- Module model + rule registry
# ---------------------------------------------------------------------------

class ModIR(object):
    """One ddk_module / ddk_submodule lowered to Kbuild facts."""

    def __init__(self, name, rule_name, line):
        self.name = name
        self.rule_name = rule_name
        self.line = line
        self.out = ""
        self.obj = ""
        self.obj_note = ""
        self.fingerprint = ""
        self.parts = []          # ordered list of Kbuild fragments
        self.lines = []          # list[Line] after rendering
        self.findings = []
        self.deps = []           # [(label, kind)]
        self.extras = []         # EXTRA_SYMBOLS module_syms keys
        self.unconditional = []
        self.conditional = []    # [(config, true_objs, false_objs|None)]
        self.flags = []          # ccflags fragments in order
        self.kernel_build = ""
        self.kconfig = None
        self.defconfig = None
        self.hdrs = []
        self.is_library = False
        self.empty_reason = ""

    # -- model -------------------------------------------------------------
    def confidence(self):
        """The min over emitted lines, joined with the worst *loss*.

        Informational notes ('note'/'warn') describe what the converter did and
        must not lower the score.  A 'lossy' finding caps at MEDIUM and an
        'unrecoverable' one at LOW, so a module can never read HIGH while some
        part of the DDK target could not be expressed in Kbuild.
        """
        conf = C_UNKNOWN if not self.lines else max(l.conf for l in self.lines)
        for f in self.findings:
            if f.kind == "unrecoverable":
                conf = max(conf, C_LOW)
            elif f.kind == "lossy":
                conf = max(conf, C_MEDIUM)
        return conf

    def confidence_lines(self):
        """The emitted lines that hold the module at its worst confidence."""
        top = self.confidence()
        return [l for l in self.lines if l.conf == top]

    def summary(self):
        return {
            "name": self.name,
            "rule": self.rule_name,
            "out": self.out,
            "obj": self.obj,
            "fingerprint_ko": self.fingerprint,
            "line": self.line,
            "n_srcs": len(self.unconditional) + sum(
                len(e[1]) + len(e[2] or []) for e in self.conditional),
            "n_conditional": len(self.conditional),
            "confidence": CONF_NAME[self.confidence()],
            "valid": build_output_valid(self),
            "empty_reason": self.empty_reason,
            "findings": [f.as_dict() for f in self.findings],
        }

    def render(self):
        """Render fragments to Lines with per-fragment provenance."""
        out = []
        for frag in self.parts:
            if isinstance(frag, Line):
                out.append(frag)
                continue
            kind, conf, origin, text = frag
            if text is None:
                continue
            for ln in text.split("\n"):
                out.append(Line(ln, kind, conf, origin))
        self.lines = out
        return out


def _frag(kind, conf, origin, text):
    return (kind, conf, origin, text)


class RuleContext(object):
    """Everything the emitter rules need."""

    def __init__(self, resolver, opts, build_path):
        self.resolver = resolver
        self.opts = opts
        self.build_path = build_path
        self.headers_targets = {}     # name -> (fn, node)
        self.other_rules = {}         # name -> (fn, node)
        self.all_mods = []
        self.rule_notes = []

    def lookup(self, name):
        fn, node = self.resolver.resolve_file_scoped(name)
        return fn, node


def _include_lines(ctx, mod, val, attr, prepend=False):
    """Emit ccflags -I lines for an `includes`/`linux_includes` value."""
    dirs = []
    conf = C_HIGH
    origin = 0
    if isinstance(val, VList):
        conf = val.conf
        for e in val.elems:
            if isinstance(e, VStr):
                dirs.append(e.s)
            elif isinstance(e, VError):
                conf = max(conf, C_LOW)
                mod.findings.append(Finding(
                    attr, "unrecoverable",
                    "include directory from an unresolved value: %s" % e.reason,
                    e.origin))
        origin = val.origin
    elif isinstance(val, VError):
        mod.findings.append(Finding(attr, "unrecoverable",
                                    "includes could not be resolved: %s"
                                    % val.reason, val.origin))
        return
    else:
        return
    if not dirs:
        return
    if attr == "linux_includes":
        text = " ".join("-I$(srctree)/%s" % d for d in dirs)
        mod.flags.append((conf, origin, text))
        mod.findings.append(Finding(
            attr, "lossy",
            "linux_includes approximated as -I$(srctree)/... appended to "
            "ccflags-y; Kbuild's LINUXINCLUDE prepend order is not reproduced",
            origin, C_MEDIUM))
    else:
        text = " ".join("-I$(src)/%s" % d for d in dirs)
        mod.flags.append((conf, origin, text))


def emit_module(ctx, mod, node, rule_name):
    """Stage C: lower one ddk_module node into Kbuild fragments."""
    r = ctx.resolver
    line = node.line
    # Findings are per-module, not per-file: take a private slice so an
    # earlier module's notes can never leak into this one.
    r.findings = []

    def kw(name):
        return node.kwargs.get(name)

    # out / obj ----------------------------------------------------------
    out_node = kw("out")
    if out_node is not None and out_node.kind == "str":
        mod.out = out_node.value
    if not mod.out:
        out_guess = mod.name + ".ko" if not mod.name.endswith(".ko") else mod.name
        mod.out = out_guess
        mod.findings.append(Finding(
            "out", "warn",
            "no `out` attribute: assumed %r (Kbuild uses obj-m += %s)"
            % (out_guess, ko_to_obj(out_guess)[0] + ".o"), line, C_MEDIUM))

    base, note = ko_to_obj(mod.out)
    if note:
        mod.findings.append(Finding("out", "lossy", note, line, C_MEDIUM))
    # Kbuild: the object name is <basename>.o, and the compiler appends "_" to
    # the object name to derive the .ko, so `-DKBAIL_MODULE_NAME=<base>_` works.
    mod.obj = base
    mod.fingerprint = base + ".ko"
    if mod.out != mod.fingerprint:
        mod.findings.append(Finding(
            "out", "lossy",
            "Bazel `out` %r differs from the Kbuild footprint %r; the "
            "compiler always produces <obj>.ko"
            % (mod.out, mod.fingerprint), line, C_MEDIUM))

    # srcs ---------------------------------------------------------------
    srcs_val = r.value_of(kw("srcs"), "srcs")
    literals, labels, _ = _src_elems(srcs_val)
    src_objs = []
    rust_lits = []
    for lit in literals:
        if is_rust(lit):
            # A .rs source is a Rust crate source; Kbuild has no rule for it
            # and must not be given a bogus `<mod>-y := foo_rs.o`.
            rust_lits.append(lit)
        elif is_src(lit):
            src_objs.append(lit)
        elif is_h(lit):
            src_objs.append(lit)   # header: tracked, no object
    if rust_lits:
        mod.parts.append(_frag(
            "todo", C_LOW, line,
            "# TODO(manual): Rust module source(s): %s\n"
            "#   DDK builds Rust via crate_root; Kbuild has no .rs rule.\n"
            "#   Rust modules are not supported by the classic Kbuild build."
            % ", ".join(rust_lits)))
        mod.findings.append(Finding(
            "srcs", "unrecoverable",
            "Rust source(s) %s: Kbuild cannot build Rust modules"
            % ", ".join(rust_lits), line, C_LOW))
    if isinstance(srcs_val, VGlob):
        pats = ", ".join(srcs_val.patterns)
        mod.parts.append(_frag(
            "todo", C_LOW, srcs_val.origin,
            "# TODO(manual): srcs = glob([%s]) -- list the files explicitly.\n"
            "#   Kbuild cannot reproduce Bazel's ** recursion or its include "
            "order." % pats))
        mod.findings.append(Finding(
            "srcs", "unrecoverable",
            "srcs came from glob([%s]); the literal .c list is not in the "
            "BUILD file" % pats, srcs_val.origin))
    elif isinstance(srcs_val, VSelect):
        # `A + select({...})` keeps the literal part A on `srcs_val.base`.
        # A is unconditional in Bazel (the select only adds the selected
        # branch), so it MUST contribute objects/headers regardless of which
        # branch wins.  Dropping it silently loses whole module bodies.
        if srcs_val.base is not None:
            _collect_src_objs(srcs_val.base, mod, src_objs, ctx)
        dval = srcs_val.default_value()
        dl, dlabels, _ = _src_elems(dval)
        src_objs.extend([d for d in dl if is_src(d)])
        branches = ", ".join(srcs_val.branch_names())
        # Emit EVERY branch that carries a real source list, not just the
        # default one.  A Bazel `select()` over config_settings maps naturally
        # onto Kbuild `ifdef`/`ifeq` conditionals: the branch label names the
        # Bazel config_setting (":rdo_bringup") and the sources are the files
        # that config selects.  The default branch is applied unconditionally,
        # matching Bazel's semantics for the unselected case.
        emitted = []
        for bcond, bval in srcs_val.branches:
            bfiles = []
            # A branch value may itself be `const_list + select(...)`: the
            # literal part is unconditional within that branch and its
            # sources would otherwise vanish with the branch.
            if isinstance(bval, VSelect) and bval.base is not None:
                bl, _, _ = _src_elems(bval.base)
                bfiles.extend(d for d in bl if is_src(d))
            bl, blabels, _ = _src_elems(bval)
            bfiles.extend(d for d in bl if is_src(d))
            # A branch may name a filegroup target instead of listing files
            # (the v1/v2 split: select({is_v2: ["//pkg/v2:tgt"], default:
            # ["//pkg/v1:tgt"]})).  Resolve it so the branch keeps its sources.
            for lbl in list(blabels) + _src_label_elems(bval):
                fkind, _fn, fnode = _label_kind(lbl, ctx.resolver)
                if fkind != "filegroup":
                    continue
                fgfiles, _n = _filegroup_sources(
                    lbl, fnode, ctx, pkgdir=os.path.dirname(ctx.build_path))
                bfiles.extend(f for f in fgfiles if is_src(f))
            if not bfiles:
                continue
            emitted.append((bcond, bfiles))
        if emitted:
            lines = [
                "# TODO(manual): srcs = select({...}) -- Bazel config_setting ->",
                "#   Kbuild conditional.  Replace each placeholder condition with",
                "#   the real CONFIG_* that %r selects." % (srcs_val.default_key,),
            ]
            for bcond, bfiles in emitted:
                lines.append(
                    "#   ifdef %s   # Bazel config_setting %s"
                    % (_config_from_label(bcond), bcond))
                lines.append("#   %s-y += %s"
                             % (mod.obj, " ".join(_to_obj_path(f) for f in bfiles)))
                lines.append("#   endif")
            mod.parts.append(_frag("todo", C_LOW, srcs_val.origin,
                                   "\n".join(lines)))
            mod.findings.append(Finding(
                "srcs", "unrecoverable",
                "srcs=select(): the %r branch is unconditional; branches %s "
                "need Kbuild conditionals (see the TODO block; the file lists "
                "were recovered, the Bazel config_setting -> CONFIG_ mapping "
                "was not)" % (srcs_val.default_key, branches),
                srcs_val.origin))
        else:
            mod.parts.append(_frag(
                "todo", C_LOW, srcs_val.origin,
                "# TODO(manual): srcs = select({...}) -- the following is the\n"
                "#   %r branch only.  Enumerate all branches in Kbuild:\n"
                "#   %s"
                % (srcs_val.default_key, branches)))
            mod.findings.append(Finding(
                "srcs", "unrecoverable",
                "srcs=select(): only the %r branch was emitted; branches %s are "
                "environment-dependent" % (srcs_val.default_key, branches),
                srcs_val.origin))
        # The default branch is unconditional in Bazel, so its sources must
        # land in <mod>-y even though the other branches need hand-written
        # Kbuild conditionals.  Resolve it through filegroups too -- otherwise
        # `srcs = select({is_v2: ["//pkg/v2:t"], default: ["//pkg/v1:t"]})`
        # yields zero objects.
        for _c, _bv in srcs_val.branches:
            if _c != srcs_val.default_key:
                continue
            dlits = [d for d in _src_elems(_bv)[0] if is_src(d)]
            src_objs.extend(dlits)
            for lbl in _src_label_elems(_bv):
                fkind, _fn, fnode = _label_kind(lbl, ctx.resolver)
                if fkind != "filegroup":
                    continue
                fgfiles, _n = _filegroup_sources(
                    lbl, fnode, ctx, pkgdir=os.path.dirname(ctx.build_path))
                src_objs.extend(f for f in fgfiles if is_src(f) and
                                f not in src_objs)
        if not src_objs:
            mod.empty_reason = ("srcs resolved from a select() branch with no "
                                "sources (default=%r)" % srcs_val.default_key)
    elif isinstance(srcs_val, VError):
        mod.parts.append(_frag(
            "todo", C_LOW, srcs_val.origin,
            "# TODO(manual): srcs could not be resolved: %s"
            % srcs_val.reason))
        mod.findings.append(Finding("srcs", "unrecoverable", srcs_val.reason,
                                    srcs_val.origin))
        mod.empty_reason = "srcs unresolved: %s" % srcs_val.reason
    else:
        # plain list (possibly with labels glued in)
        _collect_src_objs(srcs_val, mod, src_objs, ctx)

    if srcs_val is not None and not isinstance(srcs_val, (VGlob, VSelect,
                                                          VError, VList,
                                                          VTuple, VNone)):
        mod.parts.append(_frag(
            "todo", C_LOW, line,
            "# TODO(manual): srcs has an unsupported shape (%s)"
            % type(srcs_val).__name__))

    mod.unconditional = _dedup(src_objs)

    # conditional_srcs ---------------------------------------------------
    cs = kw("conditional_srcs")
    if cs is not None:
        cs_val = r.value_of(cs, "conditional_srcs")
        if isinstance(cs_val, VDict):
            for kk, vv in cs_val.pairs:
                cfg = kk.to_py() if hasattr(kk, "to_py") else str(kk)
                branches = _cond_branch_objs(vv)
                if branches is None:
                    mod.parts.append(_frag(
                        "todo", C_LOW, vv.origin if hasattr(vv, "origin") else line,
                        "# TODO(manual): conditional_srcs[%r] is not a literal "
                        "list" % cfg))
                    mod.findings.append(Finding(
                        "conditional_srcs[%s]" % cfg, "unrecoverable",
                        "conditional source list is not statically known",
                        getattr(vv, "origin", line)))
                    continue
                on_true, on_false = branches
                if on_true or on_false:
                    # A Kbuild conditional line must use a `$(CONFIG_FOO)`
                    # spelling; `$(FOO)` expands to empty and silently drops
                    # every source under it.  Normalise the key and record a
                    # note whenever we had to rewrite or invent the prefix.
                    kbuild_cfg = cfg
                    if not cfg.startswith("CONFIG_"):
                        kbuild_cfg = _config_from_label(cfg)
                        mod.parts.append(_frag(
                            "todo", C_MEDIUM, line,
                            "# TODO(manual): conditional_srcs key %r is not a "
                            "CONFIG_* symbol;\n"
                            "#   emitted as $(%s) -- map it to the real Kconfig "
                            "symbol." % (cfg, kbuild_cfg)))
                        mod.findings.append(Finding(
                            "conditional_srcs[%s]" % cfg, "lossy",
                            "config key %r lacks the CONFIG_ prefix; emitted as "
                            "$(%s)" % (cfg, kbuild_cfg), line, C_MEDIUM))
                    # `on_false is None` -> plain-list entry (ifneq shorthand);
                    # a list (possibly empty) -> an explicit True/False pair,
                    # emitted as a real ifeq/else under the switch.
                    mod.conditional.append(
                        (kbuild_cfg, on_true,
                         None if on_false is None else on_false))
        else:
            mod.parts.append(_frag(
                "todo", C_LOW, line,
                "# TODO(manual): conditional_srcs is not a dict-shaped literal"))
            mod.findings.append(Finding("conditional_srcs", "unrecoverable",
                                        "conditional_srcs not statically known",
                                        line))

    # local_defines ------------------------------------------------------
    ld = kw("local_defines")
    if ld is not None:
        val = r.value_of(ld, "local_defines")
        if isinstance(val, VList):
            defs = []
            debug_defs = []      # DYNAMIC_DEBUG_MODULE-style compile toggles
            for e in val.elems:
                if not isinstance(e, VStr):
                    continue
                raw = e.s[2:] if e.s.startswith("-D") else e.s
                if _is_debug_define(raw):
                    debug_defs.append(raw)
                else:
                    defs.append("-D" + raw)
            if defs:
                mod.flags.append((val.conf, val.origin, " ".join(defs)))
            if debug_defs:
                # A compile-flag toggle, not a source gate: keep it as a named
                # switch so a reviewer can turn the debug instrumentation off
                # without touching the module's objects or its CONFIG_ gates.
                mod.parts.append(_frag(
                    "switch", C_HIGH, getattr(val, "origin", line),
                    _debug_define_block(mod, debug_defs)))
        elif isinstance(val, VSelect):
            _emit_select_flags(mod, val, "local_defines", "-D")
        elif isinstance(val, (VGlob, VError)):
            mod.parts.append(_frag(
                "todo", C_LOW, getattr(val, "origin", line),
                "# TODO(manual): local_defines value is not a literal list"))
            mod.findings.append(Finding("local_defines", "unrecoverable",
                                        "non-literal local_defines",
                                        getattr(val, "origin", line)))

    # copts --------------------------------------------------------------
    cp = kw("copts")
    if cp is not None:
        val = r.value_of(cp, "copts")
        _emit_copts(mod, val)

    # includes / linux_includes ------------------------------------------
    _include_lines(ctx, mod, r.value_of(kw("includes"), "includes"), "includes")
    _include_lines(ctx, mod, r.value_of(kw("linux_includes"), "linux_includes"),
                   "linux_includes")

    # hdrs ---------------------------------------------------------------
    hdrs = kw("hdrs")
    if hdrs is not None:
        _emit_hdrs(ctx, mod, r.value_of(hdrs, "hdrs"))

    # config -------------------------------------------------------------
    kc = kw("kconfig")
    if kc is not None and kc.kind == "str":
        mod.kconfig = kc.value
    dc = kw("defconfig")
    if dc is not None:
        if dc.kind == "str":
            mod.defconfig = dc.value
        elif dc.kind in ("select", "call"):
            mod.findings.append(Finding(
                "defconfig", "unrecoverable",
                "defconfig is selected at build time (select()); Kbuild has a "
                "single per-directory defconfig -- both files must be kept "
                "manually", dc.line))

    kb = kw("kernel_build")
    if kb is not None and kb.kind == "str":
        mod.kernel_build = kb.value
        mod.parts.append(_frag("comment", C_HIGH, kb.line,
                               "# Kernel: %s" % kb.value))

    # deps ---------------------------------------------------------------
    deps = kw("deps")
    if deps is not None:
        _emit_deps(ctx, mod, r.value_of(deps, "deps"), "deps")
    if "makefile" in node.kwargs:
        mod.findings.append(Finding(
            "makefile", "note",
            "DDK `makefile` attribute present: the Bazel build reuses a "
            "makefile driver; the generated Kbuild is the closest projection",
            node.kwargs["makefile"].line, C_MEDIUM))

    # name / rule comments ------------------------------------------------
    mod.parts.insert(0, _frag("comment", C_HIGH, line,
                              "# %s: %s" % (rule_name, mod.name)))
    if not mod.unconditional and not mod.conditional and not mod.empty_reason:
        mod.empty_reason = "the DDK target resolves to zero source files"
    return mod


def _collect_src_objs(val, mod, src_objs, ctx):
    """Walk a srcs VList: .c -> object; :label -> dep; glob -> note."""
    if not isinstance(val, (VList, VTuple)):
        if isinstance(val, VStr):
            _add_src_str(val.s, mod, src_objs, ctx, val.origin)
        return
    for e in val.elems:
        if isinstance(e, VStr):
            _add_src_str(e.s, mod, src_objs, ctx, e.origin)
        elif isinstance(e, VFileLabel):
            _add_src_str(e.label, mod, src_objs, ctx, e.origin)
        elif isinstance(e, VGlob):
            pats = ", ".join(e.patterns)
            if e.is_header_only:
                mod.findings.append(Finding(
                    "srcs", "note",
                    "header-only glob(%s) in srcs: no object line needed"
                    % pats, e.origin, C_MEDIUM))
                continue
            mod.parts.append(_frag(
                "todo", C_LOW, e.origin,
                "# TODO(manual): srcs contains glob([%s]) -- list the .c files"
                % pats))
            mod.findings.append(Finding(
                "srcs", "unrecoverable",
                "glob([%s]) inside srcs: literal .c list not recoverable"
                % pats, e.origin))
        elif isinstance(e, VSelect):
            dval = e.default_value()
            mod.parts.append(_frag(
                "todo", C_LOW, e.origin,
                "# TODO(manual): select({...}) inside srcs: %r branch emitted; "
                "branches: %s" % (e.default_key, ", ".join(e.branch_names()))))
            mod.findings.append(Finding(
                "srcs", "unrecoverable",
                "select() inside srcs (%s); only %r emitted"
                % (", ".join(e.branch_names()), e.default_key), e.origin))
            if isinstance(dval, VList):
                _collect_src_objs(dval, mod, src_objs, ctx)
        elif isinstance(e, VError):
            mod.parts.append(_frag(
                "todo", C_LOW, e.origin,
                "# TODO(manual): unresolved srcs entry: %s" % e.reason))
            mod.findings.append(Finding("srcs", "unrecoverable", e.reason,
                                        e.origin))
        elif isinstance(e, (VList, VTuple)):
            _collect_src_objs(e, mod, src_objs, ctx)
        elif isinstance(e, VFileLabel):
            _add_src_str(e.label, mod, src_objs, ctx, e.origin)


def _add_src_str(s, mod, src_objs, ctx, origin):
    if is_src(s):
        src_objs.append(s)
        return
    if is_h(s):
        src_objs.append(s)
        return
    if is_label(s):
        kind, fn, target = _label_kind(s, ctx.resolver)
        if kind == "headers":
            dirs = collect_include_dirs(target, ctx.resolver)
            if dirs:
                mod.flags.append((C_HIGH, origin,
                                  " ".join("-I$(src)/%s" % d for d in dirs)))
                mod.findings.append(Finding(
                    "srcs", "note",
                    "srcs entry %r is a headers target; emitted -I flags"
                    % s, origin, C_MEDIUM))
            else:
                mod.parts.append(_frag(
                    "todo", C_MEDIUM, origin,
                    "# TODO(manual): srcs entry %r is a headers label; add the "
                    "matching -I path by hand" % s))
                mod.findings.append(Finding(
                    "srcs", "lossy",
                    "srcs entry %r is a cross-package headers label; its -I "
                    "path is only known by reading that BUILD file" % s,
                    origin, C_MEDIUM))
        elif kind == "module":
            mod.deps.append((s, "module"))
        elif kind == "object":
            mod.deps.append((s, "object"))
        elif kind == "filegroup":
            # A filegroup in `srcs` contributes its files to this module
            # (Bazel DefaultInfo.files = transitive(srcs)).  Inline them so the
            # objects land in <mod>-y rather than silently vanishing -- this is
            # the `srcs = select({...: ["//pkg:tgt"]})` -> filegroup chain.
            files, _note = _filegroup_sources(
                s, target, ctx, pkgdir=os.path.dirname(ctx.build_path))
            lits = [f for f in files if is_src(f) or is_h(f)]
            if lits:
                src_objs.extend(lits)
                mod.findings.append(Finding(
                    "srcs", "note",
                    "srcs entry %r is a filegroup; inlined %d source(s)"
                    % (s, len(lits)), origin, C_MEDIUM))
            else:
                mod.parts.append(_frag(
                    "todo", C_MEDIUM, origin,
                    "# TODO(manual): srcs entry %r is a filegroup with no "
                    "statically known sources" % s))
                mod.findings.append(Finding(
                    "srcs", "lossy",
                    "srcs entry %r is a filegroup whose sources could not be "
                    "read" % s, origin, C_MEDIUM))
        else:
            mod.findings.append(Finding(
                "srcs", "warn",
                "srcs entry %r is a Bazel label, not a source file (no fake "
                ".c emitted)" % s, origin, C_MEDIUM))
        return
    mod.findings.append(Finding(
        "srcs", "warn", "srcs entry %r is neither a source nor a label" % s,
        origin, C_MEDIUM))


def _cond_branch_objs(val):
    """conditional_srcs value -> (true_objs, false_objs).

    `false_objs` is None when the entry is a plain list (no False branch); an
    explicit `{True: [...], False: [...]}` yields both lists so the emitter can
    produce a real ifeq/else.  A `{True: [...]}` with an empty/absent False
    branch yields `[]` (the shorthand `ifneq` form).
    """
    if isinstance(val, VList):
        objs = [e.s for e in val.elems if isinstance(e, VStr) and is_src(e.s)]
        return objs, None
    if isinstance(val, VDict):
        on_true = []
        on_false = []
        has_false = False
        for kk, vv in val.pairs:
            key = kk.to_py() if hasattr(kk, "to_py") else None
            if key is True and isinstance(vv, VList):
                on_true = [e.s for e in vv.elems
                           if isinstance(e, VStr) and is_src(e.s)]
            elif key is False:
                has_false = True
                if isinstance(vv, VList):
                    on_false = [e.s for e in vv.elems
                                if isinstance(e, VStr) and is_src(e.s)]
        return on_true, (on_false if has_false else None)
    if isinstance(val, VSelect):
        tv, _ = _cond_branch_objs(val.default_value())
        return tv, []
    return None


def _emit_select_flags(mod, val, attr, prefix):
    """`attr = select({":cfg": [flags], "//conditions:default": []})` -> Kbuild.

    Kbuild's `ccflags-$(CONFIG_X) += ...` is the natural target: it is exactly
    the conditional-flag form the original Makefiles use.  The config_setting
    label supplies the symbol spelling (a placeholder the reviewer maps), and
    the `//conditions:default` branch is emitted unconditionally, matching
    Bazel's semantics for the unselected case.

    `prefix` forces a -D on each entry (for local_defines); None passes copts
    through as written.
    """
    def _flags_of(branch_val):
        if not isinstance(branch_val, VList):
            return []
        out = []
        for e in branch_val.elems:
            if isinstance(e, VStr):
                out.append(e.s if (prefix is None or e.s.startswith("-"))
                           else prefix + e.s)
        return out

    emitted = []
    for cond, bval in val.branches:
        if cond == val.default_key:
            continue
        flags = _flags_of(bval)
        if flags:
            emitted.append((cond, flags))

    # default branch: unconditional
    default_flags = _flags_of(val.default_value())
    if default_flags:
        mod.flags.append((val.conf, val.origin, " ".join(default_flags)))

    if not emitted:
        if not default_flags:
            mod.findings.append(Finding(
                attr, "note",
                "%s=select(): no branch carries flags; nothing emitted"
                % attr, val.origin, C_MEDIUM))
        return

    lines = ["# %s = select({...}) -> conditional flags; map each placeholder "
             "CONFIG_" % attr,
             "# below to the real Kconfig symbol %r selects."
             % val.default_key]
    for cond, flags in emitted:
        cfg = _config_from_label(cond)
        lines.append("ccflags-$(%s) += %s" % (cfg, " ".join(flags)))
        lines.append("#   ^ Bazel config_setting %s" % cond)
    # A multi-line, already-prefixed block: emit as a raw segment, NOT through
    # mod.flags (which would prepend `ccflags-y +=` to every line).
    mod.parts.append(_frag("raw", C_MEDIUM, val.origin, "\n".join(lines)))
    mod.findings.append(Finding(
        attr, "lossy",
        "%s=select(): %d conditional branch(es) emitted as "
        "ccflags-$(CONFIG_*); the config_setting -> CONFIG_ mapping is a "
        "placeholder to verify" % (attr, len(emitted)), val.origin, C_MEDIUM))


def _emit_copts(mod, val):
    """copts -> ccflags-y fragments, with Bazel make-variable translation."""
    items = []
    if isinstance(val, VList):
        items = val.elems
        conf = val.conf
        origin = val.origin
    elif isinstance(val, VError):
        mod.findings.append(Finding("copts", "unrecoverable", val.reason,
                                    val.origin))
        mod.parts.append(_frag(
            "todo", C_LOW, val.origin,
            "# TODO(manual): copts could not be resolved: %s" % val.reason))
        return
    elif isinstance(val, VSelect):
        # A select() over config_settings maps onto Kbuild's
        # `ccflags-$(CONFIG_X) += ...` conditional-flag form (the exact idiom
        # in the akita corpus, e.g. qcacld-3.0/Kbuild:3790).  Emit every
        # non-default branch that way, plus the default branch unconditionally.
        _emit_select_flags(mod, val, "copts", None)
        return
    else:
        return

    pending = []
    conf_acc = conf
    i = 0
    n = len(items)
    while i < n:
        e = items[i]
        if not isinstance(e, VStr):
            if isinstance(e, VError):
                conf_acc = max(conf_acc, C_LOW)
                mod.findings.append(Finding("copts", "unrecoverable", e.reason,
                                            e.origin))
            i += 1
            continue
        s = e.s
        if s == "-include":
            # -include, <next>  ->  -include <translated>
            if i + 1 < n and isinstance(items[i + 1], VStr):
                nxt = items[i + 1].s
                pending.append("-include")
                pending.append(_translate_location(nxt, mod, e.origin))
                i += 2
                continue
            pending.append("-include")
            i += 1
            continue
        if s.startswith("-include") and len(s) > len("-include"):
            rest = s[len("-include"):].strip()
            pending.append("-include " + _translate_location(rest, mod, e.origin))
            i += 1
            continue
        translated = _translate_copt(s, mod, e.origin)
        if translated is not None:
            pending.append(translated)
        i += 1

    if pending:
        text = " ".join(p for p in pending if p)
        text = _join_include_pair(text)
        mod.flags.append((conf_acc, origin, text))


def _join_include_pair(text):
    """`-include X` must stay two tokens; keep it, it is valid Kbuild."""
    return text


def _translate_location(s, mod, origin):
    """$(location :x) / $(execpath x.h) / $$(ROOT_DIR) -> Kbuild spelling."""
    out = s
    if "$(location" in out or "$(execpath" in out or "$(rootpath" in out:
        def _sub(match):
            macro, inner = match.group(1), match.group(2).strip()
            # A bare filename (no ':' and no '//') is a same-package header:
            # the Kbuild spelling is a plain relative path.
            if not inner.startswith(":") and not inner.startswith("//") \
                    and not inner.startswith("@"):
                if inner.endswith((".h", ".hpp", ".hxx")):
                    return inner
                mod.findings.append(Finding(
                    "copts", "lossy",
                    "$(%s %s) translated to the relative path %r; if it is "
                    "generated by a Bazel rule, generate it before building "
                    "with Kbuild" % (macro, inner, inner), origin, C_MEDIUM))
                return inner
            if inner.startswith(":"):
                hdr = inner[1:]
                mod.findings.append(Finding(
                    "copts", "warn",
                    "$(%s %s) translated to -include %s; if %s is generated "
                    "by a Bazel rule, generate it manually before building "
                    "with Kbuild" % (macro, inner, hdr, hdr), origin, C_LOW))
                return hdr
            mod.findings.append(Finding(
                "copts", "unrecoverable",
                "$(%s %s) points at another package; resolve manually"
                % (macro, inner), origin))
            return inner
        out = re.sub(r"\$\(+(location|execpath|rootpath)\s+([^)]*)\)", _sub, out)
    if "ROOT_DIR" in out or "$(execpath" in out:
        out = out.replace("$$(", "$(")
    return out


def _translate_copt(s, mod, origin):
    s = s.strip()
    if not s:
        return None
    if s.startswith("-D") or s.startswith("-U") or s.startswith("-I") or \
            s.startswith("-W") or s.startswith("-f") or s.startswith("-O") or \
            s.startswith("-g") or s.startswith("-m") or s.startswith("-std="):
        if "$$(" in s or "$(ROOT_DIR)" in s or "$(location" in s:
            fixed = s.replace("$$(", "$(")
            if "$(ROOT_DIR)" in fixed:
                mod.findings.append(Finding(
                    "copts", "lossy",
                    "$$(ROOT_DIR) is a Bazel make-variable; translated "
                    "verbatim to $(ROOT_DIR) for Kbuild", origin, C_MEDIUM))
            return fixed
        return s
    if "$$(" in s or "$(" in s:
        fixed = s.replace("$$(", "$(")
        mod.findings.append(Finding(
            "copts", "lossy",
            "Bazel make-variable in copts %r translated verbatim" % s,
            origin, C_MEDIUM))
        return fixed
    return s


def _emit_hdrs(ctx, mod, val):
    """hdrs = [":ddk_headers_target", ...] -> -I flags + notes."""
    if isinstance(val, VError):
        mod.findings.append(Finding("hdrs", "unrecoverable", val.reason,
                                    val.origin))
        return
    elems = val.elems if isinstance(val, (VList, VTuple)) else [val]
    for e in elems:
        if isinstance(e, VFileLabel) or (isinstance(e, VStr) and is_label(e.s)):
            label = e.label if isinstance(e, VFileLabel) else e.s
            if not label.startswith(":"):
                mod.findings.append(Finding(
                    "hdrs", "note",
                    "hdrs %r is cross-package: its includes are only known by "
                    "reading that BUILD file" % label,
                    getattr(e, "origin", 0), C_MEDIUM))
                continue
            fn, target = ctx.lookup(label[1:])
            dirs = collect_include_dirs(target, ctx.resolver)
            if dirs:
                mod.flags.append((C_HIGH, getattr(e, "origin", 0),
                                  " ".join("-I$(src)/%s" % d for d in dirs)))
                mod.findings.append(Finding(
                    "hdrs", "note",
                    "hdrs %r: resolved the ddk_headers target and emitted "
                    "-I$(src)/%s" % (label, ", ".join(dirs)),
                    getattr(e, "origin", 0), C_MEDIUM))
            else:
                # Distinguish an actually-empty target from one whose includes
                # we failed to read; the latter must not be silently dropped.
                if _includes_is_env_dependent(target, ctx.resolver):
                    mod.parts.append(_frag(
                        "todo", C_MEDIUM, getattr(e, "origin", 0),
                        "# TODO(manual): hdrs %r declares includes via "
                        "select()/unresolved expression; add its -I$(src)/... "
                        "paths by hand" % label))
                    mod.findings.append(Finding(
                        "hdrs", "unrecoverable",
                        "hdrs %r: includes could not be fully resolved "
                        "(select() or unresolved expression); -I paths need "
                        "manual recovery" % label,
                        getattr(e, "origin", 0)))
                else:
                    mod.findings.append(Finding(
                        "hdrs", "note",
                        "hdrs %r is an exported ddk_headers target with no "
                        "`includes`; downstream modules inherit its headers"
                        % label, getattr(e, "origin", 0), C_MEDIUM))
        elif isinstance(e, VGlob):
            pats = ", ".join(e.patterns)
            mod.findings.append(Finding(
                "hdrs", "note",
                "hdrs glob([%s]): header globs need no Kbuild object line "
                "(-I covers them)" % pats,
                getattr(e, "origin", 0), C_MEDIUM))


def _emit_deps(ctx, mod, val, attr):
    """deps = [...] -> -I flags, EXTRA_SYMBOLS, notes; never fake .c files."""
    if isinstance(val, VError):
        mod.findings.append(Finding(attr, "unrecoverable", val.reason,
                                    val.origin))
        return
    elems = val.elems if isinstance(val, (VList, VTuple)) else [val]
    for e in elems:
        if isinstance(e, VSelect):
            dval = e.default_value()
            mod.parts.append(_frag(
                "todo", C_LOW, e.origin,
                "# TODO(manual): %s = select({...}): %r branch emitted only; "
                "branches: %s" % (attr, e.default_key,
                                  ", ".join(e.branch_names()))))
            mod.findings.append(Finding(
                attr, "unrecoverable",
                "%s=select(): only %r branch emitted (branches: %s)"
                % (attr, e.default_key, ", ".join(e.branch_names())), e.origin))
            if dval is not None:
                _emit_deps(ctx, mod, dval, attr)
            continue
        if isinstance(e, VGlob):
            mod.findings.append(Finding(
                attr, "note", "%s contains glob(): ignored for Kbuild" % attr,
                e.origin, C_MEDIUM))
            continue
        if isinstance(e, VError):
            mod.findings.append(Finding(attr, "unrecoverable", e.reason,
                                        e.origin))
            continue
        label = None
        if isinstance(e, VFileLabel):
            label = e.label
        elif isinstance(e, VStr) and is_label(e.s):
            label = e.s
        if label is None:
            continue
        _emit_one_dep(ctx, mod, label, attr, getattr(e, "origin", 0))


def _src_label_elems(val):
    """Label strings inside a srcs value (list / tuple / nested select)."""
    out = []
    if isinstance(val, (VList, VTuple)):
        for e in val.elems:
            if isinstance(e, VStr) and is_label(e.s):
                out.append(e.s)
            elif isinstance(e, VFileLabel):
                out.append(e.label)
            elif isinstance(e, (VList, VTuple, VSelect)):
                out.extend(_src_label_elems(e))
    elif isinstance(val, VSelect):
        if val.base is not None:
            out.extend(_src_label_elems(val.base))
        for _c, bv in val.branches:
            out.extend(_src_label_elems(bv))
    elif isinstance(val, VStr) and is_label(val.s):
        out.append(val.s)
    elif isinstance(val, VFileLabel):
        out.append(val.label)
    return out


def _filegroup_sources(label, node, ctx, visited=None, pkgdir=None,
                       resolved=False):
    """Sources a filegroup contributes: (literal_files, note).

    Follows `srcs` through nested `:other` / `//pkg:other` filegroups and
    expands globs against the filesystem when the pattern is rooted in a
    directory we can see.  Cross-package filegroups (`//pkg:tgt`) are read from
    that package's BUILD.bazel.

    `resolved=True` means `node` has ALREADY been looked up in the package
    `pkgdir` names, so the cross-package re-resolution must be skipped (doing it
    again would re-enter this branch with the same key and return nothing).
    """
    visited = visited if visited is not None else set()
    key = (pkgdir or "", label)
    if key in visited:
        return [], ""
    visited.add(key)
    if node is None:
        return [], ""

    out = []
    note = ""

    # Cross-package: re-bind to that package's BUILD and its own resolver.
    if label.startswith("//") and not resolved:
        root = getattr(ctx.opts, "repo_root", "") or ""
        xdir, target = _label_to_pkg_dir(label, root)
        if xdir is None:
            return [], ""
        xnode = None
        build = os.path.join(xdir, "BUILD.bazel")
        xpf = _parse_text_cached(build)
        if xpf is not None:
            for st in xpf.calls:
                n = st.node
                fn = n.value.value if n.value is not None and \
                    n.value.kind == "name" else ""
                nm = n.kwargs.get("name")
                if nm is not None and nm.kind == "str" and \
                        nm.value == target and _rule_kind(fn) == "filegroup":
                    xnode = n
                    break
        if xnode is None:
            return [], ""
        return _filegroup_sources(label, xnode, ctx, visited, pkgdir=xdir,
                                  resolved=True)

    srcs = node.kwargs.get("srcs")
    base = pkgdir or ""
    # srcs may be a list, or a `list + list` / `list + glob(...)` concat.
    for piece in _flatten_concat(srcs):
        if piece.kind == "str":
            s = piece.value
            if is_label(s):
                if s.startswith(":"):
                    fn2, n2 = ctx.resolver.resolve_file_scoped(s[1:])
                    if n2 is not None and _rule_kind(fn2) == "filegroup":
                        sub, _ = _filegroup_sources(s, n2, ctx, visited, base)
                        out.extend(sub)
                continue
            out.append(s)
        elif piece.kind == "call":
            callee = piece.value
            cname = callee.value if callee is not None and \
                callee.kind == "name" else ""
            if cname in ("glob", "native.glob"):
                pats = _glob_patterns(piece)
                out.extend(_expand_globs(base, pats))
    return out, note


def _flatten_concat(node):
    """Flatten `a + b + ...` (SNode binop '+') into a list of leaf nodes."""
    if node is None:
        return []
    if node.kind == "binop" and node.value == "+":
        return _flatten_concat(node.args[0]) + _flatten_concat(node.args[1])
    if node.kind in ("list", "tuple"):
        out = []
        for e in node.args:
            out.extend(_flatten_concat(e))
        return out
    return [node]


def _expand_globs(base, patterns):
    """Expand glob patterns against the filesystem under `base`.

    Returns literal paths relative to `base` (matching Bazel's package-relative
    spelling).  Recursive `**` is honoured; a pattern in an unreadable dir
    yields nothing rather than raising.
    """
    out = []
    if not base or not os.path.isdir(base):
        return out
    for pat in patterns:
        if "**" in pat:
            prefix = pat.split("**", 1)[0].rstrip("/")
            root = os.path.join(base, prefix) if prefix else base
            tail = pat.split("**", 1)[1].lstrip("/")
            if not os.path.isdir(root):
                continue
            for dirpath, _dirs, files in os.walk(root):
                for fn in files:
                    if fnmatch.fnmatch(fn, tail) or fnmatch.fnmatch(
                            os.path.join(dirpath, fn)[len(base) + 1:],
                            tail.lstrip("/")):
                        rel = os.path.join(dirpath, fn)[len(base) + 1:]
                        if rel not in out:
                            out.append(rel)
        else:
            head = os.path.dirname(pat)
            d = os.path.join(base, head) if head else base
            if not os.path.isdir(d):
                continue
            for fn in sorted(os.listdir(d)):
                full = os.path.join(d, fn)
                if os.path.isfile(full) and fnmatch.fnmatch(fn, os.path.basename(pat)):
                    rel = os.path.join(head, fn) if head else fn
                    if rel not in out:
                        out.append(rel)
    return out


def _wrap_report(line, limit=100, indent="           "):
    """Soft-wrap a long report line so a terminal/diff stays readable.

    Continuation lines are indented under the finding text.  The limit is 100
    (wider than the 80 used for generated Kbuild) because these are diagnostics
    for a human, not kernel source.
    """
    if len(line) <= limit:
        return [line]
    out = []
    cur = ""
    for word in line.split():
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            out.append(cur)
            cur = indent + word
    if cur:
        out.append(cur)
    return out


def _wrap_comment(line, limit=80, indent="#     "):
    """Wrap a long `#` comment line at the kernel's 80-column limit.

    Continuation lines are prefixed with `#` and indented under the text, so
    the block stays a valid comment and each line is greppable.  A single
    unsplittable word is left long rather than broken.
    """
    if len(line) <= limit:
        return [line]
    out = []
    cur = ""
    for word in line.split():
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            out.append(cur)
            cur = indent + word
    if cur:
        out.append(cur)
    # Continuation lines must be comments, not bare text.
    for i in range(1, len(out)):
        if not out[i].lstrip().startswith("#"):
            out[i] = "# " + out[i].lstrip()
    return out


def _append_comment_list(lines, prefix, items, limit=80, open_with="",
                         close_with=""):
    """Append a `# ...` comment listing `items`, wrapped at `limit`.

    Comment lists are free text (not a Kbuild assignment), so no backslash is
    used -- each continued line is its own `# ` comment, which is the kernel
    convention for long comment blocks and keeps every line greppable.
    """
    body = ", ".join(items)
    head = prefix + open_with
    whole = head + body + close_with
    if len(whole) <= limit:
        lines.append(whole)
        return
    pad = " " * min(len(head), 14)
    cur = head
    for i, item in enumerate(items):
        last = (i == len(items) - 1)
        piece = item + ("" if last else ",")
        if cur.strip() != "#" and len(cur) + len(piece) + 1 > limit:
            lines.append(cur)
            cur = "#" + pad + piece
        else:
            cur += piece
        if not last:
            cur += " "
    if cur.strip() not in ("#",):
        lines.append(cur + close_with)


def _ccflags_lines(text, limit=80):
    """Wrap a joined ccflags fragment into kernel-style line(s).

    Follows the kernel's 80-column limit (Documentation/process/coding-style.rst)
    and the reference Kbuild corpus: a trailing `\\` continues the assignment
    and continuation lines are indented.  A flag set that already fits is left
    on one line.
    """
    toks = text.replace("\\", " ").split()
    return _wrap_assign("ccflags-y += ", toks, limit=limit)


def _library_objects(rule_node):
    """Objects of a local ddk_library target (may be None)."""
    if rule_node is None:
        return []
    srcs = rule_node.kwargs.get("srcs")
    lits = _str_list(srcs)
    return [o for o in _dedup([_obj_name(s) for s in lits if is_src(s)])]


# Header bundles that are provided by the kernel_build / common kernel rather
# than by a module in this tree.  They contribute no package-local -I and are
# therefore not a conversion loss.
BASE_HEADER_LABELS = (
    "//common:all_headers_aarch64",
    "//common:all_headers_x86_64",
    "//common:all_headers",
    "//build/kernel/kleaf:user_ddk_unsafe_headers",
)


def _headers_target_is_bundle(rule_node, ctx):
    """True if a ddk_headers declares only headers and no include dirs.

    Such a target (e.g. soc/gs/.../zram:zram_headers with hdrs=[...] and no
    `includes`) provides same-directory headers that Kbuild already finds via
    $(src); there is no -I to emit and nothing is lost.
    """
    if rule_node is None:
        return False
    for attr in ("includes", "linux_includes"):
        node = rule_node.kwargs.get(attr)
        if node is not None:
            return False
    for attr in ("hdrs", "textual_hdrs", "srcs"):
        if rule_node.kwargs.get(attr) is not None:
            return True
    return False


def _kernel_root_visible(ctx):
    """True if the workspace root (kernel checkout) is present on disk.

    `//common:*` is defined by the kernel root's own BUILD.bazel, so its
    presence means the ACK side of the tree was found and `//common`,
    `//private` labels can be resolved.
    """
    root = getattr(ctx.opts, "repo_root", "") or ""
    if not root:
        return False
    return os.path.isfile(os.path.join(root, "BUILD.bazel")) and \
        os.path.isdir(os.path.join(root, "private"))


def _emit_one_dep(ctx, mod, label, attr, origin):
    # Record every dependency label on the IR so later stages (the Makefile
    # shim's soc/gs Makefile.include detection) can see them; the individual
    # kinds below decide what is *emitted*.
    if label not in [l for l, _ in mod.deps]:
        mod.deps.append((label, "dep"))
    if label in BASE_HEADER_LABELS:
        # The ACK kernel's own header bundle.  It provides no package-local -I
        # (Kbuild reaches those headers through $(srctree) already), so nothing
        # is emitted -- but report whether we could actually see the kernel
        # root, so an absent/partial checkout is distinguishable from "nothing
        # to do".
        seen = _kernel_root_visible(ctx)
        mod.findings.append(Finding(
            attr, "note",
            "%s %r is the kernel's own header bundle%s; no -I needed"
            % (attr, label,
               " (found the kernel root)" if seen
               else " (kernel root not found; set --repo-root)"),
            origin, C_HIGH))
        return
    kind, fn, target = _label_kind(label, ctx.resolver)
    if kind == "headers":
        if label.startswith("//"):
            # Cross-package: resolve against THAT package's BUILD and emit
            # ROOT_DIR-relative includes.
            xdirs, xpkg = resolve_cross_package_headers(label, ctx)
            if xdirs:
                # xpkg is the package dir relative to the workspace root; it is
                # "" for `//common:...` (the ACK kernel's workspace root).
                flags = " ".join(
                    "-I$(ROOT_DIR)/%s" % (os.path.join(xpkg, d).lstrip("/")
                                          if xpkg else d)
                    for d in xdirs)
                mod.flags.append((C_MEDIUM, origin, flags))
                mod.findings.append(Finding(
                    attr, "note",
                    "%s %r resolved from %s/BUILD.bazel: %s"
                    % (attr, label, (xpkg or "<workspace root>"), flags),
                    origin, C_MEDIUM))
                return
        dirs = collect_include_dirs(target, ctx.resolver)
        if dirs:
            mod.flags.append((C_HIGH, origin,
                              " ".join("-I$(src)/%s" % d for d in dirs)))
            mod.findings.append(Finding(
                attr, "note",
                "%s %r -> ddk_headers includes: -I$(src)/%s"
                % (attr, label, ", ".join(dirs)), origin, C_MEDIUM))
            return
        # No include dirs anywhere in the chain.  Either the target declares
        # only `hdrs` (a same-directory header bundle already covered by
        # $(src) -- nothing to emit), or it truly could not be read.  The two
        # are different: only the latter is a conversion loss.
        if _headers_target_is_bundle(target, ctx):
            mod.findings.append(Finding(
                attr, "note",
                "%s %r is a same-directory header bundle (hdrs only, no "
                "includes); nothing to emit" % (attr, label), origin, C_HIGH))
            return
        mod.parts.append(_frag(
            "todo", C_MEDIUM, origin,
            "# TODO(manual): %s %r is a headers label; add its -I path by hand"
            % (attr, label)))
        mod.findings.append(Finding(
            attr, "lossy",
            "%s %r is a headers label; its include path could not be read"
            % (attr, label), origin, C_MEDIUM))
        return
    if kind == "filegroup":
        # A filegroup named in `srcs` contributes its files to this module
        # (Bazel DefaultInfo.files = transitive(srcs)).  Inline the literal
        # sources so the objects land in <mod>-y instead of vanishing -- this
        # is the `srcs = select({...: ["//pkg:touch_bus_negotiator"]})` ->
        # filegroup(srcs = [glob(...), "x.c"]) chain the DDK uses.
        files, note = _filegroup_sources(
            label, target, ctx, pkgdir=os.path.dirname(ctx.build_path))
        lits = [f for f in files if is_src(f) or is_h(f)]
        if lits:
            mod.unconditional = _dedup(mod.unconditional + lits)
            mod.findings.append(Finding(
                attr, "note",
                "%s %r is a filegroup%s; inlined %d source(s) into <%s>-y"
                % (attr, label, note, len(lits), mod.obj), origin, C_MEDIUM))
            return
        mod.parts.append(_frag(
            "todo", C_MEDIUM, origin,
            "# TODO(manual): %s %r is a filegroup with no statically known "
            "sources; add them to <%s>-y by hand"
            % (attr, label, mod.obj)))
        mod.findings.append(Finding(
            attr, "lossy",
            "%s %r is a filegroup whose sources could not be read"
            % (attr, label), origin, C_MEDIUM))
        return
    if kind == "library":
        objs = _library_objects(target)
        if objs:
            # DDK injects the library's objects into the dependent module's
            # link group; do the same for the -y list.
            mod.unconditional = _dedup(mod.unconditional + objs)
            mod.findings.append(Finding(
                attr, "note",
                "%s %r is a ddk_library: its objects (%s) link into this "
                "module and are appended to its -y list"
                % (attr, label, " ".join(objs)), origin, C_MEDIUM))
        else:
            mod.findings.append(Finding(
                attr, "lossy",
                "%s %r is a ddk_library with no statically-known objects; "
                "inline them into <mod>-y" % (attr, label), origin, C_MEDIUM))
        return
    if kind == "object":
        mod.findings.append(Finding(
            attr, "note",
            "%s %r is a ddk_prebuilt_object: link it via "
            "<mod>-y += <name>.o (provide the .o manually)" % (attr, label),
            origin, C_MEDIUM))
        return
    if kind == "module":
        key = label_to_module_syms(label, ctx.opts.repo_pkg_root)
        if key is not None:
            mod.extras.append(key)
            mod.findings.append(Finding(
                attr, "note",
                "%s %r is a module dependency: EXTRA_SYMBOLS += "
                "$(call module_syms,%s)" % (attr, label, key), origin,
                C_MEDIUM))
        return
    mod.parts.append(_frag(
        "todo", C_MEDIUM, origin,
        "# TODO(manual): %s %r is a cross-package dependency; resolve the "
        "EXTRA_SYMBOLS / -I path by hand" % (attr, label)))
    mod.findings.append(Finding(
        attr, "lossy",
        "%s %r is a cross-package dependency; resolve manually" % (attr, label),
        origin, C_MEDIUM))


# -- rendering ---------------------------------------------------------------

def render_module(mod, ctx):
    """Render one module's Kbuild fragments into Lines."""
    parts = []
    for frag in mod.parts:
        if isinstance(frag, Line):
            parts.append(frag)
            continue
        kind, conf, origin, text = frag
        if text is None:
            continue
        parts.append((kind, conf, origin, text))

    # ccflags first (grouped across the module)
    flag_groups = []
    for conf, origin, text in mod.flags:
        if not text:
            continue
        done = False
        for g in flag_groups:
            if g[2] == text:
                g[0] = max(g[0], conf)
                done = True
                break
        if not done:
            flag_groups.append([conf, origin, text])
    for conf, origin, text in flag_groups:
        for ln in _ccflags_lines(text):
            parts.append(("ccflags", conf, origin, ln))

    # obj- line.  Across the reference Kbuild corpus the norm is a gated
    # `obj-$(CONFIG_<symbol>) += name.o` (341 vs 17 bare `obj-m`), so try to
    # recover the module's enable symbol.  Never invent one: if no symbol can
    # be found, fall back to `obj-m +=` and record a finding.
    obj_conf = C_HIGH
    sym, sym_origin = _module_enable_symbol(mod, ctx)
    if sym:
        obj_text = "obj-$(%s) += %s.o" % (sym, mod.obj)
        mod.findings.append(Finding(
            "rule", "note",
            "module enable symbol %s recovered from %s; without it the module "
            "would build unconditionally" % (sym, sym_origin), mod.line,
            C_MEDIUM))
    else:
        obj_text = "obj-m += %s.o" % mod.obj
        mod.findings.append(Finding(
            "rule", "lossy",
            "could not recover the module's CONFIG_ enable symbol (the DDK "
            "target does not record it); emitted `obj-m +=` -- set it by hand "
            "if the module must be gated", mod.line, C_MEDIUM))
    parts.append(("obj", obj_conf, 0, obj_text))

    # -y lines
    if mod.unconditional:
        objs = []
        for s in mod.unconditional:
            if is_src(s):
                objs.append(_obj_name(s))
            elif is_h(s):
                objs.append(s)
            elif s.endswith(".o"):
                objs.append(s)      # linked ddk_library / prebuilt object
        grouped = _grouped_srcs(objs, mod)
        if grouped is not None:
            parts.append(("mod-y", _elem_conf(mod, mod.unconditional),
                          mod.line,
                          "\n".join(_wrap_assign("%s-y := " % mod.obj,
                                                 grouped))))

    # Conditional sources: every gate becomes a named, flippable switch so a
    # reviewer can drop one feature's objects without disabling the module.
    optional = []
    for cfg, objs, false_objs in mod.conditional:
        true_objs = [_obj_name(o) for o in objs if is_src(o)]
        fobjs = None
        if false_objs is not None:
            fobjs = [_obj_name(o) for o in false_objs if is_src(o)]
        if not true_objs and not fobjs:
            continue
        optional.append((cfg, true_objs, fobjs))
    if optional:
        parts.append(("cond", C_HIGH, mod.line, _switch_block(mod, optional)))

    # trailing notes
    for f in mod.findings:
        if f.kind in ("unrecoverable",) and f.conf >= C_LOW:
            pass
    mod.parts = parts
    mod.render()
    return mod.lines


def _elem_conf(mod, srcs):
    conf = C_HIGH
    for f in mod.findings:
        if f.path == "srcs" and f.kind in ("unrecoverable", "lossy"):
            conf = max(conf, C_LOW)
        elif f.path == "srcs" and f.kind == "warn":
            conf = max(conf, C_MEDIUM)
    return conf


def _obj_name(src):
    """Turn a source path into a Kbuild object name.

    Kbuild accepts `subdir/file.o` in a -y list, so the directory path is
    preserved (turning `common/core.c` into `common_core.o` would name an
    object that never exists on disk).  Entries that are already object names
    (a linked ddk_library object, a prebuilt .o) are passed through unchanged.
    """
    base = src
    if base.startswith("./"):
        base = base[2:]
    if base.endswith(".o"):
        return base
    for ext in (".c", ".S", ".s"):
        if base.endswith(ext):
            base = base[:-len(ext)]
            break
    # A dotted basename is not a legal Kbuild object token; the directory path
    # is kept (Kbuild supports `dir/file.o`) but the leaf is flattened.
    head, sep, leaf = base.rpartition("/")
    leaf = leaf.replace(".", "_")
    return (head + sep + leaf if sep else leaf) + ".o"


def _dedup(seq):
    seen = set()
    out = []
    for item in seq:
        if item in seen:
            continue
        seen.add(item)
        out.append(item)
    return out


def _wrap_assign(lhs, tokens, limit=80, indent="    "):
    """Emit `lhs tok tok ...` wrapped to the kernel's 80-column limit.

    Style follows Documentation/process/coding-style.rst ("the preferred limit
    on the length of a single line is 80 columns") and the reference Kbuild
    corpus: a trailing `\\` continues the assignment, and continuation lines
    are indented.  Returns a list of lines (one if it already fits).
    """
    text = " ".join(tokens)
    if len(lhs) + len(text) <= limit:
        return ["%s%s" % (lhs, text)]
    if len(tokens) <= 1:
        return ["%s%s" % (lhs, text)]          # unsplittable single token
    out = []
    cur = lhs
    for i, tok in enumerate(tokens):
        last = (i == len(tokens) - 1)
        # Join with a single space: `lhs` already ends in one ("h2omg-y := "),
        # so only add a separator when one is not already present.
        sep = "" if (not cur or cur.endswith(" ")) else " "
        if cur.strip() and len(cur) + len(sep) + len(tok) > limit - 2:
            out.append(cur.rstrip() + " \\")
            cur = indent + tok
        else:
            cur += sep + tok
        if last:
            out.append(cur)
    return out


def _grouped_srcs(objs, mod):
    """Decide the `-y` list for a module.

    Kbuild cannot express `mod-y := mod.o` when mod.o is itself the module
    object (a circular self-reference).  A single source named after the
    module needs no -y line at all, because Kbuild derives it implicitly.
    """
    real = [o for o in objs if o.endswith(".o")]
    if not real:
        return None
    if len(real) == 1 and real[0] == mod.obj + ".o":
        return None
    return objs


# ---------------------------------------------------------------------------
# Stage C3 -- Post-emit validator
# ---------------------------------------------------------------------------

_RE_BAD_OBJ = re.compile(r"^(?:[A-Za-z0-9_-]+)-y\s*:=")
_RE_COND_ASSIGN = re.compile(r"-y\s*\+=")
_TOKEN_LEAKS = ("//", "@", "$(location", "$(execpath", "$$(")


def build_output_valid(mod):
    """Return (ok, [problems]).

    Catches the two verified invalid-Kbuild classes plus label/token leaks:
      * a -y or -$(CONFIG) line containing '//' or '@' (Bazel label leak)
      * a module that resolves to zero objects
      * triple-quote / $(execpath) text leaking into an assignment
    """
    problems = []
    for ln in mod.lines:
        text = ln.text
        stripped = text.lstrip()
        if stripped.startswith("#"):
            continue
        if ln.kind in ("obj", "mod-y", "cond", "ccflags"):
            if "//" in text or "@" in text:
                problems.append("invalid Kbuild line (label leak): %s" % text)
            if "$(location" in text or "$(execpath" in text or "$$(" in text:
                problems.append("unexpanded Bazel macro: %s" % text)
            if '"""' in text or "'''" in text:
                problems.append("unterminated literal leak: %s" % text)
    real_objs = [o for o in mod.unconditional if is_src(o)]
    if not real_objs and not mod.conditional and not mod.is_library:
        problems.append("module resolves to zero objects%s"
                        % (" (%s)" % mod.empty_reason if mod.empty_reason else ""))
    return (not problems), problems


def validate_module(mod):
    ok, problems = build_output_valid(mod)
    if not ok:
        for p in problems:
            mod.parts.append(_frag("warn", C_LOW, mod.line,
                                   "# INVALID-KBUILD(%s): %s" % (mod.name, p)))
        mod.render()
    return ok, problems


# ---------------------------------------------------------------------------
# Assembly: BUILD file -> ModIR list
# ---------------------------------------------------------------------------

def collect_modules(build_path, pf, loader, opts):
    """Return (modules, ctx, file_findings)."""
    r = Resolver(build_path, pf, loader, opts)
    ctx = RuleContext(r, opts, build_path)
    ctx.resolver = r
    modules = []
    file_findings = []

    # First pass: index local targets so deps/hdrs can be resolved.
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        if nm is None or nm.kind != "str":
            continue
        if fn in ("ddk_headers", "ddk_uapi_headers", "filegroup"):
            ctx.headers_targets[nm.value] = (fn, node)
        ctx.other_rules[nm.value] = (fn, node)

    # Non-emitting rules -> comment-only notes.
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        name = nm.value if nm is not None and nm.kind == "str" else "<anon>"
        if fn in ("ddk_module", "ddk_submodule", "ddk_library"):
            continue
        if fn == "kernel_module_group":
            members = _str_list(node.kwargs.get("srcs"))
            # A group can bundle dozens of targets (bms: 38, display.samsung:
            # 13); listing them all produced 900-column report lines.  Name the
            # first few and the count -- the full list is derivable from the
            # BUILD file.
            shown = ", ".join(members[:4])
            more = ("" if len(members) <= 4
                    else ", ... (+%d more)" % (len(members) - 4))
            file_findings.append(Finding(
                "kernel_module_group:%s" % name, "note",
                "kernel_module_group %r bundles %d target(s): %s%s "
                "(each is its own .ko; no Kbuild line of its own)"
                % (name, len(members), shown, more),
                node.line, C_MEDIUM))
        elif fn == "ddk_prebuilt_module":
            src = node.kwargs.get("src")
            file_findings.append(Finding(
                "ddk_prebuilt_module:%s" % name, "note",
                "ddk_prebuilt_module %r ships a prebuilt .ko (src=%s): keep "
                "the .ko out of Kbuild or add it to a prebuilt objects list"
                % (name, src.value if src is not None and src.kind == "str"
                   else "<rule>"), node.line, C_MEDIUM))
        elif fn == "ddk_prebuilt_object":
            src = node.kwargs.get("src")
            file_findings.append(Finding(
                "ddk_prebuilt_object:%s" % name, "note",
                "ddk_prebuilt_object %r: link with <mod>-y += %s.o"
                % (name, name), node.line, C_MEDIUM))
        elif fn == "ddk_uapi_headers":
            file_findings.append(Finding(
                "ddk_uapi_headers:%s" % name, "note",
                "ddk_uapi_headers %r: UAPI headers, no object line; keep "
                "them under include/uapi for Kbuild" % name, node.line,
                C_MEDIUM))

    # Library pass (objects link into the dependent's -y group).
    libraries = {}
    lib_notes = {}
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        nm = node.kwargs.get("name")
        if fn != "ddk_library":
            continue
        if nm is None or nm.kind != "str":
            continue
        lname = nm.value
        srcs_val = r.value_of(node.kwargs.get("srcs"), "srcs")
        lits, labels, _ = _src_elems(srcs_val)
        objs = [_obj_name(s) for s in lits if is_src(s)]
        libraries[lname] = objs
        lib_notes[lname] = Finding(
            "ddk_library:%s" % lname, "note",
            "ddk_library %r is not a standalone .ko; its objects (%s) link "
            "into the module that lists it in deps"
            % (lname, " ".join(objs) or "<unresolved>"), node.line, C_MEDIUM)

    # Module pass.
    for st in pf.calls:
        node = st.node
        fn = node.value.value if node is not None and node.value is not None \
            and node.value.kind == "name" else ""
        if fn not in ("ddk_module", "ddk_submodule"):
            continue
        nm = node.kwargs.get("name")
        name = nm.value if nm is not None and nm.kind == "str" else "<anon>"
        mod = ModIR(name, fn, node.line)
        emit_module(ctx, mod, node, fn)

        # Attach any ddk_library deps referenced by this module: DDK injects
        # the library's objects into the dependent module's link group.
        lib_names = set(libraries)
        for label in [l for l, _ in mod.deps]:
            cand = label[1:] if label.startswith(":") else None
            if cand is None and "/" in label:
                cand = label.split(":")[-1]
            if cand in lib_names:
                objs = libraries[cand]
                if objs:
                    mod.unconditional = _dedup(mod.unconditional + objs)
                    mod.findings.append(lib_notes[cand])
                    mod.deps = [d for d in mod.deps if d[0] != label]

        # EL2 / pkvm note
        if fn == "ddk_submodule":
            mod.findings.append(Finding(
                "rule", "lossy",
                "ddk_submodule: discouraged in DDK and not a distinct Kbuild "
                "concept -- emitted as its own obj-m module", node.line,
                C_MEDIUM))
        mod.findings.extend([f for f in r.findings])
        r.findings = []
        # Library objects are appended to mod.unconditional above, so the
        # -y list must be rendered only after that pull-in has happened.
        render_module(mod, ctx)
        validate_module(mod)
        # Two ddk_module targets that share an `out` .ko would both emit an
        # `obj-m`/`<base>-y` pair with the SAME base name; Kbuild's last
        # assignment wins, silently dropping the earlier target's objects.
        # Detect the collision and record it so the reviewer can split/rename.
        clash = next((m for m in modules if m.obj == mod.obj), None)
        if clash is not None:
            mod.findings.append(Finding(
                "rule", "unrecoverable",
                "collides with ddk_module %r: both emit `%s.o`; Kbuild keeps "
                "only the last -- rename one or merge them"
                % (clash.name, mod.obj), node.line, C_LOW))
            clash.findings.append(Finding(
                "rule", "unrecoverable",
                "collides with ddk_module %r: both emit `%s.o`; Kbuild keeps "
                "only the last -- rename one or merge them"
                % (mod.name, mod.obj), clash.line, C_LOW))
        modules.append(mod)

    consumed = set()
    for m in modules:
        for f in m.findings:
            for lname in lib_notes:
                if lname in f.detail:
                    consumed.add(lname)
    for lname in sorted(lib_notes):
        if lname not in consumed:
            file_findings.append(lib_notes[lname])

    file_findings.extend(r.findings)
    return modules, ctx, file_findings


# ---------------------------------------------------------------------------
# Rendering whole files
# ---------------------------------------------------------------------------

def _module_ccflags(mod):
    """All ccflags payloads a module wants (assignment prefix stripped)."""
    out = []
    for ln in mod.lines:
        if ln.kind == "ccflags":
            out.append(_flag_payload(ln.text))
    return out


def _module_ccflags_payloads(mod):
    return _module_ccflags(mod)


def _flag_payload(text):
    """Strip a leading `ccflags-y += ` / `<obj>-y += ` assignment from a line."""
    for marker in ("ccflags-y += ", "-y += "):
        idx = text.find(marker)
        if idx != -1:
            return text[idx + len(marker):]
    return text


def file_ccflags(mods):
    """Group flag fragments with module scope, keeping text unique per group."""
    frags = []          # [(scope, payload, conf, origin)]
    for m in mods:
        for ln in m.lines:
            if ln.kind != "ccflags":
                continue
            frags.append((m.obj, _flag_payload(ln.text), ln.conf, ln.origin))

    values_in_order = []
    for _, text, _, _ in frags:
        if text not in values_in_order:
            values_in_order.append(text)
    # A single module in the file has no collision to avoid: use plain
    # ccflags-y, which is what the original Kbuild did.
    if len(mods) <= 1 or len(values_in_order) <= 1:
        return [(_wrap_ccflags("ccflags-y += ", values_in_order), C_HIGH)]

    # Deterministic: values used by more than one module go to the shared
    # ccflags-y line (assigned once, so += is safe); module-specific values
    # become <mod>-y += lines.
    shared = []
    per_mod = {}
    for text in values_in_order:
        users = [m for m in mods
                 if text in _module_ccflags_payloads(m)]
        if len(users) > 1:
            shared.append(text)
        else:
            per_mod.setdefault(users[0].obj if users else "_", []).append(text)

    out = []
    if shared:
        out.append((_wrap_ccflags("ccflags-y += ", shared), C_HIGH))
    for obj in mods:
        texts = per_mod.get(obj.obj)
        if texts:
            out.append((_wrap_ccflags(obj.obj + "-y += ", texts), C_HIGH))
    # modules that only use shared flags still need no extra line
    return out


def _wrap_ccflags(prefix, texts):
    """Join flag fragments under `prefix`, wrapped to 80 columns.

    The fragments may already carry continuation backslashes (a .bzl built the
    string with `\\`); those are not flags, so normalise to plain whitespace
    before re-wrapping.
    """
    toks = []
    for t in texts:
        toks.extend(t.replace("\\", " ").split())
    return "\n".join(_wrap_assign(prefix, toks))


# ---------------------------------------------------------------------------
# Rendering whole files: Kbuild, Makefile shim, legacy variant
# ---------------------------------------------------------------------------

def render_kbuild(build_path, mods, ctx, file_findings, opts, label_suffix=""):
    """Render one Kbuild file for a BUILD.bazel package."""
    lines = []
    pkg = os.path.dirname(build_path)
    rel = os.path.relpath(build_path, opts.repo_root) if opts.repo_root \
        else build_path

    conf = max([m.confidence() for m in mods] or [C_UNKNOWN])
    lines.append(BANNER)
    lines.append("#")
    lines.append("# Source:      %s" % rel.replace(os.sep, "/"))
    lines.append("# Package:     %s" % (os.path.basename(pkg) or "."))
    _append_comment_list(
        lines, "# Modules:     %d " % len(mods),
        [m.obj for m in mods], open_with="(", close_with=")")
    lines.append("# Confidence:  %s" % CONF_NAME[conf])
    lines.append("#")
    lines.append("# Per-module confidence (min over emitted lines):")
    for m in mods:
        mark = "  " if build_output_valid(m)[0] else "!!"
        lines.append("# %s %-28s %-8s %d srcs" %
                     (mark, m.obj, CONF_NAME[m.confidence()],
                      len([s for s in m.unconditional if is_src(s)])))
    lossy = [f for f in file_findings if f.kind in ("unrecoverable", "lossy")]
    for m in mods:
        lossy.extend([f for f in m.findings
                      if f.kind in ("unrecoverable", "lossy")])
    if lossy:
        lines.append("#")
        lines.append("# LOSSY / UNRECOVERABLE (must be completed by hand):")
        for f in lossy:
            lines.extend(_wrap_comment(
                "#   - [%s] %s: %s" % (f.kind, f.path, f.detail)))
    # Constructs the akita reference corpus uses that a ddk_module simply
    # cannot express.  Named explicitly so nothing is silently dropped.
    lines.append("#")
    lines.append("# NOT EXPRESSIBLE in DDK (add by hand if needed):")
    lines.append("#   subdir-ccflags-y   -- propagates flags into recursed "
                 "subdirs")
    lines.append("#   GCOV_PROFILE_*.o   -- per-object coverage, no DDK "
                 "equivalent")
    lines.append("#   CFLAGS_<file>.o    -- per-file flags; DDK copts are "
                 "whole-target")
    lines.append("")

    # Local Kconfig comment
    kcfg = [m for m in mods if m.kconfig]
    if kcfg:
        lines.append("# Local Kconfig: %s (kept in the DDK target; copy the "
                     "entries back here)" % kcfg[0].kconfig)
        lines.append("")

    # Exported UAPI headers -> `headers-y` (the original Kbuild idiom, e.g.
    # kernel-akita/.../aoc/Kbuild:23 `headers-y := uapi/aoc.h`).
    hdr_line = _exported_headers_line(ctx, pkg)
    if hdr_line:
        lines.append("# Exported headers (from ddk_headers):")
        lines.append(hdr_line)
        lines.append("")

    # Subdirectory modules.  DDK is flat (one .ko per target), so a subdir
    # module has its own generated Kbuild; the parent needs an explicit
    # `obj-$(CONFIG_X) += <subdir>/` to recurse into it -- the construct the
    # akita corpus uses (e.g. gpu/mali_kbase/Kbuild).  DDK cannot express the
    # recursion, so point the reviewer at exactly what to add.
    subdirs = _subdir_modules(pkg)
    if subdirs:
        lines.append("# ---- subdirectory modules (add these by hand) --------")
        lines.append("# DDK builds each subdir as its own target; classic Kbuild")
        lines.append("# needs an explicit recursion line per subdir:")
        for sd in subdirs:
            lines.append("# %s-$(CONFIG_<X>) += %s/"
                         % (os.path.basename(pkg) or "obj", sd))
        lines.append("")

    # Shared flags
    flag_lines = file_ccflags(mods)
    if len(mods) > 1:
        lines.append("# ---- compiler flags --------------------------------------")
    for text, c in flag_lines:
        if text:
            lines.append(text)
    if mods and len(mods) > 1:
        lines.append("")

    # Objects
    lines.append("# ---- modules ---------------------------------------------")
    for m in mods:
        lines.append("")
        for ln in m.lines:
            if ln.kind == "ccflags":
                continue
            if ln.kind in ("comment", "note"):
                lines.append(ln.text)
            else:
                lines.append(ln.text)

    # EXTRA_SYMBOLS
    extras = []
    for m in mods:
        for key in m.extras:
            if key not in extras:
                extras.append(key)
    if extras:
        lines.append("")
        lines.append("# ---- cross-module symbol dependencies -------------------")
        for key in extras:
            lines.append("EXTRA_SYMBOLS += $(call module_syms,%s)" % key)

    lines.append("")
    if label_suffix:
        lines.append("# NOTE: this file was written as %s because a Kbuild "
                     "already exists." % ("Kbuild" + label_suffix))
        lines.append("")
    # Final pass: soft-wrap any remaining over-long comment line to the kernel's
    # 80-column limit.  Emitters produce `# TODO(manual): ...` and `# Source:`
    # lines whose text length depends on user paths, so wrap centrally rather
    # than at each call site.  Generated statements (ccflags/obj/-y) are already
    # wrapped by their emitters; EXTRA_SYMBOLS are individual += statements and
    # match how the reference Makefiles write them.
    lines = _rewrap_comments(lines)
    return "\n".join(lines) + "\n"


def _rewrap_comments(lines, limit=80):
    """Wrap every `#` comment line longer than `limit`.

    Continuation lines stay comments (so the file remains valid Kbuild) and are
    indented under the text.
    """
    out = []
    for ln in lines:
        stripped = ln.lstrip()
        if len(ln) > limit and stripped.startswith("#") and \
                not stripped.startswith("#!"):
            out.extend(_wrap_comment(ln, limit=limit))
        else:
            out.append(ln)
    return out


def _exported_headers_line(ctx, pkg):
    """`headers-y := uapi/*.h` for the package's exported uapi headers.

    Ground truth: kernel-akita/.../aoc/Kbuild has `headers-y := uapi/aoc.h`,
    matching the yoga `ddk_headers(hdrs = [..., "uapi/*.h"])`.  Only uapi/
    headers are exported this way; ordinary private headers are not.
    """
    found = []
    for _name, (fn, node) in sorted(ctx.headers_targets.items()):
        if fn != "ddk_headers" or node is None:
            continue
        for h in _str_list_unsafe(node.kwargs.get("hdrs")) + \
                _glob_patterns(node.kwargs.get("hdrs")):
            if "uapi/" in h and h not in found:
                found.append(h)
    if not found:
        return ""
    # A glob like uapi/*.h stays a glob (Kbuild accepts it in headers-y).
    return "headers-y += %s" % " ".join(sorted(found))


def _subdir_modules(pkg):
    """Immediate subdirectories that carry their own ddk_module BUILD.bazel."""
    try:
        entries = sorted(os.listdir(pkg))
    except OSError:
        return []
    out = []
    for name in entries:
        sub = os.path.join(pkg, name)
        if not os.path.isdir(sub):
            continue
        b = os.path.join(sub, "BUILD.bazel")
        if os.path.isfile(b) and build_has_ddk(b):
            out.append(name)
    return out


def _glob_patterns(node):
    """String patterns from a glob(...) node, or [] if not a glob."""
    if node is None or getattr(node, "kind", None) != "call":
        return []
    callee = node.value
    if callee is None or getattr(callee, "kind", None) != "name" or \
            callee.value != "glob":
        return []
    out = []
    for a in node.args:
        if getattr(a, "kind", None) == "list":
            for e in a.args:
                if getattr(e, "kind", None) == "str":
                    out.append(e.value)
        elif getattr(a, "kind", None) == "str":
            out.append(a.value)
    return out


def render_makefile(dirpath, mods, ctx=None):
    """Makefile shim for the GKI out-of-tree build.

    Modelled on the surviving original Makefiles in the kernel-akita corpus
    (e.g. amplifiers/cs35l45/Makefile, hdcp/samsung/Makefile), which all share
    the same scaffolding:

        KERNEL_SRC ?= /lib/modules/$(shell uname -r)/build
        M ?= $(shell pwd)
        KBUILD_OPTIONS += CONFIG_FOO=m ...
        EXTRA_SYMBOLS += ...
        [include $(ROOT_DIR)/.../soc/gs/Makefile.include]
        modules modules_install clean compile_commands.json:
            $(MAKE) -C $(KERNEL_SRC) M=$(M) W=1 \
            $(KBUILD_OPTIONS) EXTRA_CFLAGS="..." \
            KBUILD_EXTRA_SYMBOLS="$(EXTRA_SYMBOLS)" $(@)

    None of that is recorded in a ddk_module, so it is emitted as boilerplate
    plus whatever IS recoverable (the enable symbols -> KBUILD_OPTIONS, and the
    soc/gs Makefile.include dependency).
    """
    lines = []
    lines.append(BANNER)
    lines.append("# Source:      %s/Makefile shim"
                 % (os.path.basename(dirpath) or "."))
    lines.append("#")
    lines.append("# Thin forwarder: modules / modules_install / clean are handed")
    lines.append("# to the real kbuild.  Module content lives in Kbuild.")
    lines.append("")
    # KERNEL_SRC / M carry `?=` so an outer build system can override them,
    # matching every original Makefile in the reference corpus.
    lines.append("KERNEL_SRC ?= /lib/modules/$(shell uname -r)/build")
    lines.append("M ?= $(shell pwd)")
    lines.append("")
    lines.append("KCFLAGS ?=")
    lines.append("")

    # KBUILD_OPTIONS: the recovered module-enable symbols.  Original Makefiles
    # carry ONE package-wide `KBUILD_OPTIONS += CONFIG_A=m CONFIG_B=m ...`
    # list, not a per-module gate, so collect every symbol the package's
    # Kconfig declares (plus any per-module match) rather than trying to
    # attribute each one to a specific .o.
    symbols = []
    if ctx is not None:
        for sym in _package_enable_symbols(mods, ctx):
            if sym not in symbols:
                symbols.append(sym)
    if symbols:
        lines.append("# Module enable symbols (recovered from the package "
                     "Kconfig).")
        lines.append("# The out-of-tree build needs these so obj-$(CONFIG_...)"
                     " resolves.")
        for s in symbols:
            lines.append("KBUILD_OPTIONS += %s=m" % s)
        lines.append("")
    else:
        lines.append("# KBUILD_OPTIONS: no module enable symbol could be "
                     "recovered;")
        lines.append("# add `CONFIG_<X>=m` here so the obj-$(CONFIG_<X>) lines "
                     "resolve.")
        lines.append("")

    # soc/gs Makefile.include supplies the shared -I paths and EXTRA_SYMBOLS.
    if ctx is not None and _depends_on_soc_gs(mods):
        lines.append("include "
                     "$(ROOT_DIR)/private/google-modules/soc/gs/Makefile.include")
        lines.append("")

    lines.append("module_syms = $(wildcard "
                 "$(COMMON_OUT_DIR)/private/google-modules/$(1)Module.symvers)")
    lines.append("")
    lines.append("# EXTRA_SYMBOLS are emitted in Kbuild; keep any hand-written")
    lines.append("# additions above this line.")
    lines.append("")
    lines.append("modules modules_install clean compile_commands.json:")
    lines.append("\t$(MAKE) -C $(KERNEL_SRC) M=$(M) W=1 \\")
    lines.append("\t$(KBUILD_OPTIONS) EXTRA_CFLAGS=\"$(EXTRA_CFLAGS)\" \\")
    lines.append("\tKBUILD_EXTRA_SYMBOLS=\"$(EXTRA_SYMBOLS)\" $(@)")
    lines.append("")
    lines.append(".PHONY: modules modules_install clean compile_commands.json")
    lines.append("")
    return "\n".join(lines)


def _package_enable_symbols(mods, ctx):
    """All module-enable CONFIG_ symbols this package's Kconfig/Makefile names.

    Original (akita) Makefiles carry a single package-wide
    `KBUILD_OPTIONS += CONFIG_A=m CONFIG_B=m ...`, so the shim wants the whole
    set, not a per-module attribution.  Preference order:

      1. per-module matched symbols (unambiguous, from `_module_enable_symbol`);
      2. every `config X` declared by the sibling Kconfig, but ONLY when that
         file also declares a symbol matching a module in this package -- a
         Kconfig holding unrelated feature symbols (AOC_V1/MBU, DEBUG_FS) must
         not be promoted to a module gate;
      3. `KBUILD_OPTIONS` from an enclosing Makefile.
    """
    base = os.path.dirname(ctx.build_path)
    matched = []
    for m in mods:
        sym, _o = _module_enable_symbol(m, ctx)
        if sym and sym not in matched:
            matched.append(sym)
    if matched:
        return matched

    # 2. Kconfig: keep only symbols that are plausibly a module *enable* gate.
    #    An enable symbol is either the exact module stem, or the module stem
    #    plus a driver/module suffix (aoc_char_dev -> AOC_CHAR_DRIVER).  All
    #    other declared symbols (AOC_V1, AOC_MBU, AOC_USB_AUDIO_OFFLOAD) are
    #    feature/variant configs, not module gates.
    for kname in ("Kconfig", "Kconfig.ext"):
        text = _read_text(os.path.join(base, kname))
        if not text:
            continue
        declared = ["CONFIG_" + s for s in _kconfig_symbols(text)]
        norm = lambda s: re.sub(r"[^A-Z0-9]", "", s.upper())
        mod_stems = sorted({norm(m.name) for m in mods} |
                           {norm(m.obj) for m in mods})
        out = []
        for sym in declared:
            stem = norm(sym[len("CONFIG_"):])
            # exact module name
            if stem in mod_stems:
                out.append(sym)
                continue
            # module stem + _DRIVER/_MODULE, where the module stem is a proper
            # prefix at a token boundary (aocchar + DRIVER).
            base_stem = stem
            for suf in ("DRIVER", "MODULE"):
                if base_stem.endswith(suf):
                    base_stem = base_stem[:-len(suf)]
                    break
            if base_stem in mod_stems:
                out.append(sym)
        if out:
            return out

    # 3. enclosing Makefile
    for root in (base, os.path.dirname(base)):
        text = _read_text(os.path.join(root, "Makefile"))
        if not text:
            continue
        found = []
        for chunk in re.findall(
                r"KBUILD_OPTIONS\s*\+?=\s*((?:[^\n\\]|\\\n)+)", text):
            for sym in re.findall(r"\b(CONFIG_[A-Z0-9_]+)\b", chunk):
                if sym not in found:
                    found.append(sym)
        if found:
            return found
    return []


def _depends_on_soc_gs(mods):
    """True if any module depends on the soc/gs package (its Makefile.include
    supplies shared include paths and EXTRA_SYMBOLS)."""
    for m in mods:
        for label in getattr(m, "deps", []):
            lab = label[0] if isinstance(label, tuple) else label
            if "google-modules/soc/gs" in lab:
                return True
    return False


def render_legacy_kbuild(build_path, mods, ctx, label):
    """Compute-fingerprint style multi-module Kbuild (Kbuild.<label>)."""
    lines = []
    lines.append("# AUTO-GENERATED by ddk2kbuild.py from BUILD.bazel "
                 "-- REVIEW REQUIRED")
    lines.append("#")
    lines.append("# Compute-fingerprint (multi-module) variant.  The fingerprint")
    lines.append("# suffix is the directory's Kbuild-based module set, so")
    lines.append("# `obj-$(DRIVER_TYPE)` in the legacy Makefile resolves.")
    lines.append("")
    for m in mods:
        lines.append("# %s  (confidence: %s)" % (m.obj, CONF_NAME[m.confidence()]))
    lines.append("")
    for m in mods:
        for ln in m.lines:
            if ln.kind == "ccflags":
                continue
            lines.append(ln.text)
        lines.append("")
    return "\n".join(lines)


