# Reporting
# ---------------------------------------------------------------------------

def print_text_report(results, opts):
    total = 0
    by_conf = {C_HIGH: 0, C_MEDIUM: 0, C_LOW: 0, C_UNKNOWN: 0}
    invalid = 0
    out = []
    for res in results:
        rel = os.path.relpath(res["build_path"], opts.repo_root) \
            if opts.repo_root else res["build_path"]
        out.append("== %s" % rel.replace(os.sep, "/"))
        if not res["modules"]:
            out.append("   (no ddk_module / ddk_submodule)")
        for m in res["modules"]:
            total += 1
            c = CONF_ORDER[m["confidence"]]
            by_conf[c] += 1
            if not m["valid"]:
                invalid += 1
            out.append("   %-30s out=%-28s srcs=%-4d %-7s%s"
                       % (m["name"], m["out"], m["n_srcs"], m["confidence"],
                          "" if m["valid"] else "  INVALID"))
            for f in m["findings"]:
                if f["kind"] in ("unrecoverable", "lossy"):
                    out.extend(_wrap_report(
                        "       [%s] %s: %s"
                        % (f["kind"], f["path"], f["detail"])))
            for p in m.get("problems", []):
                out.extend(_wrap_report("       [invalid] %s" % p))
        for f in res["file_findings"]:
            fd = f.as_dict() if isinstance(f, Finding) else f
            out.extend(_wrap_report(
                "   [%s] %s: %s" % (fd["kind"], fd["path"], fd["detail"])))
    out.append("")
    out.append("---- summary ----")
    out.append("files scanned : %d" % len(results))
    out.append("modules       : %d" % total)
    out.append("  high        : %d" % by_conf[C_HIGH])
    out.append("  medium      : %d" % by_conf[C_MEDIUM])
    out.append("  low         : %d" % by_conf[C_LOW])
    out.append("  unknown     : %d" % by_conf[C_UNKNOWN])
    out.append("invalid-kbuild : %d" % invalid)
    out.append("files written : %d" % sum(1 for r in results if r["written"]))
    sys.stdout.write("\n".join(out) + "\n")


def print_json_report(results, opts):
    payload = [
        {
            "build_path": os.path.relpath(r["build_path"], opts.repo_root)
            if opts.repo_root else r["build_path"],
            "written": r["written"],
            "kbuild_path": r["kbuild_path"],
            "makefile_path": r["makefile_path"],
            "modules": r["modules"],
            "file_findings": [f.as_dict() if isinstance(f, Finding) else f
                              for f in r["file_findings"]],
            "warnings": r["warnings"],
        }
        for r in results
    ]
    sys.stdout.write(json.dumps(payload, indent=2, sort_keys=True) + "\n")


