# Driver
# ---------------------------------------------------------------------------

BUILD_NAMES = ("BUILD.bazel", "BUILD")


def walk_build_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames
                             if d not in (".git", "bazel-bin", "bazel-out",
                                          "bazel-testlogs", "__pycache__",
                                          "node_modules"))
        for fn in sorted(filenames):
            if fn in BUILD_NAMES:
                found.append(os.path.join(dirpath, fn))
    return found


def build_has_ddk(path):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError:
        return False
    return ("ddk_module" in text) or ("ddk_submodule" in text)


def build_has_config_rule(path):
    """True if the file carries a config rule (device_build/ddk_config).

    These files have no ddk_module, so the normal walk skips them -- but
    --config must still read them to reconstruct the device config chain.
    """
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError:
        return False
    return ("device_build(" in text) or ("ddk_config(" in text) or \
        ("kconfig_exts" in text)


def find_repo_root(start):
    """Work out the Bazel workspace root that `//...` labels resolve against.

    The tree is meant to be converted from inside a kernel checkout:

        <kernel_root>/                 <- the Bazel workspace named `common`
            BUILD.bazel                <- defines //common:all_headers_aarch64
            private/                   <- //private/...
            google-modules/            <- modules to convert
            google-devices/

    so a `//common:X` label means `<kernel_root>/BUILD.bazel` and `//private/...`
    means `<kernel_root>/private/...`.  Walk up looking for that root; fall back
    to the nearest ancestor that looks like any sort of tree root.
    """
    cur = os.path.abspath(start)
    if os.path.isfile(cur):
        cur = os.path.dirname(cur)
    fallback = None
    while True:
        has_build = os.path.isfile(os.path.join(cur, "BUILD.bazel"))
        has_private = os.path.isdir(os.path.join(cur, "private"))
        # The kernel-root shape: a top-level BUILD.bazel that also owns private/
        # (or the google-modules/google-devices module trees).
        if has_build and has_private:
            return cur
        if has_build and (
                os.path.isdir(os.path.join(cur, "google-modules")) or
                os.path.isdir(os.path.join(cur, "google-devices"))):
            return cur
        if fallback is None and (has_private or
                                 os.path.isfile(os.path.join(cur, "WORKSPACE")) or
                                 os.path.isfile(os.path.join(cur, "MODULE.bazel")) or
                                 os.path.isdir(os.path.join(cur, "build", "kernel"))):
            fallback = cur
        parent = os.path.dirname(cur)
        if parent == cur:
            return fallback or os.path.abspath(
                start if os.path.isdir(start) else os.path.dirname(start))
        cur = parent


def process_build(build_path, opts):
    """Convert one BUILD.bazel.  Never raises out of here."""
    loader = BzlLoader(opts.repo_root, opts.verbose)
    res = {
        "build_path": build_path,
        "modules": [],
        "file_findings": [],
        "warnings": [],
        "written": False,
        "kbuild_path": None,
        "makefile_path": None,
        "text": "",
        "makefile_text": "",
    }
    try:
        with open(build_path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError as exc:
        res["warnings"].append("cannot read %s: %s" % (build_path, exc))
        return res

    pf = parse_text(text, build_path)
    res["warnings"].extend(pf.warnings)
    for st in pf.error_stmts:
        res["file_findings"].append(Finding(
            "parse", "unrecoverable",
            "could not parse a statement; raw text kept for manual review: %s"
            % (st.raw[:200] or "<empty>"), st.line))
    if pf.error_stmts:
        todo = ["# TODO(manual): %d top-level statement(s) in %s could not be "
                "parsed:" % (len(pf.error_stmts),
                             os.path.basename(build_path))]
        for st in pf.error_stmts:
            todo.append("#   line %d: %s" % (st.line, (st.raw or "")[:160]))
        res["parse_todo"] = "\n".join(todo)
    else:
        res["parse_todo"] = ""

    has_ddk = build_has_ddk(build_path)
    if not has_ddk:
        # No module target: the file may still carry device/config rules that
        # --config must reconstruct (device_build / ddk_config).
        if opts.config:
            _process_config(build_path, pf, res, opts)
            if opts.stdout and res.get("config_text"):
                sys.stdout.write(res["config_text"])
        return res

    mods, ctx, file_findings = collect_modules(build_path, pf, loader, opts)
    res["file_findings"].extend(file_findings)
    res["modules"] = []
    for m in mods:
        summary = m.summary()
        ok, problems = build_output_valid(m)
        summary["problems"] = problems
        res["modules"].append(summary)

    # ---- config reconstruction (independent of ddk_module presence) ----
    if opts.config:
        _process_config(build_path, pf, res, opts)

    if not mods:
        # A device/config-only file still has config output to emit.
        if opts.stdout and res.get("config_text"):
            sys.stdout.write(res["config_text"])
        return res

    res["text"] = render_kbuild(build_path, mods, ctx, file_findings, opts)
    if res["parse_todo"]:
        res["text"] = res["text"].replace(BANNER, BANNER + "\n" +
                                          res["parse_todo"], 1)
    res["makefile_text"] = render_makefile(os.path.dirname(build_path), mods,
                                           ctx)

    # ---- gate + write -------------------------------------------------
    # Confidence is "higher value == less trustworthy", so a module passes the
    # gate when its level is at or better than the threshold.
    limit = CONF_ORDER[opts.write_min_confidence]
    low = [m for m in mods if m.confidence() > limit]
    invalid = [m for m in mods if not build_output_valid(m)[0]]

    if opts.stdout:
        sys.stdout.write(res["text"])
        if res.get("config_text"):
            sys.stdout.write(res["config_text"])
        if opts.makefile:
            sys.stdout.write("\n# ---- Makefile shim ----\n")
            sys.stdout.write(res["makefile_text"])
        res["written"] = True
        return res

    if opts.dry_run:
        return res

    if invalid and not opts.allow_lossy:
        res["warnings"].append(
            "%s: %d module(s) produced invalid Kbuild -- not written "
            "(pass --allow-lossy to override): %s"
            % (os.path.relpath(build_path, opts.repo_root),
               len(invalid), ", ".join(m.name for m in invalid)))
        return res
    if low and not opts.allow_lossy:
        res["warnings"].append(
            "%s: %d module(s) below --write-min-confidence=%s -- not written "
            "(pass --allow-lossy to override): %s"
            % (os.path.relpath(build_path, opts.repo_root), len(low),
               opts.write_min_confidence, ", ".join(m.name for m in low)))
        return res

    outdir = os.path.dirname(build_path)
    if opts.out:
        rel = os.path.relpath(build_path, opts.repo_root) if opts.repo_root \
            else os.path.basename(build_path)
        outdir = os.path.join(opts.out, os.path.dirname(rel))
    elif getattr(opts, "tree_run", False):
        # Tree-wide write IN PLACE -- the normal workflow: the generated Kbuild
        # belongs next to its BUILD.bazel so the kernel build picks it up.  The
        # safety net is below: an existing hand-written Kbuild/Makefile is never
        # overwritten (it is redirected to *.generated).  Say so once, not per
        # file.
        global _INPLACE_NOTED
        if not _INPLACE_NOTED:
            _INPLACE_NOTED = True
            info_msg("writing Kbuild beside each BUILD.bazel; an existing "
                     "Kbuild/Makefile is preserved (output goes to "
                     "*.generated instead).  Pass --out DIR to write elsewhere.")

    kbuild_path = os.path.join(outdir, "Kbuild")
    shim_name = "Kbuild.generated" if opts.legacy_kbuild else None
    legacy_path = None
    if os.path.exists(kbuild_path):
        kbuild_path = os.path.join(outdir, "Kbuild.generated")
        warn_msg("%s: Kbuild already exists; writing %s instead"
                 % (os.path.relpath(outdir, opts.repo_root), "Kbuild.generated"))
    if shim_name:
        legacy_path = os.path.join(outdir, shim_name)
    try:
        if not os.path.isdir(outdir):
            os.makedirs(outdir)
        _write_file(kbuild_path, res["text"])
        res["kbuild_path"] = kbuild_path
        res["written"] = True
        if legacy_path:
            _write_file(legacy_path, render_legacy_kbuild(
                build_path, mods, ctx, os.path.basename(outdir)))
        if opts.makefile:
            mf = os.path.join(outdir, "Makefile")
            if os.path.exists(mf):
                mf = os.path.join(outdir, "Makefile.generated")
                warn_msg("%s: Makefile already exists; writing Makefile.generated"
                         % os.path.relpath(outdir, opts.repo_root))
            _write_file(mf, res["makefile_text"])
            res["makefile_path"] = mf
    except OSError as exc:
        res["warnings"].append("cannot write %s: %s" % (outdir, exc))
        res["written"] = False
    return res


def _write_file(path, content):
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(content)


# ---------------------------------------------------------------------------
# Self tests (shipped in the tool; the real suite is tests/test_ddk2kbuild.py)
# ---------------------------------------------------------------------------

def _st_convert(text, tmpname="BUILD.bazel"):
    """Convert in-memory source with a fake repo layout."""
    opts = Opts()
    opts.repo_root = "/virtual"
    pf = parse_text(text, "/virtual/pkg/" + tmpname)
    loader = BzlLoader("/virtual")
    mods, ctx, ff = collect_modules("/virtual/pkg/" + tmpname, pf, loader, opts)
    return mods, ff


def run_self_tests():
    """Small built-in corpus; returns exit code."""
    failures = []

    def check(label, text, want=(), absent=()):
        mods, ff = _st_convert(text)
        # The blob is the whole generated Kbuild file, not just the module
        # fragments: EXTRA_SYMBOLS and the shared ccflags live at file scope.
        opts = Opts()
        opts.repo_root = "/virtual"
        ctx = RuleContext(None, opts, "/virtual/pkg/BUILD.bazel")
        blob = render_kbuild("/virtual/pkg/BUILD.bazel", mods, ctx, ff, opts)
        for w in want:
            if w not in blob:
                failures.append("%s: missing %r\n--- emitted ---\n%s"
                                % (label, w, blob))
        for a in absent:
            if a in blob:
                failures.append("%s: unexpected %r\n--- emitted ---\n%s"
                                % (label, a, blob))

    # 1. plain multi-source module
    check("multi-src", textwrap.dedent('''
        ddk_module(
            name = "foo",
            out = "foo.ko",
            srcs = ["a.c", "b.c", "h.h"],
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["obj-m += foo.o", "foo-y := a.o b.o h.h"],
         absent=["foo.c", "//common:pkg.c"])

    # 2. single source collapsing
    check("single-src", textwrap.dedent('''
        ddk_module(name = "bar", out = "bar.ko", srcs = ["bar.c"],
                   kernel_build = "//common:kernel_aarch64")
    '''), want=["obj-m += bar.o"], absent=["bar-y :="])

    # 3. self-named source (circular)
    check("self-object", textwrap.dedent('''
        ddk_module(name = "bar", out = "bar.ko", srcs = ["bar.c", "z.c"],
                   kernel_build = "//common:kernel_aarch64")
    '''), want=["obj-m += bar.o", "bar-y := bar.o z.o"], absent=[])

    # 4. conditional_srcs
    check("conditional", textwrap.dedent('''
        ddk_module(
            name = "c", out = "c.ko",
            srcs = ["m.c"],
            conditional_srcs = {"CONFIG_A": {True: ["x.c"]}},
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["obj-m += c.o", "c-$(CONFIG_A) += x.o"])

    # 5. local_defines + copts
    check("defines", textwrap.dedent('''
        ddk_module(
            name = "d", out = "d.ko", srcs = ["m.c"],
            local_defines = ["FOO=1", "BAR"],
            copts = ["-Wall"],
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["ccflags-y += -DFOO=1 -DBAR", "-Wall"])

    # 6. includes
    check("includes", textwrap.dedent('''
        ddk_module(
            name = "e", out = "e.ko", srcs = ["m.c"],
            includes = ["inc"],
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["ccflags-y += -I$(src)/inc"])

    # 7. glob -> TODO, never a fake .c
    check("glob", textwrap.dedent('''
        ddk_module(
            name = "f", out = "f.ko", srcs = ["m.c"] + glob(["**/*.c"]),
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["TODO(manual)", "glob([**/*.c])"])

    # 8. //pkg dep -> EXTRA_SYMBOLS, never a fake .c
    check("cross-dep", textwrap.dedent('''
        ddk_module(
            name = "g", out = "g.ko", srcs = ["m.c"],
            deps = ["//private/google-modules/iif"],
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["EXTRA_SYMBOLS += $(call module_syms,"
                    "private/google-modules/iif/)"],
         absent=["iif.c"])

    # 9. local ddk_headers include resolution
    check("hdrs-target", textwrap.dedent('''
        ddk_headers(name = "hh", hdrs = ["a.h"], includes = ["core"])
        ddk_module(
            name = "h", out = "h.ko", srcs = ["m.c"], deps = [":hh"],
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["ccflags-y += -I$(src)/core"])

    # 10. globals: BUILD-local symbol
    check("local-symbol", textwrap.dedent('''
        _SRCS = ["a.c", "b.c"]
        ddk_module(name = "i", out = "i.ko", srcs = _SRCS,
                   kernel_build = "//common:kernel_aarch64")
    '''), want=["i-y := a.o b.o"])

    # 11. local_defines via symbol
    check("defines-symbol", textwrap.dedent('''
        _DEFS = ["Z=1"]
        ddk_module(name = "j", out = "j.ko", srcs = ["m.c"],
                   local_defines = _DEFS + ["K"],
                   kernel_build = "//common:kernel_aarch64")
    '''), want=["ccflags-y += -DZ=1 -DK"])

    # 12. select -> default + warning, low confidence
    check("select", textwrap.dedent('''
        ddk_module(
            name = "k", out = "k.ko",
            srcs = ["m.c"],
            deps = [":base"] + select({
                ":soc_is_x": ["//pkg:x"],
                "//conditions:default": ["//pkg:d"],
            }),
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["TODO(manual)", "select("])

    # 13. dotted out name
    check("dotted-out", textwrap.dedent('''
        ddk_module(name = "l", out = "malibu.pixel.ko", srcs = ["m.c"],
                   kernel_build = "//common:kernel_aarch64")
    '''), want=["obj-m += malibu_pixel.o"])

    # 14. determinism
    txt = textwrap.dedent('''
        ddk_module(name = "n", out = "n.ko", srcs = ["b.c", "a.c"],
                   kernel_build = "//common:kernel_aarch64")
    ''')
    m1, _ = _st_convert(txt)
    m2, _ = _st_convert(txt)
    b1 = "\n".join(l.text for m in m1 for l in m.lines)
    b2 = "\n".join(l.text for m in m2 for l in m.lines)
    if b1 != b2:
        failures.append("determinism: two runs differ")

    # 15. ddk_library comment, no obj-m for the library
    check("library", textwrap.dedent('''
        ddk_library(name = "lib", srcs = ["x.c"], kernel_build = "//common:kernel_aarch64")
        ddk_module(name = "o", out = "o.ko", srcs = ["m.c"], deps = [":lib"],
                   kernel_build = "//common:kernel_aarch64")
    '''), want=["obj-m += o.o", "x.o"])

    # 16. never crash on garbage
    mods, ff = _st_convert("ddk_module(name = \"z\", srcs = [1, , , ] ###\n")
    if mods is None:
        failures.append("garbage input crashed")

    # 17. cross-package headers label in srcs must not become a .c
    check("headers-label-in-srcs", textwrap.dedent('''
        ddk_module(
            name = "p", out = "p.ko", srcs = ["m.c", "//other:pkg_headers"],
            kernel_build = "//common:kernel_aarch64",
        )
    '''), want=["TODO(manual)", "pkg_headers"],
         absent=["pkg_headers.c", "other.c"])

    if failures:
        for f in failures:
            sys.stderr.write("FAIL: %s\n" % f)
        sys.stderr.write("%d self-test failure(s)\n" % len(failures))
        return 1
    print("self-test: OK")
    return 0


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

class Opts(object):
    def __init__(self):
        self.repo_root = ""
        self.repo_pkg_root = "private/google-modules"
        self.out = None
        self.stdout = False
        self.dry_run = False
        self.write = True
        self.makefile = False
        self.legacy_kbuild = False
        self.walk_globs = False
        self.allow_lossy = False
        self.report = "text"
        self.verbose = False
        self.write_min_confidence = "medium"
        self.suppress_globs = []
        self.config = False
        self.config_scope = "both"
        self.device = None
        self.defconfig_dirs = []
        self.device_files = []
        self.tree_run = False


def build_argparser():
    p = argparse.ArgumentParser(
        prog=TOOL,
        description="Convert Kleaf DDK BUILD.bazel back to Kbuild/Makefile.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=textwrap.dedent("""\
            Mapping (ddk_module -> Kbuild), 1 ddk_module == 1 .ko:
              name/out            -> obj-m += <out-base>.o
              srcs *.c            -> <base>-y := a.o b.o   (headers kept as prereqs)
              srcs :target / //pkg-> never a .c; -I$(src)/... or EXTRA_SYMBOLS
              srcs glob(**.c)     -> TODO(manual) + low confidence
              conditional_srcs    -> <base>-$(CONFIG_X) += foo.o
              local_defines       -> ccflags-y += -DFOO=1
              copts               -> ccflags-y += <flags> (Bazel macros translated)
              includes            -> ccflags-y += -I$(src)/dir
              linux_includes      -> ccflags-y += -I$(srctree)/dir (lossy)
              hdrs/deps :target   -> resolve ddk_headers.includes -> -I$(src)/...
              deps //pkg module   -> EXTRA_SYMBOLS += $(call module_syms,<dir>/)
              kernel_build        -> "# Kernel: <label>" comment
              kconfig/defconfig   -> comment referencing the local file
              select({...})       -> default branch + TODO(manual) + low
            """))
    p.add_argument("path", nargs="?",
                   help="BUILD.bazel file or a directory to walk")
    p.add_argument("--all", metavar="ROOT",
                   help="walk ROOT for BUILD.bazel containing ddk_module")
    p.add_argument("--out", metavar="DIR",
                   help="write generated files under DIR (mirrors the tree)")
    p.add_argument("--stdout", action="store_true",
                   help="print generated files instead of writing")
    p.add_argument("--dry-run", action="store_true",
                   help="do everything except write files")
    p.add_argument("--write", action="store_true", help="write files (default)")
    p.add_argument("--makefile", action="store_true",
                   help="also emit a Makefile shim")
    p.add_argument("--legacy-kbuild", action="store_true",
                   help="also emit Kbuild.<dir> (compute-fingerprint variant)")
    p.add_argument("--walk-globs", action="store_true",
                   help="expand **/*.c globs against the filesystem (medium)")
    p.add_argument("--allow-lossy", action="store_true",
                   help="write low-confidence / invalid-Kbuild modules too")
    p.add_argument("--report", choices=("text", "json"), default="text")
    p.add_argument("--write-min-confidence", default="medium",
                   choices=("high", "medium", "low"),
                   help="refuse to write modules below this confidence")
    p.add_argument("--suppress-glob", action="append", default=[],
                   metavar="PATTERN",
                   help="ignore a glob pattern that is a known no-op")
    p.add_argument("--config", action="store_true",
                   help="also reconstruct the Kconfig/defconfig chain "
                        "(module + device level) into *.generated files")
    p.add_argument("--config-scope", choices=("module", "device", "both"),
                   default="both",
                   help="which config levels --config reconstructs")
    p.add_argument("--device", metavar="NAME", default=None,
                   help="device_build target to include (default: all found)")
    p.add_argument("--defconfig", metavar="DIR", action="append", default=[],
                   help="directory to search for device defconfigs when "
                        "resolving a module's CONFIG_ enable symbol (repeatable; "
                        "searched before the auto-detected device trees)")
    p.add_argument("--repo-root", default=None,
                   help="Bazel workspace root that //... labels resolve "
                        "against (default: autodetect). When converting a "
                        "kernel checkout, this is the KERNEL ROOT -- the dir "
                        "holding BUILD.bazel + private/, so //common:X resolves "
                        "from <root>/BUILD.bazel and //private/... from "
                        "<root>/private/...")
    p.add_argument("--verbose", action="store_true")
    p.add_argument("--self-test", action="store_true")
    return p


def main(argv=None):
    argv = argv if argv is not None else sys.argv[1:]
    args = build_argparser().parse_args(argv)

    if args.self_test:
        return run_self_tests()

    if not args.path and not args.all:
        build_argparser().print_usage(sys.stderr)
        sys.stderr.write("%s: error: need a BUILD.bazel path, a directory, or "
                         "--all ROOT\n" % TOOL)
        return 2

    opts = Opts()
    opts.out = args.out
    opts.stdout = args.stdout
    opts.dry_run = args.dry_run
    opts.makefile = args.makefile
    opts.legacy_kbuild = args.legacy_kbuild
    opts.walk_globs = args.walk_globs
    opts.allow_lossy = args.allow_lossy
    opts.report = args.report
    opts.verbose = args.verbose
    opts.write_min_confidence = args.write_min_confidence
    opts.suppress_globs = args.suppress_glob or []
    opts.config = args.config
    opts.config_scope = args.config_scope
    opts.device = args.device
    opts.defconfig_dirs = [os.path.abspath(d) for d in (args.defconfig or [])]
    opts.tree_run = bool(args.all)

    target = args.all or args.path
    if not os.path.exists(target):
        sys.stderr.write("%s: error: no such path: %s\n" % (TOOL, target))
        return 2

    opts.repo_root = args.repo_root or find_repo_root(target)

    # --defconfig: validate up front so a typo is an error, not a silent
    # fallback to the auto-discovered device trees.
    for d in opts.defconfig_dirs:
        if not os.path.isdir(d):
            sys.stderr.write("%s: error: --defconfig %s: not a directory\n"
                             % (TOOL, d))
            return 2

    files = []
    if args.all or os.path.isdir(target):
        files = [f for f in walk_build_files(target) if build_has_ddk(f)]
        # --config also needs device_build / ddk_config files, which carry no
        # ddk_module, so add them for the device level.
        if opts.config and opts.config_scope in ("device", "both"):
            for f in walk_build_files(target):
                if f in files:
                    continue
                if build_has_config_rule(f):
                    files.append(f)
            files.sort()
        if not files:
            sys.stderr.write("%s: no BUILD.bazel with ddk_module under %s\n"
                             % (TOOL, target))
            return 1
    else:
        files = [target]

    results = []
    for f in files:
        try:
            results.append(process_build(f, opts))
        except Exception as exc:  # pragma: no cover - totality guard
            warn_msg("internal error on %s: %r" % (f, exc))
            if opts.verbose:
                import traceback
                traceback.print_exc()
            results.append({
                "build_path": f, "modules": [], "file_findings": [],
                "warnings": ["internal error: %r" % (exc,)], "written": False,
                "kbuild_path": None, "makefile_path": None, "text": "",
                "makefile_text": "",
            })

    for r in results:
        for w in r["warnings"]:
            warn_msg(w)

    if opts.report == "json":
        print_json_report(results, opts)
    elif not (opts.stdout and len(files) == 1):
        print_text_report(results, opts)
    else:
        print_text_report(results, opts)

    total_invalid = sum(1 for r in results for m in r["modules"]
                        if not m["valid"])
    total_low = sum(1 for r in results for m in r["modules"]
                    if m["confidence"] in ("low", "unknown"))
    if total_invalid and not opts.allow_lossy and not opts.dry_run \
            and not opts.stdout:
        sys.stderr.write("%s: %d invalid-Kbuild module(s); nothing was written "
                         "for those packages (see the report)\n"
                         % (TOOL, total_invalid))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
